-- 남은 23개 활동 추가 + 진도표 연결
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('butterfly-life-cycle','과학','3~4','동물의 한살이','페트병 배추흰나비 관찰통','배추 잎에서 찾은 애벌레를 페트병 집에서 키우며 알, 애벌레, 번데기, 나비로 변하는 한살이를 지켜봐요.','난이도 ★★☆ 보통','만들기 20분 · 관찰 3~4주',array['페트병 자르기는 어른이']::text[],array['페트병']::text[],'assets/img/n_butterfly-life-cycle.jpg',false,'assets/pdf/butterfly-life-cycle.pdf',$json$[{"type": "materials", "note": "애벌레만 구하면 나머지는 집 재료", "rows": [{"name": "2L 투명 페트병", "how": "윗부분을 잘라 내 관찰통으로 써요", "kit": false}, {"name": "양파망이나 거즈", "how": "입구를 덮어 공기는 통하고 애벌레는 못 나가게", "kit": false}, {"name": "배추흰나비 애벌레", "how": "텃밭 배추·케일 잎 뒷면에서 찾거나 관찰 세트로 구해요", "kit": true}, {"name": "싱싱한 배추·케일 잎", "how": "애벌레 먹이. 농약이 묻지 않은 잎이어야 해요", "kit": false}, {"name": "나무젓가락 1개", "how": "번데기가 붙을 자리예요", "kit": false}, {"name": "관찰 일지 도안", "how": "아래에서 내려받아요", "kit": false}], "image": null}, {"type": "steps", "title": "실험 방법", "items": [{"title": "관찰통 만들기", "body": "페트병 윗부분을 잘라 내고, 바닥에 키친타월을 깔아요. 나무젓가락을 비스듬히 세워 넣어요.", "warn": "자르기는 어른이 해요.", "image": null}, {"title": "애벌레 옮기기", "body": "애벌레가 붙은 잎째로 옮겨요. 손으로 직접 잡으면 다칠 수 있어요.", "warn": "", "image": null}, {"title": "입구 덮기", "body": "양파망이나 거즈를 씌우고 고무줄로 묶어요. 햇빛이 바로 드는 곳은 피해요.", "warn": "", "image": null}, {"title": "매일 먹이와 청소", "body": "하루 한 번 시든 잎과 똥을 치우고 새 잎을 넣어요. 잎에 물방울이 많으면 닦아 줘요.", "warn": "", "image": null}, {"title": "관찰 일지 쓰기", "body": "크기, 색, 움직임을 날짜별로 그리고 적어요. 번데기가 되면 건드리지 말고 기다려요.", "warn": "", "image": null}, {"title": "나비 날려 보내기", "body": "나비가 나와 날개가 마르면 밖에 나가 날려 보내 줘요.", "warn": "", "image": null}], "notes": ["애벌레를 구하기 어려우면 다른 곤충의 한살이 영상을 함께 보고, 관찰 일지는 그림 카드로 순서 맞히기를 해도 좋아요."]}, {"type": "questions", "title": "관찰해 봐요", "items": ["애벌레는 허물을 몇 번 벗나요? 벗을 때마다 무엇이 달라지나요?", "번데기일 때는 먹지도 움직이지도 않는데, 안에서는 무슨 일이 생길까요?", "애벌레와 나비는 먹는 것이 어떻게 다를까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["배추흰나비는 알에서 깨어나 애벌레가 되고, 배추 잎을 먹으며 몇 번 허물을 벗고 자라요. 다 자라면 번데기가 되어 한동안 꼼짝하지 않다가, 어느 날 껍질을 뚫고 나비가 되어 나와요. 이렇게 알에서 어른이 되기까지의 과정을 한살이라고 해요."]}, {"label": "부모님께", "paras": ["배추흰나비처럼 알 → 애벌레 → 번데기 → 어른벌레를 거치는 것을 완전 탈바꿈이라고 하고, 번데기 단계가 없는 메뚜기·잠자리 같은 곤충은 불완전 탈바꿈을 합니다. 3학년 '동물의 한살이' 단원의 핵심 비교입니다.", "관찰이 끝나면 반드시 자연으로 돌려보내는 것까지가 활동이라는 점을 함께 이야기해 주세요.", "이렇게 물어보세요: \"사람의 한살이와 나비의 한살이는 무엇이 같고 무엇이 다를까?\""]}]}, {"type": "template", "title": "한살이 관찰 일지", "desc": "날짜별 관찰 칸 8개와 한살이 순서 그림 카드. A4 1장.", "pdf": "assets/pdf/butterfly-life-cycle.pdf"}, {"type": "more", "items": [{"title": "허물 모으기", "body": "벗은 허물을 테이프로 일지에 붙여 크기를 비교해요."}, {"title": "다른 곤충 비교", "body": "개미, 매미, 잠자리의 한살이를 찾아 그림으로 그려요."}, {"title": "한살이 순서 카드", "body": "관찰 일지 그림을 오려 순서 맞히기 놀이를 해요."}]}, {"type": "info", "items": [{"label": "도안", "value": "한살이 관찰 일지 (A4 1장)"}, {"label": "실험 키트", "value": "배추흰나비 애벌레 관찰 세트 (준비 중)"}, {"label": "교육과정 연결", "value": "3~4학년 동물의 한살이 (완전 탈바꿈)"}]}]$json$::jsonb,26) on conflict (slug) do nothing;
update public.topics set activity_slug='butterfly-life-cycle' where band='3~4' and subject='과학' and name='동물의 한살이';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('egg-tray-beans','과학','3~4','식물의 한살이','달걀판 강낭콩 키우기','종이 달걀판에 강낭콩을 심어 싹이 트고 자라는 과정을 날마다 재고 기록해요.','난이도 ★☆☆ 쉬움','심기 20분 · 관찰 4주',array['아이 혼자서도 할 수 있어요']::text[],array['상자']::text[],'assets/img/n_egg-tray-beans.jpg',false,'assets/pdf/egg-tray-beans.pdf',$json$[{"type": "materials", "note": "씨앗만 있으면 돼요", "rows": [{"name": "종이 달걀판", "how": "칸마다 흙을 담아 작은 화분으로 써요", "kit": false}, {"name": "강낭콩 6~8알", "how": "마트에서 파는 마른 강낭콩도 싹이 터요", "kit": true}, {"name": "흙", "how": "화분 흙이나 마당 흙", "kit": false}, {"name": "분무기나 컵", "how": "물 주기용", "kit": false}, {"name": "자", "how": "자란 키를 재요", "kit": false}, {"name": "키 기록표 도안", "how": "아래에서 내려받아요", "kit": false}], "image": null}, {"type": "steps", "title": "실험 방법", "items": [{"title": "콩 불리기", "body": "강낭콩을 하룻밤 물에 담가 불려요. 몇 알은 그대로 두고 비교해도 좋아요.", "warn": "", "image": null}, {"title": "심기", "body": "달걀판 칸에 흙을 채우고 콩을 손가락 한 마디 깊이로 심어요. 칸마다 번호를 적어요.", "warn": "", "image": null}, {"title": "물 주기", "body": "흙이 마르지 않게 하루 한 번 물을 줘요. 달걀판 아래에 쟁반을 받쳐요.", "warn": "", "image": null}, {"title": "싹 관찰하기", "body": "뿌리, 떡잎, 본잎이 나오는 순서를 관찰하고 날짜를 적어요.", "warn": "", "image": null}, {"title": "화분으로 옮기기", "body": "본잎이 나오면 달걀판 칸째로 잘라 큰 화분이나 페트병 화분에 옮겨 심어요. 종이가 흙 속에서 썩어 없어져요.", "warn": "", "image": null}], "notes": []}, {"type": "questions", "title": "관찰해 봐요", "items": ["뿌리와 줄기 중 무엇이 먼저 나오나요?", "떡잎은 자라면서 어떻게 변하나요?", "햇빛이 드는 칸과 그늘진 칸의 강낭콩은 어떻게 다르게 자라나요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["씨앗 속에는 아기 식물과 처음 먹을 양분이 들어 있어요. 물을 먹으면 씨앗이 부풀고 뿌리가 먼저 나와요. 떡잎은 씨앗 속 양분 주머니라서, 본잎이 자라면 점점 쪼그라들어요."]}, {"label": "부모님께", "paras": ["3~4학년 '식물의 한살이'는 씨앗이 싹 트고 자라 꽃이 피고 열매를 맺어 다시 씨앗이 되는 과정을 다룹니다. 강낭콩은 싹이 빨리 트고 떡잎이 커서 관찰하기 좋아 교과서에서도 많이 쓰입니다.", "키를 매일 재서 기록표에 점으로 찍으면 꺾은선그래프의 기초 연습도 됩니다.", "이렇게 물어보세요: \"씨앗 속에는 무엇이 들어 있기에 흙 속에서 혼자 싹을 틔울까?\""]}]}, {"type": "template", "title": "강낭콩 키 기록표", "desc": "4주 동안 키를 점으로 찍는 그래프와 관찰 칸. A4 1장.", "pdf": "assets/pdf/egg-tray-beans.pdf"}, {"type": "more", "items": [{"title": "투명 컵 뿌리 관찰", "body": "젖은 키친타월과 콩을 투명 컵 벽에 붙여 뿌리를 옆에서 봐요."}, {"title": "거꾸로 심기", "body": "콩을 뒤집어 심어도 뿌리가 아래로 자랄까요?"}, {"title": "열매까지", "body": "큰 화분에 옮겨 꽃과 꼬투리가 생길 때까지 길러요."}]}, {"type": "info", "items": [{"label": "도안", "value": "강낭콩 키 기록표 (A4 1장)"}, {"label": "실험 키트", "value": "강낭콩 씨앗 (마트·문구점)"}, {"label": "교육과정 연결", "value": "3~4학년 식물의 한살이"}]}]$json$::jsonb,27) on conflict (slug) do nothing;
update public.topics set activity_slug='egg-tray-beans' where band='3~4' and subject='과학' and name='식물의 한살이';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('ice-and-dew','과학','3~4','물의 상태 변화','얼음 녹이기 경주와 컵 물방울','얼음을 가장 빨리 녹이는 방법을 겨루고, 차가운 컵 겉에 맺히는 물방울의 정체를 찾아요.','난이도 ★☆☆ 쉬움','40분',array['뜨거운 물은 어른이']::text[],array['페트병']::text[],'assets/img/n_ice-and-dew.jpg',false,'assets/pdf/ice-and-dew.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 부엌 재료", "rows": [{"name": "같은 크기 얼음 5개", "how": "같은 얼음 틀에서 꺼내요", "kit": false}, {"name": "지퍼백 5개", "how": "얼음을 하나씩 담아요", "kit": false}, {"name": "소금, 수건, 그릇", "how": "녹이는 방법마다 써요", "kit": false}, {"name": "페트병 2개", "how": "하나는 냉장고에서 차갑게, 하나는 실온", "kit": false}, {"name": "시계", "how": "녹는 시간을 재요", "kit": false}, {"name": "관찰 기록지 도안", "how": "아래에서 내려받아요", "kit": false}], "image": null}, {"type": "steps", "title": "실험 방법", "items": [{"title": "방법 정하기", "body": "가족마다 얼음 녹이는 방법을 하나씩 골라요. 손으로 쥐기, 소금 뿌리기, 수건으로 싸기, 햇볕에 두기, 그대로 두기.", "warn": "", "image": null}, {"title": "동시에 시작", "body": "지퍼백에 얼음을 넣고 같은 시각에 시작해요. 다 녹은 시각을 기록지에 적어요.", "warn": "", "image": null}, {"title": "결과 비교", "body": "가장 빨리 녹은 방법과 가장 늦게 녹은 방법을 찾아요. 수건으로 싼 얼음은 왜 늦게 녹았을까요?", "warn": "", "image": null}, {"title": "컵 물방울 관찰", "body": "냉장고에서 꺼낸 페트병과 실온 페트병을 나란히 두고 5분 기다려요. 어느 쪽 겉에 물방울이 맺히나요?", "warn": "", "image": null}, {"title": "물방울 맛보기 대신 닦아 보기", "body": "맺힌 물방울을 휴지로 닦아 색이 있는지 봐요. 병 안의 음료가 새어 나온 걸까요?", "warn": "", "image": null}], "notes": []}, {"type": "questions", "title": "관찰해 봐요", "items": ["얼음이 녹으면 물의 양은 늘어날까요, 줄어들까요?", "차가운 병 겉의 물방울은 어디에서 왔을까요?", "겨울 아침 유리창이 뿌옇게 되는 것도 같은 까닭일까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["물은 얼음(고체), 물(액체), 수증기(기체)로 모습을 바꿔요. 따뜻한 열을 받으면 얼음이 녹아 물이 되고, 물이 증발하면 눈에 보이지 않는 수증기가 돼요. 공기 속 수증기가 차가운 병에 닿으면 다시 물방울로 변해서 병 겉에 맺혀요."]}, {"label": "부모님께", "paras": ["얼음이 녹는 것은 융해, 물이 수증기가 되는 것은 증발, 수증기가 차가운 표면에서 물방울이 되는 것은 응결입니다. 병 겉 물방울이 '병에서 샌 물'이 아니라 공기 중 수증기라는 것을 아이 스스로 추론하게 하는 것이 이 활동의 핵심입니다.", "수건으로 싼 얼음이 늦게 녹는 것은 수건이 바깥 열이 들어오는 것을 막기 때문입니다. 아이스박스와 같은 원리예요.", "이렇게 물어보세요: \"아이스크림을 오래 안 녹게 가져가려면 무엇으로 싸면 좋을까?\""]}]}, {"type": "template", "title": "물의 상태 변화 기록지", "desc": "얼음 녹이기 경주 기록표와 물방울 관찰 칸. A4 1장.", "pdf": "assets/pdf/ice-and-dew.pdf"}, {"type": "more", "items": [{"title": "얼음 무게 재기", "body": "녹기 전 얼음과 녹은 물의 무게를 저울로 비교해요."}, {"title": "색깔 얼음", "body": "식용색소 얼음이 녹으며 물에 퍼지는 모습을 관찰해요."}, {"title": "물 증발 관찰", "body": "접시에 물을 담아 두고 하루마다 양을 표시해요."}]}, {"type": "info", "items": [{"label": "도안", "value": "관찰 기록지 (A4 1장)"}, {"label": "실험 키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 물의 상태 변화 (융해, 증발, 응결)"}]}]$json$::jsonb,28) on conflict (slug) do nothing;
update public.topics set activity_slug='ice-and-dew' where band='3~4' and subject='과학' and name='물의 상태 변화';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('moon-phase-calendar','과학','3~4','지구와 달','종이접시 달 모양 달력','한 달 동안 밤하늘의 달을 관찰해 종이접시 달력에 그리고, 달 모양이 바뀌는 차례를 찾아요.','난이도 ★☆☆ 쉬움','만들기 20분 · 관찰 한 달',array['밤 관찰은 어른과 함께']::text[],array['이면지']::text[],'assets/img/n_moon-phase-calendar.jpg',false,'assets/pdf/moon-phase-calendar.pdf',$json$[{"type": "materials", "note": "살 것 없음", "rows": [{"name": "종이접시 1개", "how": "달력판으로 써요 (없으면 상자 판을 동그랗게)", "kit": false}, {"name": "달 관찰 달력 도안", "how": "30칸 달력과 달 모양 5단계 카드", "kit": false}, {"name": "연필, 색연필", "how": "본 모양 그대로 칠해요", "kit": false}, {"name": "손전등, 공 (선택)", "how": "달 모양이 바뀌는 까닭을 실험해요", "kit": false}], "image": null}, {"type": "steps", "title": "실험 방법", "items": [{"title": "달력 붙이기", "body": "도안의 30칸 달력을 오려 종이접시에 붙여요.", "warn": "", "image": null}, {"title": "매일 같은 시각에 보기", "body": "저녁 같은 시각에 같은 곳에서 달을 찾아요. 보이는 모양을 칸에 그대로 칠해요. 구름 낀 날은 '구름'이라고 적어요.", "warn": "", "image": null}, {"title": "이름 붙이기", "body": "모양 카드를 보고 초승달, 상현달, 보름달, 하현달, 그믐달 중 무엇인지 적어요.", "warn": "", "image": null}, {"title": "차례 찾기", "body": "한 달이 지나면 달력을 보며 달 모양이 어떤 차례로 바뀌었는지 이어 말해요.", "warn": "", "image": null}, {"title": "손전등 실험", "body": "어두운 방에서 손전등을 해, 공을 달이라 생각하고 공을 들고 내 주위를 돌아요. 공의 밝은 부분이 어떻게 보이나요?", "warn": "", "image": null}], "notes": ["상현달은 낮에도 보이고, 하현달은 늦은 밤에 떠요. 저녁에 안 보이는 날도 기록해 두면 됩니다."]}, {"type": "questions", "title": "관찰해 봐요", "items": ["보름달 다음에는 달이 어느 쪽부터 줄어드나요?", "같은 모양의 달이 다시 보이기까지 며칠쯤 걸리나요?", "달은 왜 날마다 모양이 바뀌어 보일까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["달은 스스로 빛을 내지 않고 햇빛을 받아 반사해요. 달이 지구 둘레를 돌면서 우리에게 햇빛 받은 부분이 보이는 만큼만 밝게 보이기 때문에, 날마다 모양이 달라 보여요. 달 모양은 약 한 달마다 다시 처음으로 돌아와요."]}, {"label": "부모님께", "paras": ["달의 위상은 초승달 → 상현달 → 보름달 → 하현달 → 그믐달 순으로 약 29.5일 주기로 바뀝니다. 음력 날짜와 거의 맞아서 음력 15일 무렵이 보름달입니다.", "손전등과 공 실험은 3~4학년 수준에서 '보이는 부분이 달라진다'는 생각을 몸으로 이해하게 하는 데 목적이 있습니다. 정확한 궤도 설명보다 관찰한 차례를 말할 수 있으면 충분합니다.", "이렇게 물어보세요: \"추석이나 정월 대보름에는 왜 꼭 보름달이 뜰까?\""]}]}, {"type": "template", "title": "달 관찰 달력", "desc": "30칸 관찰 달력과 달 모양 5단계 카드. A4 1장.", "pdf": "assets/pdf/moon-phase-calendar.pdf"}, {"type": "more", "items": [{"title": "달 쿠키", "body": "오레오 쿠키 크림을 긁어 달 모양 5단계를 만들어요."}, {"title": "음력 달력 찾기", "body": "휴대폰 달력에서 음력 날짜와 관찰한 달 모양을 맞춰 봐요."}, {"title": "달 표면 관찰", "body": "보름달을 쌍안경으로 보고 어두운 무늬를 그려요."}]}, {"type": "info", "items": [{"label": "도안", "value": "달 관찰 달력 (A4 1장)"}, {"label": "실험 키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 지구와 달 (달의 모양 변화)"}]}]$json$::jsonb,29) on conflict (slug) do nothing;
update public.topics set activity_slug='moon-phase-calendar' where band='3~4' and subject='과학' and name='지구와 달';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('bottle-rain-gauge','과학','5~6','날씨와 우리 생활','페트병 빗물 측정기','페트병으로 우량계를 만들어 비가 얼마나 왔는지 재고, 일기 예보의 강수량과 비교해요.','난이도 ★★☆ 보통','만들기 30분 · 측정 2주',array['페트병 자르기는 어른이']::text[],array['페트병']::text[],'assets/img/n_bottle-rain-gauge.jpg',false,'assets/pdf/bottle-rain-gauge.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"name": "원통 모양 페트병", "how": "몸통이 곧은 생수병. 모양이 울퉁불퉁하면 정확하지 않아요", "kit": false}, {"name": "자갈이나 구슬", "how": "병 바닥에 넣어 넘어지지 않게 해요", "kit": false}, {"name": "눈금 띠 도안", "how": "mm 눈금 띠를 인쇄해 붙여요", "kit": false}, {"name": "투명 테이프, 가위", "how": "눈금 띠를 붙여요", "kit": false}], "image": null}, {"type": "steps", "title": "실험 방법", "items": [{"title": "병 자르기", "body": "페트병 윗부분(어깨 부분)을 잘라 내요. 잘라 낸 윗부분을 거꾸로 끼우면 깔때기가 돼요.", "warn": "자르기는 어른이 해요.", "image": null}, {"title": "바닥 채우기", "body": "바닥에 자갈을 넣고, 자갈 위까지 물을 부어 수평을 맞춰요. 이 물 높이가 0이에요.", "warn": "", "image": null}, {"title": "눈금 붙이기", "body": "도안의 눈금 띠 0을 물 높이에 맞춰 병 옆에 붙이고 투명 테이프로 덮어요.", "warn": "", "image": null}, {"title": "밖에 두기", "body": "나무나 지붕 아래가 아닌 탁 트인 곳에 두어요. 바람에 넘어지지 않게 돌로 받쳐요.", "warn": "", "image": null}, {"title": "재고 비우기", "body": "비가 그치면 늘어난 높이를 mm로 읽어 기록표에 적고, 다시 0까지 물을 맞춰요. 일기 예보의 강수량과 비교해요.", "warn": "", "image": null}], "notes": []}, {"type": "questions", "title": "관찰해 봐요", "items": ["병이 넓으면 빗물이 더 많이 모일 텐데, 높이는 어떻게 될까요?", "내가 잰 값과 일기 예보의 강수량은 얼마나 비슷한가요?", "비가 오기 전날 하늘과 바람은 어땠나요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["강수량은 비가 땅에 고였을 때의 높이를 mm로 나타낸 거예요. 몸통이 곧은 병이라면 병이 넓든 좁든 고이는 물의 높이는 같아서, 병 높이로 비의 양을 잴 수 있어요."]}, {"label": "부모님께", "paras": ["5학년 '날씨와 우리 생활' 단원은 습도, 이슬과 구름, 고기압·저기압, 계절별 날씨를 다룹니다. 직접 잰 강수량을 기상청 예보·관측값과 비교하면 날씨 자료가 생활과 어떻게 이어지는지 자연스럽게 이해합니다.", "병 바닥이 오목하거나 어깨가 둥글면 높이와 양이 비례하지 않으니, 몸통이 곧은 부분에서만 읽도록 도와주세요.", "이렇게 물어보세요: \"장마철 하루 강수량이 100mm라면 우리 병에는 어디까지 찰까?\""]}]}, {"type": "template", "title": "빗물 측정기 눈금 띠와 기록표", "desc": "0~100mm 눈금 띠 2개와 2주 기록표. A4 1장.", "pdf": "assets/pdf/bottle-rain-gauge.pdf"}, {"type": "more", "items": [{"title": "날씨 일기", "body": "2주 동안 기온, 구름 모양, 강수량을 함께 기록해요."}, {"title": "습도 관찰", "body": "차가운 컵 물방울이 습한 날과 건조한 날 다르게 맺히는지 봐요."}, {"title": "구름 사진첩", "body": "매일 같은 시각 하늘 사진을 찍어 비 오기 전 구름을 찾아요."}]}, {"type": "info", "items": [{"label": "도안", "value": "눈금 띠와 기록표 (A4 1장)"}, {"label": "실험 키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 날씨와 우리 생활 (강수량)"}]}]$json$::jsonb,30) on conflict (slug) do nothing;
update public.topics set activity_slug='bottle-rain-gauge' where band='5~6' and subject='과학' and name='날씨와 우리 생활';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('colored-celery','과학','5~6','식물의 구조와 기능','물감 물 배추 줄기 관찰','색깔 물에 꽂아 둔 배추 잎과 셀러리가 물들어 가는 모습을 보며, 물이 지나가는 길을 찾아요.','난이도 ★☆☆ 쉬움','준비 10분 · 관찰 하루',array['칼은 어른이']::text[],array['페트병']::text[],'assets/img/n_colored-celery.jpg',false,'assets/pdf/colored-celery.pdf',$json$[{"type": "materials", "note": "식용색소만 있으면 돼요", "rows": [{"name": "셀러리 줄기 또는 배추 속잎", "how": "하얀 부분이 많을수록 잘 보여요", "kit": false}, {"name": "식용색소 (빨강·파랑)", "how": "없으면 수성 물감을 진하게 풀어요", "kit": false}, {"name": "투명 컵이나 자른 페트병 2개", "how": "색깔 물을 담아요", "kit": false}, {"name": "돋보기", "how": "잘린 단면을 자세히 봐요", "kit": false}, {"name": "관찰 기록지 도안", "how": "아래에서 내려받아요", "kit": false}], "image": null}, {"type": "steps", "title": "실험 방법", "items": [{"title": "색깔 물 만들기", "body": "컵 두 개에 물을 반쯤 담고 색소를 진하게 풀어요.", "warn": "", "image": null}, {"title": "줄기 끝 자르기", "body": "셀러리 아래쪽을 어른이 칼로 비스듬히 새로 잘라요. 자르고 바로 물에 꽂아야 잘 빨아올려요.", "warn": "칼은 어른이 써요.", "image": null}, {"title": "시간마다 관찰", "body": "1시간, 3시간, 다음 날 아침에 잎과 줄기 색이 어떻게 변했는지 기록지에 그려요.", "warn": "", "image": null}, {"title": "단면 보기", "body": "다음 날 줄기를 가로로 잘라 단면을 돋보기로 봐요. 색이 든 점들이 보이나요?", "warn": "", "image": null}, {"title": "두 색 실험", "body": "줄기 아래를 세로로 반 갈라 한쪽은 빨강, 한쪽은 파랑 물에 꽂아 두면 잎은 어떻게 될까요?", "warn": "", "image": null}], "notes": []}, {"type": "questions", "title": "관찰해 봐요", "items": ["색은 줄기의 어느 부분을 따라 올라갔나요?", "잎 끝까지 색이 가는 데 얼마나 걸렸나요?", "잎을 다 떼어 낸 줄기도 물을 잘 빨아올릴까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["식물의 뿌리와 줄기 속에는 물이 지나가는 가느다란 관이 있어요. 이것을 물관이라고 해요. 잎에서 물이 수증기로 빠져나가면 아래에서 물이 계속 끌려 올라와서, 색깔 물이 잎까지 퍼져요."]}, {"label": "부모님께", "paras": ["6학년 '식물의 구조와 기능'은 뿌리의 흡수, 줄기의 물관, 잎의 증산 작용과 광합성을 다룹니다. 단면에서 보이는 색 점들이 물관 다발이며, 잎이 있을 때 물을 더 잘 끌어올리는 것은 증산 작용 때문입니다.", "잎을 뗀 줄기와 잎이 달린 줄기를 비교하면 증산 작용의 역할을 아이 스스로 발견할 수 있습니다.", "이렇게 물어보세요: \"큰 나무는 어떻게 꼭대기까지 물을 올려 보낼까?\""]}]}, {"type": "template", "title": "줄기 관찰 기록지", "desc": "시간별 관찰 그림 칸과 단면 그리기 칸. A4 1장.", "pdf": "assets/pdf/colored-celery.pdf"}, {"type": "more", "items": [{"title": "흰 꽃 물들이기", "body": "흰 카네이션이나 국화를 색깔 물에 꽂아 꽃잎을 물들여요."}, {"title": "비닐 씌우기", "body": "잎에 비닐봉지를 씌워 두고 안쪽에 맺히는 물방울을 봐요."}, {"title": "뿌리 관찰", "body": "콩나물 뿌리를 돋보기로 보고 뿌리털을 찾아요."}]}, {"type": "info", "items": [{"label": "도안", "value": "관찰 기록지 (A4 1장)"}, {"label": "실험 키트", "value": "식용색소 (마트 제과 코너)"}, {"label": "교육과정 연결", "value": "5~6학년 식물의 구조와 기능 (물관, 증산 작용)"}]}]$json$::jsonb,31) on conflict (slug) do nothing;
update public.topics set activity_slug='colored-celery' where band='5~6' and subject='과학' and name='식물의 구조와 기능';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('candle-jar','과학','5~6','연소와 소화','유리병 촛불 끄기','크기가 다른 유리병으로 촛불을 덮어 꺼지는 시간을 재고, 불이 타려면 무엇이 필요한지 알아봐요.','난이도 ★★★ 도전','30분',array['반드시 어른과 함께','불 사용']::text[],'{}'::text[],'assets/img/n_candle-jar.jpg',false,'assets/pdf/candle-jar.pdf',$json$[{"type": "materials", "note": "반드시 어른이 곁에서 함께해요", "rows": [{"name": "티라이트 초 1개", "how": "작고 낮은 초가 안전해요", "kit": false}, {"name": "크기가 다른 유리병 3개", "how": "잼병, 음료병처럼 입구가 넓은 것", "kit": false}, {"name": "쟁반과 물 한 컵", "how": "초 아래 받치고, 만일을 위해 곁에 둬요", "kit": false}, {"name": "라이터 (어른용)", "how": "불은 어른만 붙여요", "kit": false}, {"name": "시계", "how": "꺼질 때까지 시간을 재요", "kit": false}, {"name": "기록표 도안", "how": "아래에서 내려받아요", "kit": false}], "image": null}, {"type": "steps", "title": "실험 방법", "items": [{"title": "안전 준비", "body": "탁자 위 물건을 치우고 쟁반에 초를 올려요. 머리카락은 묶고, 물 한 컵을 곁에 둬요.", "warn": "불은 어른만 붙이고 다뤄요.", "image": null}, {"title": "작은 병부터", "body": "어른이 불을 붙인 뒤 가장 작은 병을 덮고, 꺼질 때까지 시간을 재요.", "warn": "", "image": null}, {"title": "큰 병으로 반복", "body": "병이 식은 뒤 중간 병, 큰 병으로 바꿔 같은 방법으로 시간을 재요. 병은 뜨거우니 바로 만지지 않아요.", "warn": "병이 뜨거워요. 식을 때까지 기다려요.", "image": null}, {"title": "결과 정리", "body": "병 크기와 꺼진 시간을 기록표에 적고, 어떤 관계가 있는지 이야기해요.", "warn": "", "image": null}, {"title": "소화 방법 찾기", "body": "촛불을 끄는 다른 방법(입김, 뚜껑 덮기, 심지 집기)을 떠올리고, 각각 무엇을 없앤 것인지 나눠 봐요.", "warn": "", "image": null}], "notes": ["안전: 아이 혼자 불을 붙이거나 다루지 않게 해 주세요. 실험이 끝나면 초를 끄고 물을 부어 완전히 식혀요."]}, {"type": "questions", "title": "관찰해 봐요", "items": ["큰 병을 덮었을 때 촛불이 더 오래 탄 까닭은 무엇일까요?", "병 안쪽 벽에 무엇이 생겼나요?", "소화기는 불을 끌 때 무엇을 없애는 걸까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["불이 타려면 탈 물질, 산소, 불이 붙을 만큼의 온도 세 가지가 모두 있어야 해요. 병을 덮으면 촛불이 병 속 산소를 쓰다가 산소가 모자라서 꺼져요. 큰 병에는 공기가 더 많아서 더 오래 타요."]}, {"label": "부모님께", "paras": ["6학년 '연소와 소화' 단원은 연소의 조건(탈 물질, 산소, 발화점 이상의 온도)과, 이 중 하나 이상을 없애는 소화의 원리를 다룹니다. 병 안쪽에 맺히는 뿌연 물방울은 초가 탈 때 생긴 물입니다.", "병을 물 위에 덮어 물이 올라오는 실험은 산소 소비만으로 설명하기 어려운 부분이 있어 이 활동에서는 다루지 않았습니다. 시간 비교에 집중해 주세요.", "이렇게 물어보세요: \"우리 집에서 불이 나면 어떻게 대피하고, 소화기는 어디에 있을까?\""]}]}, {"type": "template", "title": "촛불 실험 기록표", "desc": "병 크기별 시간 기록표와 소화의 세 가지 방법 정리 칸. A4 1장.", "pdf": "assets/pdf/candle-jar.pdf"}, {"type": "more", "items": [{"title": "우리 집 소화기 찾기", "body": "소화기 위치와 사용 순서(안전핀 뽑기 → 노즐 잡기 → 손잡이 누르기)를 확인해요."}, {"title": "대피 지도", "body": "우리 집 대피 경로를 그려 현관에 붙여요."}, {"title": "안전한 비교", "body": "병 대신 크기가 다른 컵을 써서도 시간을 비교해요."}]}, {"type": "info", "items": [{"label": "도안", "value": "기록표 (A4 1장)"}, {"label": "실험 키트", "value": "티라이트 초 (생활용품점)"}, {"label": "교육과정 연결", "value": "5~6학년 연소와 소화"}]}]$json$::jsonb,32) on conflict (slug) do nothing;
update public.topics set activity_slug='candle-jar' where band='5~6' and subject='과학' and name='연소와 소화';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('bottle-terrarium','과학','5~6','생물과 환경','페트병 미니 생태계','페트병 안에 흙, 이끼, 작은 식물을 넣고 뚜껑을 닫아 작은 생태계를 만들어 몇 주 동안 지켜봐요.','난이도 ★★☆ 보통','만들기 40분 · 관찰 4주',array['페트병 자르기는 어른이']::text[],array['페트병']::text[],'assets/img/n_bottle-terrarium.jpg',false,'assets/pdf/bottle-terrarium.pdf',$json$[{"type": "materials", "note": "공원·화단에서 재료를 조금씩 모아요", "rows": [{"name": "2L 투명 페트병", "how": "가운데를 잘라 아래는 그릇, 위는 뚜껑으로 써요", "kit": false}, {"name": "작은 자갈", "how": "맨 아래 물 빠짐 층", "kit": false}, {"name": "흙", "how": "화분 흙", "kit": false}, {"name": "이끼와 작은 풀", "how": "화단·공원에서 조금만 (허락받은 곳에서)", "kit": false}, {"name": "분무기", "how": "처음 한 번만 물을 뿌려요", "kit": false}, {"name": "관찰 일지 도안", "how": "아래에서 내려받아요", "kit": false}], "image": null}, {"type": "steps", "title": "실험 방법", "items": [{"title": "병 자르기", "body": "페트병 가운데를 잘라 위아래로 나눠요.", "warn": "자르기는 어른이 해요.", "image": null}, {"title": "층 쌓기", "body": "아래 병에 자갈 2cm, 흙 5cm를 차례로 넣어요.", "warn": "", "image": null}, {"title": "식물 심기", "body": "이끼를 깔고 작은 풀을 심어요. 공벌레 한두 마리를 넣어도 좋아요.", "warn": "", "image": null}, {"title": "물 주고 닫기", "body": "분무기로 흙이 촉촉해질 만큼만 물을 뿌리고, 위쪽 병을 덮어 테이프로 붙여요. 뚜껑도 닫아요.", "warn": "", "image": null}, {"title": "관찰하기", "body": "햇빛이 직접 들지 않는 밝은 창가에 두고 일주일에 두 번 관찰 일지를 써요. 병 안쪽 물방울과 식물 상태를 봐요.", "warn": "", "image": null}], "notes": ["4주 관찰이 끝나면 넣었던 공벌레는 데려온 곳에 놓아 주세요."]}, {"type": "questions", "title": "관찰해 봐요", "items": ["물을 다시 주지 않았는데 병 안이 촉촉한 까닭은 무엇일까요?", "아침과 저녁에 병 안쪽 물방울 양이 다른가요?", "식물이 시들었다면 어떤 환경 요인이 맞지 않았을까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["생태계는 식물, 동물 같은 생물과 햇빛, 물, 흙, 공기 같은 환경이 서로 영향을 주고받는 곳이에요. 병 속에서 식물은 햇빛을 받아 양분을 만들고, 물은 증발했다가 병 벽에서 물방울이 되어 다시 흙으로 떨어지며 돌고 돌아요."]}, {"label": "부모님께", "paras": ["6학년 '생물과 환경'은 생태계 구성 요소, 먹이 관계, 비생물 요소(빛, 온도, 물)가 생물에 미치는 영향을 다룹니다. 닫힌 병 안에서 물이 순환하는 모습은 생태계를 눈으로 보는 좋은 예입니다.", "곰팡이가 피면 실패가 아니라 분해자가 등장한 것이라는 점도 함께 이야기해 주세요. 다만 심하면 뚜껑을 열어 환기합니다.", "이렇게 물어보세요: \"병 속 생태계에서 한 가지가 사라진다면 무엇이 가장 먼저 영향을 받을까?\""]}]}, {"type": "template", "title": "미니 생태계 관찰 일지", "desc": "4주 관찰 칸(주 2회)과 생태계 구성 요소 정리표. A4 1장.", "pdf": "assets/pdf/bottle-terrarium.pdf"}, {"type": "more", "items": [{"title": "빛 비교", "body": "똑같이 만든 병 두 개를 밝은 곳과 어두운 곳에 두고 비교해요."}, {"title": "먹이 그물 그리기", "body": "우리 동네 공원의 생물로 먹이 그물을 그려요."}, {"title": "분해자 관찰", "body": "사과 조각을 지퍼백에 넣어 곰팡이가 생기는 과정을 봐요."}]}, {"type": "info", "items": [{"label": "도안", "value": "관찰 일지 (A4 1장)"}, {"label": "실험 키트", "value": "집과 공원 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 생물과 환경 (생태계)"}]}]$json$::jsonb,33) on conflict (slug) do nothing;
update public.topics set activity_slug='bottle-terrarium' where band='5~6' and subject='과학' and name='생물과 환경';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('place-value-cups','수학','3~4','덧셈과 뺄셈','종이컵 자릿값 계산판','종이컵 세 개에 백, 십, 일의 자리를 붙이고 콩을 옮기며, 받아올림과 받아내림이 왜 생기는지 손으로 확인해요.','난이도 ★☆☆ 쉬움','만들기 10분 · 놀이 20분',array['콩은 어린 동생 손이 닿지 않게']::text[],array['종이컵','병뚜껑']::text[],'assets/img/n_place-value-cups.jpg',false,'assets/pdf/place-value-cups.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 집에 있는 재료", "rows": [{"name": "종이컵 3개", "how": "백·십·일의 자리 컵이 돼요", "kit": false}, {"name": "마른 콩이나 병뚜껑 30개", "how": "일의 자리 낱개로 써요", "kit": false}, {"name": "빨대 또는 이쑤시개 묶음", "how": "10개를 고무줄로 묶어 '십 묶음'을 만들어도 좋아요", "kit": false}, {"name": "자릿값 계산판 도안", "how": "아래에서 내려받아요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "계산판 펼치기", "body": "도안을 인쇄해 책상에 놓고, 백·십·일 칸 위에 종이컵을 하나씩 올려요. 컵에 '백', '십', '일'이라고 적어요.", "warn": "", "image": null}, {"title": "수를 컵에 담기", "body": "예를 들어 247이면 백 컵에 2개, 십 컵에 4개, 일 컵에 7개를 넣어요. 같은 콩이라도 어느 컵에 있느냐에 따라 값이 달라져요.", "warn": "", "image": null}, {"title": "더하는 수 담기", "body": "247 + 185라면 185만큼 콩을 더 넣어요. 백 컵에 1개, 십 컵에 8개, 일 컵에 5개.", "warn": "", "image": null}, {"title": "일의 자리부터 정리", "body": "일 컵의 콩을 세어요. 7+5=12개! 10개를 빼서 십 컵에 콩 1개로 바꿔 넣어요. 이게 받아올림이에요. 일 컵에는 2개가 남아요.", "warn": "", "image": null}, {"title": "십, 백의 자리도 정리", "body": "십 컵이 4+8+1=13개가 되면 또 10개를 백 컵 1개로 바꿔요. 최종 답은 4, 3, 2. 즉 432예요.", "warn": "", "image": null}, {"title": "뺄셈은 거꾸로", "body": "빼야 할 콩이 모자라면 윗자리 컵에서 1개를 꺼내 아랫자리 콩 10개로 바꿔요. 이게 받아내림이에요.", "warn": "", "image": null}], "notes": ["처음에는 두 자리 수로 시작하고, 익숙해지면 세 자리 수로 늘려요. 문제 카드는 도안 아래쪽에 있어요."]}, {"type": "questions", "title": "생각해 봐요", "items": ["일 컵에 콩이 10개 넘게 있으면 왜 안 될까요?", "십 컵의 콩 1개는 일 컵의 콩 몇 개와 같을까요?", "받아올림이 두 번 생기는 덧셈 문제를 직접 만들어 볼 수 있나요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["우리가 쓰는 수는 한 칸에 0부터 9까지만 들어갈 수 있어요. 10이 되면 한 칸 왼쪽으로 이사를 가요. 일의 자리 10개가 십의 자리 1개, 십의 자리 10개가 백의 자리 1개가 되는 거예요. 그래서 덧셈할 때 10이 넘으면 윗자리에 1을 올려 주는 거랍니다."]}, {"label": "부모님께", "paras": ["3학년 '덧셈과 뺄셈'은 세 자리 수의 받아올림·받아내림이 핵심입니다. 아이가 세로셈에서 작은 '1'을 왜 쓰는지 모르고 외우기만 하면 실수가 잦아집니다. 콩 10개를 1개로 바꾸는 손동작을 세로셈의 작은 1과 연결해 주세요.", "정리가 끝나면 계산판 옆에 세로셈을 같이 써서 비교해 보세요.", "이렇게 물어보세요: \"일 컵에서 십 컵으로 콩을 옮길 때, 세로셈에서는 어디에 무엇을 쓰면 될까?\""]}]}, {"type": "template", "title": "자릿값 계산판", "desc": "백·십·일 자리 판과 덧셈·뺄셈 문제 카드 12장. A4 1장.", "pdf": "assets/pdf/place-value-cups.pdf"}, {"type": "more", "items": [{"title": "어림하고 계산하기", "body": "계산 전에 '대략 400쯤?' 하고 어림한 뒤 결과와 비교해요."}, {"title": "가게 놀이", "body": "100원·10원·1원 동전을 컵 대신 써서 거스름돈 계산을 해요."}, {"title": "문제 내기", "body": "아이가 문제를 내고 부모님이 풀어요. 일부러 틀려서 아이가 찾아내게 해 보세요."}]}, {"type": "info", "items": [{"label": "도안", "value": "자릿값 계산판 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 덧셈과 뺄셈 (세 자리 수, 받아올림·받아내림)"}]}]$json$::jsonb,34) on conflict (slug) do nothing;
update public.topics set activity_slug='place-value-cups' where band='3~4' and subject='수학' and name='덧셈과 뺄셈';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('snack-division','수학','3~4','나눗셈','종이컵 간식 똑같이 나누기','과자를 종이컵 접시에 똑같이 나눠 담으며, 나눗셈의 두 가지 뜻과 곱셈과의 관계를 알아봐요.','난이도 ★☆☆ 쉬움','20분','{}'::text[],array['종이컵']::text[],'assets/img/n_snack-division.jpg',false,'assets/pdf/snack-division.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 간식만 있으면 돼요", "rows": [{"name": "종이컵 4~6개", "how": "간식을 담는 접시로 써요", "kit": false}, {"name": "작은 간식 24개", "how": "젤리, 시리얼, 콩과자 등 셀 수 있는 것", "kit": false}, {"name": "나눗셈 기록지 도안", "how": "아래에서 내려받아요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "똑같이 나누기", "body": "간식 12개를 종이컵 3개에 하나씩 차례로 넣어요. 한 컵에 몇 개씩 들어갔나요? 12 ÷ 3 = 4.", "warn": "", "image": null}, {"title": "묶어서 덜어 내기", "body": "이번에는 간식 12개를 4개씩 컵에 담아요. 컵이 몇 개 필요한가요? 12 ÷ 4 = 3.", "warn": "", "image": null}, {"title": "두 방법 비교하기", "body": "같은 12개인데 '몇 명에게 나누나'를 물으면 한 사람 몫이, '몇 개씩 담나'를 물으면 묶음 수가 답이 돼요. 기록지 두 칸에 그림으로 그려요.", "warn": "", "image": null}, {"title": "곱셈으로 확인하기", "body": "컵 3개 × 4개 = 12개. 나눗셈 답이 맞는지 곱셈으로 거꾸로 확인해요.", "warn": "", "image": null}, {"title": "남는 것 알아보기", "body": "간식 14개를 컵 3개에 나누면 2개가 남아요. 남는 수(나머지)는 나누는 수보다 항상 작아요.", "warn": "나머지는 4학년 내용이에요. 어려워하면 넘어가도 돼요.", "image": null}], "notes": ["다 하고 나면 나눈 간식은 맛있게 먹어요. 가족 수대로 나누면 더 재미있어요."]}, {"type": "questions", "title": "생각해 봐요", "items": ["24개를 똑같이 나눌 수 있는 컵의 수를 모두 찾아볼까요?", "나눗셈 답을 곱셈으로 확인하는 방법을 말해 볼까요?", "20개를 6명에게 나누면 어떻게 될까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["나눗셈은 똑같이 나누는 계산이에요. '12개를 3명에게 똑같이 나누면 한 명이 몇 개?'처럼 나눌 수도 있고, '12개를 4개씩 담으면 몇 봉지?'처럼 묶을 수도 있어요. 어느 쪽이든 12 ÷ 3 = 4처럼 써요."]}, {"label": "부모님께", "paras": ["3학년 나눗셈은 '똑같이 나누기(등분제)'와 '몇 번 덜어 내기(포함제)' 두 가지 뜻으로 소개됩니다. 아이가 문장제에서 헷갈려 하면 실물로 두 방법을 직접 해 보는 것이 가장 빠릅니다.", "곱셈구구를 거꾸로 쓰는 것이 나눗셈이라는 연결도 꼭 짚어 주세요.", "이렇게 물어보세요: \"12 ÷ 3 = 4를 보고 곱셈식을 두 개 만들어 볼까?\""]}]}, {"type": "template", "title": "나눗셈 기록지", "desc": "나누기·묶기 그림 칸과 곱셈 확인 칸. A4 1장.", "pdf": "assets/pdf/snack-division.pdf"}, {"type": "more", "items": [{"title": "나눗셈 이야기 만들기", "body": "15 ÷ 5를 보고 간식, 연필, 스티커로 이야기 문제를 지어요."}, {"title": "피자 나누기", "body": "분수 활동의 피자 판으로 8조각을 2명, 4명에게 나눠요."}, {"title": "나머지 찾기 놀이", "body": "주사위 두 개로 수를 만들고 3으로 나눴을 때 나머지를 맞혀요."}]}, {"type": "info", "items": [{"label": "도안", "value": "나눗셈 기록지 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 나눗셈 (등분제와 포함제, 곱셈과의 관계)"}]}]$json$::jsonb,35) on conflict (slug) do nothing;
update public.topics set activity_slug='snack-division' where band='3~4' and subject='수학' and name='나눗셈';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('paper-meter-tape','수학','3~4','길이와 시간','종이띠 1m 자와 1분 감각 놀이','도안 4장을 이어 붙여 1m 줄자를 만들어 집 안을 재고, 스톱워치로 1분과 초의 감각을 익혀요.','난이도 ★☆☆ 쉬움','만들기 15분 · 놀이 20분','{}'::text[],array['이면지']::text[],'assets/img/n_paper-meter-tape.jpg',false,'assets/pdf/paper-meter-tape.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 휴대폰 스톱워치를 써요", "rows": [{"name": "1m 자 도안", "how": "25cm 띠 4개 (A4 1장). 반드시 배율 100%로 인쇄해요", "kit": false}, {"name": "풀, 가위, 테이프", "how": "띠를 이어 붙여요", "kit": false}, {"name": "휴대폰 스톱워치", "how": "시간 놀이에 써요", "kit": false}, {"name": "길이 기록지", "how": "도안 오른쪽 칸에 있어요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "인쇄 확인하기", "body": "인쇄한 띠의 0과 10 사이를 학교 자로 재 보세요. 정확히 10cm면 인쇄가 잘 된 거예요.", "warn": "'페이지에 맞춤'으로 인쇄하면 길이가 틀려져요.", "image": null}, {"title": "1m 자 만들기", "body": "띠 4개를 오려 숫자가 이어지도록 0~25, 25~50, 50~75, 75~100 순서로 붙여요. 이음매는 테이프로 겹치지 않게 맞대요.", "warn": "", "image": null}, {"title": "어림하고 재기", "body": "식탁, 문, 침대 길이를 먼저 '몇 cm쯤?' 어림하고 자로 재서 기록지에 적어요. 1m가 넘으면 '1m 20cm'처럼 써요.", "warn": "", "image": null}, {"title": "mm까지 재기", "body": "연필, 지우개처럼 작은 물건은 작은 눈금으로 재요. 작은 눈금 한 칸이 1mm, 10칸이 1cm예요.", "warn": "", "image": null}, {"title": "1분 맞히기", "body": "스톱워치를 켜고 눈을 감은 채 '1분 됐다!' 싶을 때 손을 들어요. 몇 초였는지 확인해요.", "warn": "", "image": null}, {"title": "1분 동안 해 보기", "body": "1분 동안 줄넘기 몇 번, 박수 몇 번을 할 수 있는지 재요. 60초 = 1분이에요.", "warn": "", "image": null}], "notes": ["1km는 1m 자 1000개를 이은 길이예요. 집에서 학교까지 몇 걸음인지 세어 보면 km 감각이 생겨요."]}, {"type": "questions", "title": "생각해 봐요", "items": ["내 키는 1m보다 얼마나 더 클까요?", "어림한 길이와 잰 길이가 가장 많이 차이 난 물건은 무엇인가요?", "눈을 감고 잰 1분은 실제보다 길었나요, 짧았나요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["1cm를 10칸으로 나눈 한 칸이 1mm, 1cm가 100개 모이면 1m, 1m가 1000개 모이면 1km예요. 시간도 비슷해요. 1초가 60개 모이면 1분, 1분이 60개 모이면 1시간이에요. 길이는 10, 100, 1000씩, 시간은 60씩 묶인다는 게 달라요."]}, {"label": "부모님께", "paras": ["3학년 '길이와 시간'은 mm·km 단위와 초 단위, 그리고 시간의 덧셈·뺄셈을 다룹니다. 시간 계산에서 60을 넘으면 받아올림하는 부분을 아이들이 가장 어려워하니, 스톱워치 놀이로 '60초 = 1분' 감각을 먼저 몸으로 익히게 해 주세요.", "어림 → 측정 → 비교 순서를 지키면 측정 감각이 훨씬 빨리 늡니다.", "이렇게 물어보세요: \"2분 30초는 모두 몇 초일까?\""]}]}, {"type": "template", "title": "1m 종이띠 자", "desc": "mm 눈금이 있는 25cm 띠 4개와 길이 기록표. A4 1장.", "pdf": "assets/pdf/paper-meter-tape.pdf"}, {"type": "more", "items": [{"title": "가족 키 재기", "body": "문틀에 1m 자를 세워 가족 키를 재고 표시해요."}, {"title": "1km 걷기", "body": "지도 앱으로 1km 거리를 찾아 걸어 보고 걸린 시간을 재요."}, {"title": "시간 계산 놀이", "body": "TV 프로그램 시작과 끝 시각으로 몇 분 동안 했는지 계산해요."}]}, {"type": "info", "items": [{"label": "도안", "value": "1m 자 도안 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 길이와 시간 (mm, km, 초)"}]}]$json$::jsonb,36) on conflict (slug) do nothing;
update public.topics set activity_slug='paper-meter-tape' where band='3~4' and subject='수학' and name='길이와 시간';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('carton-capacity','수학','3~4','들이와 무게','우유팩·페트병 들이 비교','우유팩과 페트병, 컵에 물을 옮겨 담으며 어느 그릇이 더 많이 담기는지 비교하고 L와 mL를 익혀요.','난이도 ★☆☆ 쉬움','30분',array['물을 쓰니 욕실이나 싱크대에서']::text[],array['우유팩','페트병','종이컵']::text[],'assets/img/n_carton-capacity.jpg',false,'assets/pdf/carton-capacity.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 빈 용기를 모아 두세요", "rows": [{"name": "1L 우유팩, 200mL 우유팩", "how": "겉에 들이가 적혀 있어 기준이 돼요", "kit": false}, {"name": "500mL 페트병, 2L 페트병", "how": "라벨의 숫자를 확인해요", "kit": false}, {"name": "종이컵 여러 개", "how": "작은 단위 그릇으로 써요", "kit": false}, {"name": "주방 저울 (있으면)", "how": "무게 비교에 써요", "kit": false}, {"name": "들이 기록지 도안", "how": "아래에서 내려받아요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "들이 어림하기", "body": "그릇들을 줄 세우고 어느 것에 물이 가장 많이 들어갈지 예상 순서를 기록지에 적어요.", "warn": "", "image": null}, {"title": "종이컵으로 세기", "body": "각 그릇에 물을 가득 채운 뒤 종이컵에 옮겨 부어 몇 컵이 나오는지 세요.", "warn": "", "image": null}, {"title": "기준 그릇으로 비교", "body": "200mL 우유팩으로 1L 우유팩을 채워 보세요. 5번이면 가득 차요. 그래서 1L = 1000mL예요.", "warn": "", "image": null}, {"title": "라벨과 맞춰 보기", "body": "페트병 라벨의 mL 숫자를 보고, 우리가 센 컵 수와 맞는지 확인해요.", "warn": "", "image": null}, {"title": "무게도 비교하기", "body": "저울이 있으면 물을 채운 그릇의 무게를 재 봐요. 물 1L는 약 1kg이에요.", "warn": "저울이 없으면 두 손에 들고 어느 쪽이 무거운지 느껴 봐요.", "image": null}], "notes": ["종이컵은 가득 채우면 약 180~190mL쯤 돼요. 컵마다 조금씩 달라서 '정확한 단위'가 왜 필요한지 이야기 나누기 좋아요."]}, {"type": "questions", "title": "생각해 봐요", "items": ["모양이 다른데 들이가 같은 그릇이 있었나요?", "키가 큰 그릇이 항상 더 많이 담길까요?", "종이컵으로 재면 왜 정확하지 않을까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["그릇에 담을 수 있는 양을 들이라고 해요. 들이는 L(리터)와 mL(밀리리터)로 나타내고, 1L는 1000mL예요. 1L 우유팩에는 200mL 우유팩 5개만큼 들어가요. 키가 크다고 많이 들어가는 건 아니에요. 넓이와 높이를 모두 봐야 해요."]}, {"label": "부모님께", "paras": ["3학년 '들이와 무게'는 임의 단위(컵)로 비교하다가 표준 단위(L, mL, kg, g)가 왜 필요한지 깨닫는 흐름입니다. 생활 속 용기 라벨을 함께 읽으면 단위 감각이 빠르게 생깁니다.", "무게 부분은 '고무줄 저울' 활동(물체의 무게)과 함께 하면 더 좋습니다.", "이렇게 물어보세요: \"1L 3병과 500mL 2병을 합치면 몇 L 몇 mL일까?\""]}]}, {"type": "template", "title": "들이 비교 기록지", "desc": "예상 순서, 컵 수 기록, 단위 바꾸기 연습 칸. A4 1장.", "pdf": "assets/pdf/carton-capacity.pdf"}, {"type": "more", "items": [{"title": "라벨 찾기 탐험", "body": "냉장고 속 음료, 우유, 간장병의 들이를 모두 찾아 표로 만들어요."}, {"title": "1kg 맞히기", "body": "책, 과일 등을 들어 보고 1kg쯤 되는 물건을 찾아 저울로 확인해요."}, {"title": "고무줄 저울과 함께", "body": "물체의 무게 단원의 고무줄 저울로 물 100mL, 200mL를 달아 봐요."}]}, {"type": "info", "items": [{"label": "도안", "value": "들이 기록지 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 들이와 무게 (L, mL, kg, g)"}]}]$json$::jsonb,37) on conflict (slug) do nothing;
update public.topics set activity_slug='carton-capacity' where band='3~4' and subject='수학' and name='들이와 무게';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('tangram','수학','3~4','평면도형','이면지 칠교놀이','정사각형 한 장을 일곱 조각으로 잘라 동물과 집 모양을 만들고, 직각삼각형·정사각형·직사각형을 찾아봐요.','난이도 ★☆☆ 쉬움','만들기 15분 · 놀이 30분','{}'::text[],array['이면지','상자']::text[],'assets/img/n_tangram.jpg',false,'assets/pdf/tangram.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 택배 상자에 붙이면 튼튼해요", "rows": [{"name": "칠교 도안", "how": "조각 선과 모양 카드 (A4 1장)", "kit": false}, {"name": "얇은 택배 상자 판지", "how": "도안을 붙여 두꺼운 조각을 만들어요", "kit": false}, {"name": "풀, 가위, 색연필", "how": "조각마다 색을 칠하면 구분하기 쉬워요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "도안 붙이기", "body": "도안의 큰 정사각형을 상자 판지에 풀로 붙여요.", "warn": "", "image": null}, {"title": "일곱 조각 자르기", "body": "선을 따라 큰 삼각형 2개, 중간 삼각형 1개, 작은 삼각형 2개, 정사각형 1개, 평행사변형 1개로 잘라요.", "warn": "두꺼운 판지는 어른이 칼로 잘라 주세요.", "image": null}, {"title": "직각 찾기", "body": "삼각자나 책 모서리를 대 보며 직각이 있는 조각을 찾아 표시해요.", "warn": "", "image": null}, {"title": "도전 카드 풀기", "body": "도안 아래 도전 카드 3장(정사각형, 삼각형, 직사각형)을 보고 카드에 적힌 조각만 써서 같은 모양을 만들어요.", "warn": "", "image": null}, {"title": "조각 합치기", "body": "작은 삼각형 2개로 정사각형, 중간 삼각형, 평행사변형을 각각 만들 수 있는지 해 봐요.", "warn": "", "image": null}, {"title": "나만의 모양", "body": "새로운 모양을 만들고 테두리를 따라 그려 가족에게 문제로 내요.", "warn": "", "image": null}], "notes": ["일곱 조각을 다시 정사각형으로 맞추는 것이 생각보다 어려워요. 막히면 큰 삼각형 2개부터 놓아 보세요."]}, {"type": "questions", "title": "생각해 봐요", "items": ["일곱 조각 중 직각이 있는 조각은 몇 개인가요?", "작은 삼각형 2개로 만들 수 있는 모양은 무엇무엇일까요?", "정사각형도 직사각형이라고 할 수 있을까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["꼭짓점에서 종이를 반듯하게 두 번 접었을 때 생기는 각을 직각이라고 해요. 직각이 있는 삼각형은 직각삼각형, 네 각이 모두 직각인 사각형은 직사각형이에요. 그중 네 변의 길이까지 모두 같으면 정사각형이에요. 그래서 정사각형은 직사각형의 한 종류랍니다."]}, {"label": "부모님께", "paras": ["3학년 '평면도형'은 선분·반직선·직선, 각과 직각, 직각삼각형·직사각형·정사각형을 다룹니다. 아이들이 '정사각형은 직사각형인가?'를 가장 헷갈려 하니, 칠교 조각을 직접 대 보며 조건을 하나씩 확인하게 해 주세요.", "4학년 다각형·사각형 분류(평행사변형, 사다리꼴)로 이어질 때 이 조각들을 다시 쓰면 좋습니다.", "이렇게 물어보세요: \"이 조각은 왜 직사각형이 아니라고 생각해?\""]}]}, {"type": "template", "title": "칠교 도안", "desc": "칠교 정사각형(15cm)과 모양 만들기 도전 카드 3장. A4 1장.", "pdf": "assets/pdf/tangram.pdf"}, {"type": "more", "items": [{"title": "시간 재기 대결", "body": "같은 모양 카드를 누가 더 빨리 만드는지 겨뤄요."}, {"title": "종이 접어 직각 만들기", "body": "아무 모양 종이를 두 번 접어 직각 자를 만들고 집 안 직각을 찾아요."}, {"title": "그림자 맞히기", "body": "모양 테두리만 그려 주고 조각 배치를 맞히게 해요."}]}, {"type": "info", "items": [{"label": "도안", "value": "칠교 도안 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 평면도형 (직각, 직각삼각형, 직사각형, 정사각형)"}]}]$json$::jsonb,38) on conflict (slug) do nothing;
update public.topics set activity_slug='tangram' where band='3~4' and subject='수학' and name='평면도형';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('hundred-chart-multiples','수학','5~6','약수와 배수','1~100 수표 배수 색칠','1부터 100까지 수표에서 2, 3, 5의 배수를 색칠해 무늬를 찾고, 겹치는 칸에서 공배수와 소수를 발견해요.','난이도 ★★☆ 보통','40분','{}'::text[],array['병뚜껑','이면지']::text[],'assets/img/n_hundred-chart-multiples.jpg',false,'assets/pdf/hundred-chart-multiples.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 색연필만 있으면 돼요", "rows": [{"name": "1~100 수표 도안", "how": "같은 수표 3장이 들어 있어요 (A4 2장)", "kit": false}, {"name": "색연필 3색 이상", "how": "배수마다 다른 색으로 칠해요", "kit": false}, {"name": "병뚜껑이나 바둑돌 (선택)", "how": "색칠 대신 칸을 덮어도 돼요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "2의 배수 칠하기", "body": "첫 번째 수표에서 2, 4, 6…처럼 2씩 뛰어 세며 노란색으로 칠해요. 어떤 무늬가 생기나요?", "warn": "", "image": null}, {"title": "3의 배수 표시하기", "body": "같은 수표에 3, 6, 9…를 파란 동그라미로 표시해요. 노란색과 파란 동그라미가 겹친 수를 찾아요.", "warn": "", "image": null}, {"title": "공배수 찾기", "body": "두 표시가 겹친 6, 12, 18…이 2와 3의 공배수예요. 가장 작은 것은 무엇인가요? 그게 최소공배수예요.", "warn": "", "image": null}, {"title": "약수 찾기", "body": "두 번째 수표에서 24를 고르고, 24를 나누어떨어지게 하는 수(1, 2, 3, 4, 6, 8, 12, 24)를 모두 색칠해요.", "warn": "", "image": null}, {"title": "소수 체 거르기", "body": "세 번째 수표에서 1을 지우고, 2를 남긴 채 2의 배수를 모두 지워요. 3, 5, 7도 같은 방법으로 해요. 남은 수가 소수예요.", "warn": "소수는 6학년 이후 중학교 내용과 이어지는 심화 활동이에요.", "image": null}], "notes": ["5의 배수는 일의 자리가 0이나 5, 2의 배수는 일의 자리가 짝수라는 규칙도 수표에서 바로 보여요."]}, {"type": "questions", "title": "생각해 봐요", "items": ["2의 배수와 5의 배수를 모두 칠하면 겹치는 칸은 어디인가요?", "24와 36의 공약수는 무엇무엇일까요?", "약수가 딱 2개뿐인 수를 찾아볼까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["어떤 수를 나누어떨어지게 하는 수를 약수, 어떤 수를 1배, 2배, 3배 한 수를 배수라고 해요. 두 수의 배수에 공통으로 들어 있는 수가 공배수, 그중 가장 작은 수가 최소공배수예요. 수표에 색칠하면 배수가 일정한 간격으로 줄을 서는 게 보여요."]}, {"label": "부모님께", "paras": ["5학년 '약수와 배수'는 이어지는 '약분과 통분', '분수의 덧셈과 뺄셈'의 바탕입니다. 최대공약수·최소공배수를 계산 방법(공약수로 나누기)부터 외우기 전에 수표에서 눈으로 확인하게 하면 개념이 오래 남습니다.", "소수 체 거르기(에라토스테네스의 체)는 교과서 범위를 살짝 넘지만, 아이들이 아주 좋아하는 확장 활동입니다.", "이렇게 물어보세요: \"12와 18의 공배수 중 가장 작은 수는 수표에서 어디에 있을까?\""]}]}, {"type": "template", "title": "1~100 수표", "desc": "같은 수표 3장과 배수·약수 기록 칸. A4 2장.", "pdf": "assets/pdf/hundred-chart-multiples.pdf"}, {"type": "more", "items": [{"title": "배수 빙고", "body": "수표 일부를 오려 빙고판으로 쓰고 '4의 배수!'를 외쳐요."}, {"title": "버스 배차 문제", "body": "6분, 8분마다 오는 버스가 다시 동시에 오는 시각을 공배수로 구해요."}, {"title": "약수 직사각형", "body": "콩 12개로 만들 수 있는 직사각형 모양을 모두 찾아 약수와 연결해요."}]}, {"type": "info", "items": [{"label": "도안", "value": "1~100 수표 (A4 2장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 약수와 배수 (공약수, 공배수)"}]}]$json$::jsonb,39) on conflict (slug) do nothing;
update public.topics set activity_slug='hundred-chart-multiples' where band='5~6' and subject='수학' and name='약수와 배수';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('fraction-strips','수학','5~6','분수의 덧셈과 뺄셈','종이 분수 막대로 통분하기','같은 길이의 종이 막대를 2, 3, 4, 6, 8, 12조각으로 나눠 놓고, 분모가 다른 분수를 더할 때 왜 통분이 필요한지 눈으로 확인해요.','난이도 ★★☆ 보통','만들기 20분 · 놀이 30분','{}'::text[],array['이면지']::text[],'assets/img/n_fraction-strips.jpg',false,'assets/pdf/fraction-strips.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 도안과 색연필", "rows": [{"name": "분수 막대 도안", "how": "1, 1/2, 1/3, 1/4, 1/6, 1/8, 1/12 막대 (A4 1장)", "kit": false}, {"name": "가위, 색연필", "how": "막대마다 다른 색으로 칠해요", "kit": false}, {"name": "봉투나 지퍼백", "how": "조각을 보관해요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "색칠하고 자르기", "body": "막대마다 한 가지 색으로 칠한 뒤, 맨 위 '1' 막대만 그대로 두고 나머지는 칸마다 잘라 조각으로 만들어요.", "warn": "", "image": null}, {"title": "같은 크기 찾기", "body": "1/2 조각 1개와 길이가 같은 조각 묶음을 찾아요. 2/4, 3/6, 4/8, 6/12. 크기가 같은 분수예요.", "warn": "", "image": null}, {"title": "1/2 + 1/3 놓아 보기", "body": "1 막대 아래에 1/2 조각과 1/3 조각을 이어 놓아요. 이 길이를 한 종류의 조각으로만 덮을 수 있을까요?", "warn": "", "image": null}, {"title": "통분 찾기", "body": "1/6 조각으로 덮으면 딱 5개가 맞아요. 1/2 = 3/6, 1/3 = 2/6이니까 1/2 + 1/3 = 5/6.", "warn": "", "image": null}, {"title": "뺄셈도 해 보기", "body": "3/4 위에 1/3을 겹쳐 놓고 남은 길이를 1/12 조각으로 재요. 3/4 − 1/3 = 9/12 − 4/12 = 5/12.", "warn": "", "image": null}, {"title": "식으로 정리하기", "body": "조각으로 찾은 답을 기록지에 식으로 써요. 공통분모가 두 분모의 공배수라는 것을 확인해요.", "warn": "", "image": null}], "notes": ["1을 넘는 덧셈(예: 3/4 + 2/3)은 1 막대를 넘쳐서 대분수 1 5/12가 돼요."]}, {"type": "questions", "title": "생각해 봐요", "items": ["1/3과 1/4을 같은 조각으로 나타내려면 어떤 조각이 필요할까요?", "공통분모로 왜 두 분모의 공배수를 쓸까요?", "1/2 + 1/3이 2/5가 아닌 이유를 막대로 설명할 수 있나요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["분모가 다른 분수는 조각의 크기가 달라서 바로 더할 수 없어요. 그래서 두 분수를 같은 크기의 조각으로 바꿔 줘요. 이걸 통분이라고 해요. 1/2과 1/3은 둘 다 1/6 조각으로 바꿀 수 있어서 3/6 + 2/6 = 5/6이 돼요."]}, {"label": "부모님께", "paras": ["5학년 '분수의 덧셈과 뺄셈'에서 가장 흔한 오류가 '분자는 분자끼리, 분모는 분모끼리' 더하는 것입니다(1/2 + 1/3 = 2/5). 막대로 2/5가 1/2보다 작다는 것을 직접 보면 이 실수가 확 줄어듭니다.", "통분은 '약수와 배수'에서 배운 공배수와 바로 연결됩니다. 1~100 수표 활동을 먼저 하면 더 좋습니다.", "이렇게 물어보세요: \"1/2 + 1/3이 2/5라면 1/2보다 클까, 작을까?\""]}]}, {"type": "template", "title": "분수 막대", "desc": "1, 1/2, 1/3, 1/4, 1/6, 1/8, 1/12 막대(길이 18cm)와 계산 기록 칸. A4 1장.", "pdf": "assets/pdf/fraction-strips.pdf"}, {"type": "more", "items": [{"title": "분수 크기 줄 세우기", "body": "1/2, 2/3, 3/4, 5/6을 막대로 비교해 작은 순서로 놓아요."}, {"title": "분수 레시피", "body": "요리법의 1/2컵, 1/3컵을 합치면 얼마인지 막대로 계산해요."}, {"title": "분수 원판과 비교", "body": "3~4학년 피자 분수 원판으로 같은 덧셈을 해 보고 막대와 비교해요."}]}, {"type": "info", "items": [{"label": "도안", "value": "분수 막대 도안 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 분수의 덧셈과 뺄셈 (통분)"}]}]$json$::jsonb,40) on conflict (slug) do nothing;
update public.topics set activity_slug='fraction-strips' where band='5~6' and subject='수학' and name='분수의 덧셈과 뺄셈';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('flyer-decimal-shopping','수학','5~6','소수의 곱셈','마트 전단지 소수 장보기','전단지 속 100g당 가격과 kg 단위 무게로 장보기 계산을 하며, 소수를 곱하면 왜 값이 작아지기도 하는지 알아봐요.','난이도 ★★☆ 보통','30분','{}'::text[],array['이면지']::text[],'assets/img/n_flyer-decimal-shopping.jpg',false,'assets/pdf/flyer-decimal-shopping.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 마트 전단지나 영수증", "rows": [{"name": "마트 전단지 또는 영수증", "how": "무게(kg, g)가 적힌 상품이 있으면 좋아요", "kit": false}, {"name": "장보기 계산지 도안", "how": "예시 상품과 계산 칸 (A4 1장)", "kit": false}, {"name": "계산기 (확인용)", "how": "먼저 손으로 풀고 확인할 때만 써요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "상품 고르기", "body": "계산지의 예시 상품(사과 1kg 4,000원, 돼지고기 100g 2,500원 등)이나 전단지에서 무게 단위 상품을 골라요.", "warn": "", "image": null}, {"title": "어림하기", "body": "사과 1.5kg이면 1kg보다 많고 2kg보다 적으니 4,000원과 8,000원 사이겠죠? 먼저 어림값을 적어요.", "warn": "", "image": null}, {"title": "소수 곱셈하기", "body": "4,000 × 1.5 = 6,000원. 자연수처럼 곱한 뒤 소수점 아래 자릿수만큼 소수점을 옮겨요.", "warn": "", "image": null}, {"title": "1보다 작은 수 곱하기", "body": "사과 0.8kg은 4,000 × 0.8 = 3,200원. 1보다 작은 수를 곱하니 4,000원보다 작아졌어요.", "warn": "", "image": null}, {"title": "총액과 거스름돈", "body": "고른 상품을 모두 더하고 20,000원을 냈을 때 거스름돈을 계산해요.", "warn": "", "image": null}, {"title": "실제 영수증과 비교", "body": "다음 장보기 때 영수증의 무게와 가격을 보고 계산이 맞는지 확인해요.", "warn": "", "image": null}], "notes": ["돼지고기처럼 100g당 가격이면 600g은 2,500 × 6, 0.6kg이라고 생각해도 같은 값이 나와요."]}, {"type": "questions", "title": "생각해 봐요", "items": ["어떤 수에 0.5를 곱하는 것은 어떤 계산과 같을까요?", "곱했는데 처음 수보다 작아지는 경우는 언제일까요?", "1.2 × 1.5에서 소수점은 어디에 찍어야 할까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["소수를 곱할 때는 먼저 소수점이 없다고 생각하고 자연수처럼 곱해요. 그다음 두 수의 소수점 아래 자릿수를 더한 만큼 오른쪽에서부터 세어 소수점을 찍어요. 그리고 1보다 작은 수를 곱하면 결과가 원래 수보다 작아진다는 것도 기억해요."]}, {"label": "부모님께", "paras": ["5학년 '소수의 곱셈'은 '곱하면 커진다'는 자연수의 직관이 깨지는 단원입니다. 0.8kg이 1kg보다 싸다는 생활 감각과 연결하면 아이들이 쉽게 받아들입니다.", "계산 전에 어림을 꼭 하게 하세요. 소수점 위치 실수를 스스로 잡아내는 가장 좋은 습관입니다.", "이렇게 물어보세요: \"4,000 × 0.8이 4,000보다 큰지 작은지 계산 전에 말해 볼래?\""]}]}, {"type": "template", "title": "장보기 계산지", "desc": "예시 상품 6개 가격표, 어림·계산·거스름돈 칸. A4 1장.", "pdf": "assets/pdf/flyer-decimal-shopping.pdf"}, {"type": "more", "items": [{"title": "단위 가격 비교", "body": "같은 상품의 대용량과 소용량 중 100g당 어느 쪽이 싼지 비교해요."}, {"title": "기름값 계산", "body": "1L당 가격과 주유량(예: 35.5L)으로 주유비를 계산해요."}, {"title": "레시피 늘리기", "body": "2인분 요리법을 1.5배로 늘려 재료 양을 계산해요."}]}, {"type": "info", "items": [{"label": "도안", "value": "장보기 계산지 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 소수의 곱셈"}]}]$json$::jsonb,41) on conflict (slug) do nothing;
update public.topics set activity_slug='flyer-decimal-shopping' where band='5~6' and subject='수학' and name='소수의 곱셈';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('juice-ratio','수학','5~6','비와 비율','주스 비율 맞추기 실험','원액과 물을 1:3, 1:4로 섞어 맛을 비교하며 비, 비율, 백분율을 맛으로 알아봐요.','난이도 ★☆☆ 쉬움','30분',array['원액은 단맛이 강해요. 조금씩 맛보기']::text[],array['종이컵']::text[],'assets/img/n_juice-ratio.jpg',false,'assets/pdf/juice-ratio.pdf',$json$[{"type": "materials", "note": "음료 원액이나 매실청 하나만 준비", "rows": [{"name": "과일 원액이나 매실청", "how": "물에 타서 마시는 음료면 무엇이든", "kit": false}, {"name": "종이컵 6개 이상", "how": "계량 컵과 맛보기 컵", "kit": false}, {"name": "숟가락 또는 작은 계량컵", "how": "같은 양을 재는 단위로 써요", "kit": false}, {"name": "비율 실험 기록지 도안", "how": "아래에서 내려받아요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "단위 정하기", "body": "숟가락 1번을 '1'로 정해요. 같은 숟가락을 끝까지 써야 비교가 정확해요.", "warn": "", "image": null}, {"title": "1:3 주스 만들기", "body": "컵에 원액 2숟가락, 물 6숟가락을 넣어 섞어요. 원액 : 물 = 2 : 6 = 1 : 3이에요.", "warn": "", "image": null}, {"title": "다른 비율 만들기", "body": "1:4, 1:5 컵도 만들어 이름표를 붙여요. 어느 쪽이 더 진할지 먼저 예상해요.", "warn": "", "image": null}, {"title": "맛 비교하기", "body": "가족이 눈을 감고 맛보며 진한 순서를 맞혀요. 가장 맛있는 비율에 투표해요.", "warn": "", "image": null}, {"title": "비율 계산하기", "body": "원액 양 ÷ 전체 양을 계산해요. 1:3 주스는 1 ÷ 4 = 0.25, 즉 25%가 원액이에요.", "warn": "", "image": null}, {"title": "양 늘려 보기", "body": "가장 맛있는 비율로 1L 물병을 채우려면 원액이 얼마나 필요한지 계산해요.", "warn": "", "image": null}], "notes": ["'원액 : 물'과 '원액 : 전체'는 다른 비예요. 기록지에 두 가지를 모두 적어 보며 차이를 확인하세요."]}, {"type": "questions", "title": "생각해 봐요", "items": ["원액 2숟가락 : 물 6숟가락과 원액 3숟가락 : 물 9숟가락은 맛이 같을까요?", "1:4 주스에서 원액은 전체의 몇 %일까요?", "비가 같으면 양이 달라도 맛이 같은 이유는 무엇일까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["두 양을 나눗셈으로 비교하는 것을 비라고 해요. 원액 1, 물 3이면 '1 대 3'이라고 읽고 1 : 3이라고 써요. 기준량에 대한 비교하는 양의 크기를 비율이라고 하고, 비율에 100을 곱해 %를 붙이면 백분율이에요. 비가 같으면 컵이 커도 작아도 맛이 같아요."]}, {"label": "부모님께", "paras": ["6학년 '비와 비율'에서 아이들은 '기준량'과 '비교하는 양'을 자주 뒤바꿉니다. 'A : B에서 기준은 뒤에 있는 B'라는 것을 주스 맛으로 확인시켜 주세요.", "원액 : 물(1:3)과 원액 : 전체(1:4)를 구분하는 것이 백분율 계산의 핵심입니다.", "이렇게 물어보세요: \"1:3 주스 400mL를 만들려면 원액은 몇 mL가 필요할까?\""]}]}, {"type": "template", "title": "비율 실험 기록지", "desc": "비율별 재료 양, 예상·맛 순위, 비율·백분율 계산 칸. A4 1장.", "pdf": "assets/pdf/juice-ratio.pdf"}, {"type": "more", "items": [{"title": "밥 짓기 비율", "body": "쌀과 물의 비율을 확인하고 2인분, 4인분으로 늘려요."}, {"title": "할인율 찾기", "body": "전단지의 '30% 할인' 가격이 맞는지 계산해요."}, {"title": "지도 축척", "body": "지도의 1:50000 축척으로 실제 거리를 계산해요."}]}, {"type": "info", "items": [{"label": "도안", "value": "비율 실험 기록지 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 비와 비율 (비율, 백분율)"}]}]$json$::jsonb,42) on conflict (slug) do nothing;
update public.topics set activity_slug='juice-ratio' where band='5~6' and subject='수학' and name='비와 비율';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('plate-circle-area','수학','5~6','원의 넓이','종이접시 원 넓이 직사각형 만들기','원을 16조각으로 잘라 엇갈려 붙이면 직사각형에 가까워져요. 원의 넓이 공식이 어디서 왔는지 손으로 확인해요.','난이도 ★★☆ 보통','40분','{}'::text[],array['종이접시','이면지']::text[],'assets/img/n_plate-circle-area.jpg',false,'assets/pdf/plate-circle-area.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 종이접시나 도안", "rows": [{"name": "원 16등분 도안", "how": "반지름 6cm 원과 붙이기 칸 (A4 2장)", "kit": false}, {"name": "종이접시 1장 (선택)", "how": "도안 대신 접어서 써도 돼요", "kit": false}, {"name": "실 50cm와 자", "how": "원의 둘레(원주)를 재요", "kit": false}, {"name": "가위, 풀, 색연필", "how": "조각을 잘라 붙여요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "원주율 재기", "body": "종이접시나 동그란 컵 둘레에 실을 감아 길이를 재고, 지름으로 나눠요. 3.1~3.2쯤이 나오나요? 이 값이 원주율(약 3.14)이에요.", "warn": "", "image": null}, {"title": "반쪽씩 색칠하기", "body": "도안의 원을 위쪽 반원과 아래쪽 반원을 다른 색으로 칠해요.", "warn": "", "image": null}, {"title": "16조각 자르기", "body": "중심에서 나가는 선을 따라 16조각으로 잘라요. 피자 조각 같은 모양이 나와요.", "warn": "", "image": null}, {"title": "엇갈려 붙이기", "body": "도안 2쪽의 붙이기 칸에 한 조각은 뾰족한 쪽이 위, 다음 조각은 아래로 엇갈려 일렬로 붙여요. 직사각형에 가까운 모양이 돼요.", "warn": "", "image": null}, {"title": "가로와 세로 찾기", "body": "세로는 반지름(6cm), 가로는 원주의 반(6 × 2 × 3.14 ÷ 2 = 18.84cm)이에요. 둘을 곱하면 원의 넓이예요.", "warn": "", "image": null}, {"title": "공식으로 확인하기", "body": "반지름 × 반지름 × 3.14 = 6 × 6 × 3.14 = 113.04cm². 모눈 칸 세기와도 비교해요.", "warn": "", "image": null}], "notes": ["조각을 더 잘게(32조각) 나눌수록 더 반듯한 직사각형이 돼요. 아이와 '조각이 무한히 많으면?'을 이야기해 보세요."]}, {"type": "questions", "title": "생각해 봐요", "items": ["실로 잰 원주율이 정확히 3.14가 나오지 않는 이유는 무엇일까요?", "조각을 더 많이 자르면 모양이 어떻게 달라질까요?", "반지름이 2배가 되면 넓이는 몇 배가 될까요?"]}, {"type": "explain", "title": "왜 그럴까?", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["원을 아주 잘게 잘라 엇갈려 붙이면 직사각형이 돼요. 이 직사각형의 세로는 원의 반지름, 가로는 원 둘레의 절반이에요. 그래서 원의 넓이는 반지름 × 반지름 × 3.14로 구할 수 있어요. 3.14는 어떤 원이든 둘레를 지름으로 나누면 나오는 원주율이에요."]}, {"label": "부모님께", "paras": ["6학년 '원의 넓이'는 원주율(지름에 대한 원주의 비율)과 원의 넓이 공식을 다룹니다. 공식을 외우기 전에 '왜 반지름을 두 번 곱하지?'를 이 활동으로 이해하면 응용 문제에서 덜 흔들립니다.", "원주율을 실로 잴 때 오차가 생기는 것이 자연스럽다는 것도 함께 이야기해 주세요. 측정과 계산의 차이를 배우는 좋은 기회입니다.", "이렇게 물어보세요: \"반지름이 4cm인 원과 8cm인 원의 넓이는 몇 배 차이일까?\""]}]}, {"type": "template", "title": "원 16등분 도안", "desc": "반지름 6cm 원 16등분, 직사각형 붙이기 칸, 원주율 기록표. A4 2장.", "pdf": "assets/pdf/plate-circle-area.pdf"}, {"type": "more", "items": [{"title": "집 안 원주율 찾기", "body": "냄비 뚜껑, 컵, 시계의 원주와 지름을 재서 비율을 표로 정리해요."}, {"title": "피자 가격 비교", "body": "지름 30cm 피자와 지름 20cm 피자 2판 중 어느 쪽이 더 많은지 넓이로 비교해요."}, {"title": "모눈 세기", "body": "모눈종이(1cm 칸)에 반지름 6cm 원을 그려 칸을 세어 어림 넓이를 구해요."}]}, {"type": "info", "items": [{"label": "도안", "value": "원 넓이 도안 (A4 2장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 원의 넓이 (원주율, 원의 넓이)"}]}]$json$::jsonb,43) on conflict (slug) do nothing;
update public.topics set activity_slug='plate-circle-area' where band='5~6' and subject='수학' and name='원의 넓이';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('door-hanger-greetings','영어','3~4','인사하기','현관 문고리 인사 카드','방문 손잡이에 거는 인사 카드를 만들어, 아침저녁으로 가족과 영어로 인사를 주고받아요.','난이도 ★☆☆ 쉬움','만들기 20분 · 매일 1분','{}'::text[],array['상자','이면지']::text[],'assets/img/n_door-hanger-greetings.jpg',false,'assets/pdf/door-hanger-greetings.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 과자 상자 판지가 있으면 튼튼해요", "rows": [{"name": "문고리 카드 도안", "how": "앞뒤 인사 카드 4장 (A4 1장)", "kit": false}, {"name": "과자 상자 판지", "how": "카드를 붙여 두껍게 만들어요", "kit": false}, {"name": "풀, 가위, 색연필", "how": "", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "카드 꾸미기", "body": "도안의 카드 4장(Good morning / Good night / Hello / See you)에 색칠해요.", "warn": "", "image": null}, {"title": "판지에 붙여 자르기", "body": "카드를 상자 판지에 붙이고 바깥선과 문고리 구멍을 오려요.", "warn": "구멍은 어른이 가위 끝으로 뚫어 주세요.", "image": null}, {"title": "문에 걸기", "body": "아침에는 Good morning 면, 밤에는 Good night 면이 보이도록 방문 손잡이에 걸어요.", "warn": "", "image": null}, {"title": "카드 보고 인사하기", "body": "방에서 나올 때 카드를 뒤집으며 가족에게 그 카드의 인사를 해요. 듣는 사람도 똑같이 답해요.", "warn": "", "image": null}, {"title": "안부 묻기 더하기", "body": "익숙해지면 How are you? I'm fine, thank you. 를 이어서 말해요.", "warn": "", "image": null}], "notes": []}, {"type": "table", "title": "핵심 표현", "head": ["영어", "뜻과 쓰는 때"], "rows": [["Hello. / Hi.", "안녕. (언제든 쓰는 인사)"], ["Good morning.", "좋은 아침이야. (아침 인사)"], ["Good night.", "잘 자. (자기 전 인사)"], ["How are you?", "어떻게 지내? 잘 지내?"], ["I'm fine, thank you. And you?", "잘 지내, 고마워. 너는?"], ["Goodbye. / See you later.", "잘 가. / 나중에 봐."]], "note": ""}, {"type": "template", "title": "문고리 인사 카드", "desc": "Good morning / Good night / Hello / See you 카드 4장 (문고리 2개의 앞뒷면). A4 1장.", "pdf": "assets/pdf/door-hanger-greetings.pdf"}, {"type": "explain", "title": "", "boxes": [{"label": "부모님께", "paras": ["3학년 영어는 인사 표현으로 시작합니다. 영어 인사는 시간대(morning, afternoon, evening)와 헤어질 때(Goodbye, See you)를 구분한다는 점을 카드 앞뒤로 자연스럽게 보여 주세요.", "How are you? 에 꼭 I'm fine만 하지 않아도 됩니다. I'm good. / I'm great! / Not bad. 도 함께 써 보세요.", "부모님이 먼저 카드를 뒤집으며 인사하면 아이가 훨씬 빨리 따라 합니다."]}]}, {"type": "more", "items": [{"title": "인사 릴레이", "body": "가족이 원을 그리고 앉아 옆 사람에게 차례로 다른 인사를 건네요."}, {"title": "시간대 맞히기", "body": "시계 그림을 보여 주면 Good morning / Good afternoon / Good evening 중 맞는 인사를 말해요."}, {"title": "인형과 인사하기", "body": "가족 인형 만들기 활동의 인형으로 인사 대화 연극을 해요."}]}, {"type": "info", "items": [{"label": "도안", "value": "문고리 카드 도안 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 인사하기, 안부 묻고 답하기"}]}]$json$::jsonb,44) on conflict (slug) do nothing;
update public.topics set activity_slug='door-hanger-greetings' where band='3~4' and subject='영어' and name='인사하기';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('feelings-plate','영어','3~4','감정 말하기','종이접시 기분 시계','종이접시에 여덟 가지 기분 얼굴을 붙이고 화살표를 돌려, 오늘 내 기분을 영어로 묻고 답해요.','난이도 ★☆☆ 쉬움','만들기 25분 · 놀이 10분','{}'::text[],array['종이접시','상자']::text[],'assets/img/n_feelings-plate.jpg',false,'assets/pdf/feelings-plate.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 종이접시와 할핀(또는 빨대)", "rows": [{"name": "종이접시 1장", "how": "시계판이 돼요. 없으면 도안 원판을 판지에 붙여요", "kit": false}, {"name": "기분 시계 도안", "how": "감정 얼굴 8칸 원판과 화살표 (A4 1장)", "kit": false}, {"name": "할핀 1개", "how": "화살표를 고정해요. 없으면 빨대 조각과 테이프로", "kit": false}, {"name": "풀, 가위, 색연필", "how": "", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "얼굴 색칠하기", "body": "도안의 여덟 얼굴(happy, sad, angry, tired, hungry, sleepy, scared, excited)에 어울리는 색을 칠해요.", "warn": "", "image": null}, {"title": "원판 붙이기", "body": "원판을 오려 종이접시 가운데에 붙여요.", "warn": "", "image": null}, {"title": "화살표 달기", "body": "화살표를 상자 판지에 붙여 오리고, 가운데에 할핀을 꽂아 접시에 고정해요.", "warn": "할핀 끝이 날카로워요. 꽂는 것은 어른이.", "image": null}, {"title": "묻고 답하기", "body": "부모님이 How are you? 하고 물으면 아이가 화살표를 돌려 I'm happy. 처럼 답해요.", "warn": "", "image": null}, {"title": "이유 말하기", "body": "한국어로 왜 그런 기분인지 말해도 좋아요. 영어로 I'm hungry. 다음에 '밥 먹고 싶어!'처럼요.", "warn": "", "image": null}], "notes": []}, {"type": "table", "title": "핵심 표현", "head": ["영어", "뜻과 쓰는 때"], "rows": [["How are you?", "기분이 어때?"], ["I'm happy.", "나는 행복해."], ["I'm sad. / I'm angry.", "나는 슬퍼. / 나는 화가 나."], ["I'm tired. / I'm sleepy.", "나는 피곤해. / 나는 졸려."], ["I'm hungry.", "나는 배고파."], ["Are you okay?", "괜찮아?"]], "note": ""}, {"type": "template", "title": "기분 시계 도안", "desc": "감정 얼굴 8칸 원판(지름 18cm)과 화살표. A4 1장.", "pdf": "assets/pdf/feelings-plate.pdf"}, {"type": "explain", "title": "", "boxes": [{"label": "부모님께", "paras": ["3~4학년 '감정 말하기'는 I'm + 기분 낱말 구조를 익히는 것이 목표입니다. 낱말만 말해도(Happy!) 괜찮지만, 부모님은 항상 I'm happy. 처럼 완전한 문장으로 되돌려 말해 주세요.", "아이가 sad, angry를 고르면 영어 연습보다 '왜 그랬어?'라는 대화가 먼저입니다. 기분 시계는 감정을 말로 꺼내는 연습 도구이기도 합니다."]}, {"label": "이렇게 공감해 주세요", "paras": ["Oh, I see. · That's okay. · Me too!", "그렇구나. · 괜찮아. · 나도 그래!"]}]}, {"type": "more", "items": [{"title": "표정 연기 맞히기", "body": "한 사람이 표정만 지으면 다른 사람이 Are you happy? 하고 맞혀요."}, {"title": "가족 기분 일기", "body": "일주일 동안 저녁마다 가족 기분을 표에 스티커로 붙여요."}, {"title": "그림책 속 기분", "body": "영어 그림책 인물의 기분을 화살표로 가리켜요."}]}, {"type": "info", "items": [{"label": "도안", "value": "기분 시계 도안 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 감정 묻고 답하기"}]}]$json$::jsonb,45) on conflict (slug) do nothing;
update public.topics set activity_slug='feelings-plate' where band='3~4' and subject='영어' and name='감정 말하기';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('like-survey','영어','3~4','좋아하는 것 말하기','냉장고 좋아요 설문판','가족에게 Do you like ~? 로 좋아하는 음식을 묻고, 냉장고에 붙인 설문판에 O, X를 모아요.','난이도 ★☆☆ 쉬움','만들기 15분 · 설문 15분','{}'::text[],array['이면지']::text[],'assets/img/n_like-survey.jpg',false,'assets/pdf/like-survey.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 자석이나 테이프", "rows": [{"name": "좋아요 설문판 도안", "how": "음식 그림 낱말 8개와 가족 기록 칸 (A4 1장)", "kit": false}, {"name": "색연필, 연필", "how": "", "kit": false}, {"name": "냉장고 자석 또는 테이프", "how": "설문판을 붙여요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "설문판 꾸미기", "body": "음식 낱말(pizza, carrot, milk, chicken, kimchi, ice cream, fish, banana) 옆 그림에 색칠해요.", "warn": "", "image": null}, {"title": "가족 이름 쓰기", "body": "맨 위 칸에 Mom, Dad, 형제 이름, 그리고 Me를 써요.", "warn": "", "image": null}, {"title": "묻고 답하기", "body": "아이가 가족에게 Do you like pizza? 하고 물어요. Yes, I do. 면 O, No, I don't. 면 X를 칠해요.", "warn": "", "image": null}, {"title": "결과 말하기", "body": "다 모으면 Dad likes chicken. Mom doesn't like fish. 처럼 결과를 말해요. 어려우면 Dad, chicken, yes! 도 괜찮아요.", "warn": "", "image": null}, {"title": "냉장고에 붙이기", "body": "완성한 설문판을 냉장고에 붙이고, 저녁 메뉴 정할 때 참고해요.", "warn": "", "image": null}], "notes": []}, {"type": "table", "title": "핵심 표현", "head": ["영어", "뜻과 쓰는 때"], "rows": [["Do you like pizza?", "피자 좋아해?"], ["Yes, I do.", "응, 좋아해."], ["No, I don't.", "아니, 안 좋아해."], ["I like chicken.", "나는 치킨을 좋아해."], ["I don't like carrots.", "나는 당근을 안 좋아해."], ["What food do you like?", "무슨 음식 좋아해?"]], "note": ""}, {"type": "template", "title": "좋아요 설문판", "desc": "음식 8가지와 가족 5명 O·X 칸, 대화 표현 띠. A4 1장.", "pdf": "assets/pdf/like-survey.pdf"}, {"type": "explain", "title": "", "boxes": [{"label": "부모님께", "paras": ["3~4학년 '좋아하는 것 말하기'는 Do you like ~? / Yes, I do. / No, I don't. 대화가 핵심입니다. 영어에서 좋아하는 것을 일반적으로 말할 때는 carrots, bananas처럼 복수형을 쓰지만(pizza, milk처럼 셀 수 없는 것은 그대로), 초등 단계에서는 문장 구조에 먼저 집중하고 복수형은 들려주기만 해도 충분합니다.", "가족 결과를 말하는 3인칭(Dad likes)은 고학년 내용이니, 아이가 시도하면 칭찬만 해 주세요."]}, {"label": "이렇게 칭찬해 주세요", "paras": ["Good question! · Nice! · Thank you for asking.", "좋은 질문이야! · 좋아! · 물어봐 줘서 고마워."]}]}, {"type": "more", "items": [{"title": "좋아하는 것 넓히기", "body": "음식 대신 동물, 운동, 색깔로 새 설문판을 만들어요."}, {"title": "그래프로 그리기", "body": "결과를 '재활용 막대그래프' 활동처럼 막대그래프로 그려요."}, {"title": "인터뷰 영상", "body": "휴대폰으로 서로 인터뷰하는 짧은 영상을 찍어요."}]}, {"type": "info", "items": [{"label": "도안", "value": "설문판 도안 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 좋아하는 것 묻고 답하기"}]}]$json$::jsonb,46) on conflict (slug) do nothing;
update public.topics set activity_slug='like-survey' where band='3~4' and subject='영어' and name='좋아하는 것 말하기';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('dream-business-card','영어','5~6','장래 희망 말하기','미래의 나 꿈 명함 만들기','20년 뒤 내 직업을 상상해 영어 명함을 만들고, What do you want to be? 로 가족과 명함을 주고받아요.','난이도 ★☆☆ 쉬움','만들기 30분 · 놀이 10분','{}'::text[],array['상자']::text[],'assets/img/n_dream-business-card.jpg',false,'assets/pdf/dream-business-card.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 과자 상자 판지", "rows": [{"name": "꿈 명함 도안", "how": "빈 명함 8장과 직업 낱말 카드 (A4 1장)", "kit": false}, {"name": "과자 상자 판지", "how": "명함을 붙여 빳빳하게", "kit": false}, {"name": "색연필, 풀, 가위", "how": "", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "직업 고르기", "body": "도안의 직업 낱말(doctor, teacher, scientist, cook, pilot, singer, firefighter, YouTuber 등) 중에서 고르거나 새 직업을 찾아요.", "warn": "", "image": null}, {"title": "명함 쓰기", "body": "이름, 직업, 하는 일을 한 줄로 써요. 예: Kim Minjun / Scientist / I want to make robots.", "warn": "", "image": null}, {"title": "얼굴과 로고 그리기", "body": "명함 한쪽에 미래의 내 얼굴이나 회사 로고를 그려요.", "warn": "", "image": null}, {"title": "판지에 붙여 자르기", "body": "명함을 상자 판지에 붙이고 오려 여러 장 만들어요.", "warn": "", "image": null}, {"title": "명함 주고받기", "body": "Hi, I'm Minjun. What do you want to be? 하고 묻고, 상대가 답하면 명함을 건네요.", "warn": "", "image": null}], "notes": []}, {"type": "table", "title": "핵심 표현", "head": ["영어", "뜻과 쓰는 때"], "rows": [["What do you want to be?", "너는 무엇이 되고 싶어?"], ["I want to be a scientist.", "나는 과학자가 되고 싶어."], ["I want to be an artist.", "나는 화가가 되고 싶어. (모음 소리 앞에는 an)"], ["Why?", "왜?"], ["Because I like robots.", "왜냐하면 나는 로봇을 좋아하거든."], ["Good luck!", "행운을 빌어!"]], "note": ""}, {"type": "template", "title": "꿈 명함 도안", "desc": "빈 명함 8장과 직업 낱말 카드 12개. A4 1장.", "pdf": "assets/pdf/dream-business-card.pdf"}, {"type": "explain", "title": "", "boxes": [{"label": "부모님께", "paras": ["5~6학년 '장래 희망 말하기'는 I want to be a/an ~. 과 이유 말하기(Because ~)가 핵심입니다. a와 an의 구분(an artist, an engineer)도 이 단원에서 자주 나옵니다.", "직업 낱말을 모르면 함께 사전 앱에서 찾아보세요. YouTuber, game designer처럼 아이가 진짜 원하는 직업을 쓰게 해 주는 것이 동기 부여에 가장 좋습니다.", "부모님도 '어릴 때 꿈' 명함을 만들어 I wanted to be a ~. 라고 말해 주면 아이가 아주 좋아합니다."]}, {"label": "이렇게 응원해 주세요", "paras": ["That's a great dream! · You can do it!", "멋진 꿈이야! · 너는 할 수 있어!"]}]}, {"type": "more", "items": [{"title": "직업 스무고개", "body": "Do you work in a hospital? 처럼 질문해서 상대의 꿈 직업을 맞혀요."}, {"title": "가족 꿈 인터뷰", "body": "할머니, 할아버지께 어릴 때 꿈을 여쭤보고 영어로 명함을 만들어 드려요."}, {"title": "미래 일기", "body": "20년 뒤 하루를 I am a ~. 로 시작하는 세 문장으로 써요."}]}, {"type": "info", "items": [{"label": "도안", "value": "꿈 명함 도안 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 장래 희망 묻고 답하기"}]}]$json$::jsonb,47) on conflict (slug) do nothing;
update public.topics set activity_slug='dream-business-card' where band='5~6' and subject='영어' and name='장래 희망 말하기';
insert into public.activities (slug,subject,band,topic,title,summary,difficulty,duration,caution,tags,hero_image,hero_is_doc,template_pdf,content,sort_order) values ('weekend-plan-calendar','영어','5~6','계획 말하기','주말 계획 달력','토요일과 일요일 계획을 그림 달력에 채우고, I''m going to ~. 로 가족에게 발표한 뒤 지켰는지 확인해요.','난이도 ★★☆ 보통','계획 20분 · 확인 10분','{}'::text[],array['이면지']::text[],'assets/img/n_weekend-plan-calendar.jpg',false,'assets/pdf/weekend-plan-calendar.pdf',$json$[{"type": "materials", "note": "살 것 없음 · 도안과 색연필", "rows": [{"name": "주말 계획 달력 도안", "how": "토·일 오전/오후 칸과 활동 낱말 스티커 (A4 1장)", "kit": false}, {"name": "색연필, 풀, 가위", "how": "", "kit": false}, {"name": "체크 스티커 (선택)", "how": "지킨 계획에 붙여요", "kit": false}], "image": null}, {"type": "steps", "title": "하는 방법", "items": [{"title": "활동 고르기", "body": "도안의 활동 낱말(play soccer, visit Grandma, clean my room, read a book, go swimming, watch a movie 등)을 오려요.", "warn": "", "image": null}, {"title": "달력 채우기", "body": "토·일 오전과 오후 칸에 활동을 붙이고, 빈 칸에는 직접 써요.", "warn": "", "image": null}, {"title": "계획 발표하기", "body": "가족 앞에서 On Saturday, I'm going to play soccer. 처럼 발표해요.", "warn": "", "image": null}, {"title": "질문 주고받기", "body": "가족이 What are you going to do on Sunday? 하고 물으면 달력을 보고 답해요.", "warn": "", "image": null}, {"title": "일요일 저녁 확인", "body": "지킨 계획에 체크하고, 못 지킨 것은 다음 주로 옮겨요.", "warn": "", "image": null}], "notes": []}, {"type": "table", "title": "핵심 표현", "head": ["영어", "뜻과 쓰는 때"], "rows": [["What are you going to do this weekend?", "이번 주말에 뭐 할 거야?"], ["I'm going to play soccer.", "나는 축구를 할 거야."], ["On Saturday, I'm going to visit Grandma.", "토요일에 할머니 댁에 갈 거야."], ["Sounds fun!", "재미있겠다!"], ["How about you?", "너는?"], ["I'm not going to watch TV.", "나는 TV를 보지 않을 거야."]], "note": ""}, {"type": "template", "title": "주말 계획 달력", "desc": "토·일 오전/오후 칸, 활동 낱말 12개, 표현 띠. A4 1장.", "pdf": "assets/pdf/weekend-plan-calendar.pdf"}, {"type": "explain", "title": "", "boxes": [{"label": "부모님께", "paras": ["5~6학년 '계획 말하기'는 be going to + 동사원형으로 정해 둔 계획을 말하는 표현입니다. 동사 앞에 to가 오고, 동사는 항상 원래 모양(play, visit)이라는 점만 짚어 주세요.", "On Saturday, this weekend, tomorrow처럼 때를 나타내는 말을 함께 쓰면 문장이 훨씬 자연스러워집니다.", "일요일 저녁 확인 단계는 '지난 일 말하기'(I played soccer.)로 이어 연습하기 좋습니다."]}, {"label": "이렇게 반응해 주세요", "paras": ["Sounds fun! · Good plan! · Have a nice weekend!", "재미있겠다! · 좋은 계획이야! · 즐거운 주말 보내!"]}]}, {"type": "more", "items": [{"title": "방학 계획표", "body": "주말 대신 방학 계획을 같은 방법으로 만들어요."}, {"title": "지난 주말 말하기", "body": "확인 단계에서 I played soccer. 처럼 과거로 바꿔 말해요."}, {"title": "가족 여행 계획", "body": "가족 여행 일정을 영어 달력으로 함께 짜요."}]}, {"type": "info", "items": [{"label": "도안", "value": "계획 달력 도안 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 계획 묻고 답하기 (be going to)"}]}]$json$::jsonb,48) on conflict (slug) do nothing;
update public.topics set activity_slug='weekend-plan-calendar' where band='5~6' and subject='영어' and name='계획 말하기';
insert into public.kits (name,activity_slug,parts,status) values ('배추흰나비 관찰 세트','butterfly-life-cycle','["배추흰나비 애벌레 3마리","먹이용 케일 잎"]'::jsonb,'planned');

-- 단원 이론 레슨
create table if not exists public.lessons (
  id bigint generated always as identity primary key,
  slug text unique not null,
  band text not null check (band in ('3~4','5~6')),
  subject text not null check (subject in ('과학','수학','영어')),
  topic text not null,
  title text not null,
  hero_image text,
  content jsonb not null default '{}'::jsonb,
  sort_order int default 0,
  published boolean default true
);
alter table public.lessons enable row level security;
create policy "누구나 레슨 읽기" on public.lessons for select using (published);
alter table public.topics add column if not exists lesson_slug text references public.lessons(slug) on update cascade on delete set null;
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('s3-01','3~4','과학','소리의 성질','소리는 어떻게 생기고 전해질까?','assets/img/l_s3-01.jpg',$json${"intro": "북을 '둥!' 하고 치면 소리가 나요. 그 소리는 어디에서 생겨서 어떻게 우리 귀까지 오는 걸까요?", "sections": [{"heading": "소리는 떨림에서 생겨요", "paras": ["소리가 나는 물체를 손으로 살짝 만져 보면 바르르 떨리는 것이 느껴져요. 이렇게 물체가 빠르게 흔들리는 것을 '떨림'이라고 해요.", "소리가 나는 물체는 모두 떨리고 있어요. 떨리는 물체를 손으로 꽉 잡아 떨림을 멈추면 소리도 함께 멈춰요."], "example": "목에 손을 대고 '아~' 소리를 내 보면 목이 떨리는 것을 느낄 수 있어요.", "figure": "작은북 위에 좁쌀을 올려놓고 북을 치자 좁쌀이 튀어 오르는 모습"}, {"heading": "큰 소리와 작은 소리", "paras": ["소리의 크고 작은 정도를 '소리의 세기'라고 해요. 북을 세게 치면 큰 소리가 나고, 약하게 치면 작은 소리가 나요.", "큰 소리가 날 때는 물체가 크게 떨리고, 작은 소리가 날 때는 물체가 작게 떨려요."], "example": "도서관에서는 작은 소리로, 운동장에서 친구를 부를 때는 큰 소리로 말해요.", "figure": "북을 세게 칠 때와 약하게 칠 때 좁쌀이 튀어 오르는 높이를 비교한 그림"}, {"heading": "높은 소리와 낮은 소리", "paras": ["소리의 높고 낮은 정도를 '소리의 높낮이'라고 해요. 실로폰의 짧은 음판을 치면 높은 소리, 긴 음판을 치면 낮은 소리가 나요.", "높은 소리는 물체가 빠르게 떨릴 때, 낮은 소리는 물체가 느리게 떨릴 때 나요. 소리의 세기와 높낮이는 서로 다른 것이니 헷갈리지 마세요!"], "example": "구급차 사이렌, 새소리는 높은 소리이고 큰북 소리, 뱃고동 소리는 낮은 소리예요.", "figure": "짧은 음판부터 긴 음판까지 놓인 실로폰과 높은 소리·낮은 소리 표시"}, {"heading": "소리는 무엇을 통해 전해질까요?", "paras": ["소리는 공기 같은 기체를 통해 우리 귀에 전해져요. 그뿐 아니라 책상 같은 고체, 물 같은 액체를 통해서도 전해져요.", "실 전화기는 팽팽한 실이 떨림을 전해 주어서 멀리 있는 친구의 목소리가 들려요. 물속에서 수영할 때 밖의 소리가 들리는 것도 물이 소리를 전하기 때문이에요."], "example": "책상에 귀를 대고 친구가 책상을 톡톡 두드리면 소리가 또렷하게 들려요.", "figure": "두 아이가 종이컵 실 전화기로 이야기하는 모습"}, {"heading": "소리는 부딪치면 되돌아와요", "paras": ["소리가 나아가다가 물체에 부딪치면 되돌아오는데, 이것을 '소리의 반사'라고 해요. 딱딱하고 매끄러운 물체는 소리를 잘 반사하고, 부드러운 물체는 소리를 덜 반사해요.", "시끄러운 소리(소음)를 줄이려면 방음벽을 세우거나, 푹신한 물건을 깔아 소리가 덜 퍼지게 할 수 있어요."], "example": "산에서 '야호!' 하고 외치면 메아리가 되돌아오는 것이 소리의 반사예요.", "figure": "도로 옆 방음벽에 자동차 소리가 부딪쳐 되돌아가는 화살표 그림"}], "keywords": [{"word": "떨림", "meaning": "물체가 빠르게 흔들리는 것"}, {"word": "소리의 세기", "meaning": "소리가 크고 작은 정도"}, {"word": "소리의 높낮이", "meaning": "소리가 높고 낮은 정도"}, {"word": "소리의 반사", "meaning": "소리가 물체에 부딪쳐 되돌아오는 것"}, {"word": "소음", "meaning": "듣기 싫고 시끄러운 소리"}], "expressions": [], "quiz": [{"q": "소리가 나는 물체의 공통점은 무엇일까요?", "choices": ["색깔이 있다", "떨린다", "뜨겁다", "무겁다"], "answer": 1, "explain": "소리가 나는 물체는 모두 떨리고 있어요."}, {"q": "북을 세게 쳤을 때 나는 소리는 어떨까요?", "choices": ["더 큰 소리", "더 높은 소리", "더 낮은 소리", "소리가 안 난다"], "answer": 0, "explain": "세게 치면 북이 크게 떨려서 큰 소리가 나요."}, {"q": "실로폰에서 가장 높은 소리가 나는 음판은?", "choices": ["가장 긴 음판", "가운데 음판", "가장 짧은 음판", "모두 같다"], "answer": 2, "explain": "짧은 음판은 빠르게 떨려서 높은 소리가 나요."}, {"q": "실 전화기에서 소리를 전해 주는 것은 무엇일까요?", "choices": ["빛", "팽팽한 실", "바람", "손가락"], "answer": 1, "explain": "실이 떨림을 전해 주어 상대방에게 소리가 들려요. 실이 느슨하면 소리가 잘 안 들려요."}, {"q": "산에서 들리는 메아리와 관계있는 소리의 성질은?", "choices": ["소리의 세기", "소리의 높낮이", "소리의 떨림 멈춤", "소리의 반사"], "answer": 3, "explain": "소리가 산에 부딪쳐 되돌아오는 것이 메아리예요."}], "summary": ["소리는 물체의 떨림으로 생겨요.", "소리에는 세기(크고 작음)와 높낮이(높고 낮음)가 있어요.", "소리는 기체·액체·고체를 통해 전해지고, 물체에 부딪치면 반사돼요."], "parent_tip": "부모님께: 아이들은 '큰 소리'와 '높은 소리'를 자주 같은 것으로 생각합니다. '모기 소리는 높을까, 클까?', '아빠 목소리는 엄마 목소리보다 높을까 낮을까?'처럼 생활 속 소리를 세기와 높낮이로 나누어 말해 보게 하면 개념이 잘 잡힙니다."}$json$::jsonb,1) on conflict (slug) do nothing;
update public.topics set lesson_slug='s3-01' where band='3~4' and subject='과학' and name='소리의 성질';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('s3-02','3~4','과학','자석의 성질','자석은 어떤 물체를 끌어당길까?','assets/img/l_s3-02.jpg',$json${"intro": "냉장고 문에 붙은 자석, 필통 뚜껑의 자석! 자석은 왜 어떤 것은 붙고 어떤 것은 안 붙을까요?", "sections": [{"heading": "자석에 붙는 물체, 붙지 않는 물체", "paras": ["자석은 철로 된 물체를 끌어당겨요. 클립, 철 못, 철 숟가락처럼 철로 만든 물체는 자석에 붙어요.", "나무, 플라스틱, 유리, 종이, 고무로 만든 물체는 자석에 붙지 않아요. 알루미늄 캔이나 동전처럼 '금속'이어도 철이 아니면 붙지 않아요."], "example": "철 캔은 자석에 붙지만 알루미늄 캔은 붙지 않아서, 재활용 공장에서는 자석으로 두 캔을 골라내요.", "figure": "자석에 붙는 물체(클립, 철 못)와 붙지 않는 물체(지우개, 연필, 알루미늄 캔)를 나누어 놓은 그림"}, {"heading": "자석의 극", "paras": ["자석에서 철로 된 물체가 가장 많이 붙는 부분을 '자석의 극'이라고 해요. 막대자석은 양쪽 끝이 극이에요.", "자석에는 N극과 S극, 두 개의 극이 있어요. 자석을 아무리 잘라도 조각마다 다시 N극과 S극이 생겨요."], "example": "막대자석을 클립 상자에 넣었다 빼면 양쪽 끝에 클립이 가장 많이 붙어 나와요.", "figure": "막대자석의 양쪽 끝에 클립이 잔뜩 붙고 가운데는 거의 붙지 않은 모습"}, {"heading": "밀고 당기는 자석", "paras": ["두 자석을 가까이 가져가면, 같은 극끼리는 서로 밀어 내고 다른 극끼리는 서로 끌어당겨요.", "즉 N극과 N극, S극과 S극은 밀어 내고 N극과 S극은 끌어당겨요."], "example": "자석 장난감 기차는 다른 극끼리 마주 보게 해야 착 붙어요.", "figure": "N극-S극은 당기는 화살표, N극-N극은 밀어 내는 화살표로 표시한 두 막대자석 그림"}, {"heading": "자석은 방향을 알려 줘요", "paras": ["막대자석을 물에 띄운 접시에 올려놓으면 빙글 돌다가 N극은 북쪽, S극은 남쪽을 가리키며 멈춰요.", "이 성질을 이용한 것이 '나침반'이에요. 나침반 바늘도 자석이라서 늘 북쪽과 남쪽을 가리키지요. 그래서 나침반 가까이에 자석을 대면 바늘이 엉뚱한 쪽으로 움직여요."], "example": "길을 잃었을 때 나침반으로 북쪽을 찾을 수 있어요.", "figure": "나침반 바늘의 N극이 북쪽을 가리키는 모습"}, {"heading": "생활 속 자석", "paras": ["자석은 우리 생활 곳곳에서 쓰여요. 냉장고 문, 자석 칠판, 가방 여밈 장치, 자석 다트 등이 있어요.", "자석은 철로 된 물체를 사이에 다른 물체가 있어도 끌어당길 수 있어요. 그래서 종이를 사이에 두고도 자석으로 칠판에 붙일 수 있어요."], "example": "", "figure": "냉장고 문, 자석 칠판, 가방 자석 단추 등 생활 속 자석 사진 모음"}], "keywords": [{"word": "자석", "meaning": "철로 된 물체를 끌어당기는 물체"}, {"word": "자석의 극", "meaning": "자석에서 철을 가장 세게 끌어당기는 부분"}, {"word": "N극", "meaning": "자유롭게 움직이게 두면 북쪽을 가리키는 자석의 극"}, {"word": "S극", "meaning": "자유롭게 움직이게 두면 남쪽을 가리키는 자석의 극"}, {"word": "나침반", "meaning": "자석 바늘로 방향을 알려 주는 도구"}], "expressions": [], "quiz": [{"q": "다음 중 자석에 붙는 물체는?", "choices": ["플라스틱 자", "철 클립", "나무젓가락", "고무지우개"], "answer": 1, "explain": "자석은 철로 된 물체를 끌어당겨요."}, {"q": "막대자석에서 클립이 가장 많이 붙는 곳은?", "choices": ["가운데", "양쪽 끝", "모든 곳에 똑같이", "아무 곳에도 안 붙는다"], "answer": 1, "explain": "자석의 극은 막대자석의 양쪽 끝에 있어서 클립이 가장 많이 붙어요."}, {"q": "두 자석의 N극과 N극을 가까이 하면 어떻게 될까요?", "choices": ["끌어당긴다", "아무 일도 없다", "서로 밀어 낸다", "색이 변한다"], "answer": 2, "explain": "같은 극끼리는 서로 밀어 내요."}, {"q": "물에 띄운 막대자석의 N극은 어느 쪽을 가리키며 멈출까요?", "choices": ["북쪽", "남쪽", "동쪽", "서쪽"], "answer": 0, "explain": "자석의 N극은 북쪽, S극은 남쪽을 가리켜요."}, {"q": "다음 중 자석에 붙지 않는 금속은?", "choices": ["철 못", "철 숟가락", "철 캔", "알루미늄 캔"], "answer": 3, "explain": "금속이라도 철이 아니면 자석에 붙지 않아요."}], "summary": ["자석은 철로 된 물체를 끌어당겨요.", "자석에는 N극과 S극이 있고, 같은 극은 밀고 다른 극은 당겨요.", "자석의 N극은 북쪽을 가리키며, 이를 이용한 것이 나침반이에요."], "parent_tip": "부모님께: 아이들은 '금속은 모두 자석에 붙는다'고 생각하기 쉽습니다. 집에 있는 동전, 알루미늄 포일, 철 숟가락, 스테인리스 그릇 등을 자석에 대 보며 '왜 이건 안 붙을까?'를 함께 이야기해 보세요(스테인리스는 종류에 따라 붙기도 하고 안 붙기도 합니다)."}$json$::jsonb,2) on conflict (slug) do nothing;
update public.topics set lesson_slug='s3-02' where band='3~4' and subject='과학' and name='자석의 성질';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('s3-03','3~4','과학','빛과 그림자','그림자는 왜 생길까?','assets/img/l_s3-03.jpg',$json${"intro": "햇빛 좋은 날 운동장에 서면 내 발밑에 까만 그림자가 따라다녀요. 그림자는 어떻게 생기는 걸까요?", "sections": [{"heading": "빛은 곧게 나아가요", "paras": ["손전등을 켜면 빛이 똑바로 뻗어 나가요. 이렇게 빛이 곧게 나아가는 성질을 '빛의 직진'이라고 해요.", "빛이 곧게 나아가다가 물체에 막히면, 물체 뒤쪽으로는 빛이 가지 못해요."], "example": "구름 사이로 햇빛이 쭉쭉 곧은 줄처럼 내려오는 모습을 볼 수 있어요.", "figure": "어두운 방에서 손전등 빛이 곧은 줄기로 뻗어 나가는 모습"}, {"heading": "그림자가 생기는 까닭", "paras": ["그림자가 생기려면 빛, 물체, 그리고 그림자가 비칠 스크린(벽, 땅 등)이 필요해요.", "빛이 곧게 나아가다 물체에 막히면 물체 뒤쪽 스크린에 빛이 닿지 않아 어두운 그림자가 생겨요. 그래서 그림자 모양은 물체 모양과 비슷해요."], "example": "손으로 강아지 모양을 만들어 벽에 비추면 강아지 그림자가 생겨요.", "figure": "손전등-손-벽 순서로 놓고 벽에 손 그림자가 생긴 그림"}, {"heading": "투명한 물체와 불투명한 물체", "paras": ["유리컵처럼 빛이 대부분 통과하는 물체는 연한 그림자가 생겨요. 도자기 컵처럼 빛이 통과하지 못하는 물체는 진한 그림자가 생겨요.", "그림자의 진하기는 물체가 빛을 얼마나 통과시키는지에 따라 달라져요."], "example": "투명한 비닐우산 아래는 밝고, 검은 우산 아래는 어두워요.", "figure": "유리컵의 연한 그림자와 도자기 컵의 진한 그림자를 나란히 비교한 그림"}, {"heading": "그림자의 크기 바꾸기", "paras": ["손전등과 스크린은 그대로 두고 물체를 손전등에 가까이 가져가면 그림자가 커지고, 멀리 하면 그림자가 작아져요.", "또 같은 물체라도 놓는 방향을 바꾸면 그림자 모양이 달라질 수 있어요. 원기둥은 세우면 네모, 눕혀서 밑면을 비추면 동그라미 그림자가 생겨요."], "example": "인형극에서 인형을 불빛 가까이 대면 무대에 거인처럼 큰 그림자가 생겨요.", "figure": "물체가 손전등에 가까울 때 큰 그림자, 멀 때 작은 그림자가 생기는 두 장면 비교"}, {"heading": "거울은 빛을 되돌려요", "paras": ["빛이 나아가다 거울에 부딪치면 방향이 바뀌어 되돌아 나와요. 이것을 '빛의 반사'라고 해요.", "거울에 비친 모습은 실제와 좌우가 바뀌어 보여요. 오른손을 들면 거울 속 나는 왼손을 든 것처럼 보이지요."], "example": "구급차 앞에 글자를 좌우로 바꿔 써 두면, 앞차 운전자가 뒤를 보는 거울로 볼 때 바르게 읽혀요.", "figure": "거울에 부딪친 빛의 방향이 꺾여 나가는 화살표 그림"}], "keywords": [{"word": "빛의 직진", "meaning": "빛이 곧게 나아가는 성질"}, {"word": "그림자", "meaning": "빛이 물체에 막혀 물체 뒤에 생기는 어두운 부분"}, {"word": "투명한 물체", "meaning": "빛이 대부분 통과하는 물체"}, {"word": "불투명한 물체", "meaning": "빛이 통과하지 못하는 물체"}, {"word": "빛의 반사", "meaning": "빛이 거울 같은 물체에 부딪쳐 방향이 바뀌어 나아가는 것"}], "expressions": [], "quiz": [{"q": "그림자가 생기는 까닭과 가장 관계있는 빛의 성질은?", "choices": ["빛이 곧게 나아간다", "빛은 따뜻하다", "빛은 여러 색이다", "빛은 소리를 낸다"], "answer": 0, "explain": "빛이 곧게 나아가다 물체에 막혀 뒤쪽에 그림자가 생겨요."}, {"q": "진한 그림자가 생기는 물체는?", "choices": ["유리컵", "투명 비닐", "도자기 컵", "투명 플라스틱 판"], "answer": 2, "explain": "빛이 통과하지 못하는 불투명한 물체는 진한 그림자가 생겨요."}, {"q": "손전등과 스크린은 그대로 두고 물체를 손전등에 가까이 하면 그림자는?", "choices": ["작아진다", "커진다", "사라진다", "색이 변한다"], "answer": 1, "explain": "물체가 손전등에 가까울수록 빛을 더 많이 가려 그림자가 커져요."}, {"q": "거울 앞에서 오른손을 들면 거울 속 나는 어느 손을 든 것처럼 보일까요?", "choices": ["오른손", "양손", "손을 안 든다", "왼손"], "answer": 3, "explain": "거울에 비친 모습은 좌우가 바뀌어 보여요."}, {"q": "그림자가 생기는 데 꼭 필요하지 않은 것은?", "choices": ["빛", "물체", "스크린", "소리"], "answer": 3, "explain": "그림자는 빛, 물체, 스크린이 있으면 생겨요."}], "summary": ["빛은 곧게 나아가고, 물체에 막히면 그림자가 생겨요.", "불투명한 물체는 진한 그림자, 투명한 물체는 연한 그림자가 생겨요.", "물체가 빛에 가까울수록 그림자가 커지고, 거울은 빛을 반사해요."], "parent_tip": "부모님께: 아이들은 그림자가 물체에 '붙어 있는' 것이라 생각하기도 합니다. 밤에 손전등과 인형으로 그림자 놀이를 하며 '그림자를 크게 만들려면 어떻게 할까?', '그림자 모양을 동그라미로 바꿀 수 있을까?'를 물어보면 좋습니다."}$json$::jsonb,3) on conflict (slug) do nothing;
update public.topics set lesson_slug='s3-03' where band='3~4' and subject='과학' and name='빛과 그림자';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('s3-04','3~4','과학','물체의 무게','무게는 어떻게 잴까?','assets/img/l_s3-04.jpg',$json${"intro": "몸무게를 잴 때 체중계에 올라가요. 그런데 '무게'란 정확히 무엇이고, 저울은 어떻게 무게를 알아낼까요?", "sections": [{"heading": "무게란 무엇일까요?", "paras": ["지구는 물체를 지구 쪽으로 끌어당겨요. 그래서 공을 던져도 다시 땅으로 떨어지지요.", "지구가 물체를 끌어당기는 힘의 크기를 '무게'라고 해요. 무거운 물체일수록 지구가 더 세게 끌어당겨요."], "example": "사과가 나무에서 땅으로 떨어지는 것은 지구가 사과를 끌어당기기 때문이에요.", "figure": "나무에서 떨어지는 사과와 아래로 향한 화살표"}, {"heading": "용수철로 무게 재기", "paras": ["용수철에 물체를 걸면 용수철이 늘어나요. 무거운 물체를 걸수록 용수철이 더 많이 늘어나요.", "추를 하나씩 더 걸 때마다 용수철은 일정한 길이만큼씩 늘어나요. 이 성질을 이용해 무게를 재는 도구가 '용수철저울'이에요. 무게의 단위로는 g중, kg중, N(뉴턴) 등을 써요."], "example": "추 1개에 2cm 늘어나는 용수철은 추 3개를 걸면 6cm 늘어나요.", "figure": "용수철에 추를 1개, 2개, 3개 걸었을 때 일정하게 늘어나는 모습을 나란히 그린 그림"}, {"heading": "수평 잡기의 원리", "paras": ["널빤지 가운데를 받침점 위에 올려놓고 양쪽에 물체를 올려 기울지 않게 하는 것을 '수평 잡기'라고 해요.", "무게가 같은 물체는 받침점에서 같은 거리에 놓아야 수평이 돼요. 무게가 다르면 무거운 물체를 받침점에 더 가깝게 놓아야 수평을 잡을 수 있어요."], "example": "시소를 탈 때 몸무게가 무거운 아빠는 가운데 쪽으로, 가벼운 아이는 끝 쪽에 앉으면 균형이 맞아요.", "figure": "시소 가운데 받침점 가까이 어른, 끝에 아이가 앉아 수평을 이룬 그림"}, {"heading": "여러 가지 저울", "paras": ["양팔저울은 수평 잡기의 원리로 두 물체의 무게를 비교해요. 내려간 쪽 물체가 더 무거워요.", "체중계, 가정용 저울, 전자저울처럼 생활에서 쓰는 저울도 많아요. 물건을 사고팔 때나 요리할 때, 몸무게를 잴 때 저울로 정확한 무게를 알 수 있어요."], "example": "양팔저울 한쪽에 사과, 다른 쪽에 귤을 올렸더니 사과 쪽이 내려갔다면 사과가 더 무거워요.", "figure": "양팔저울 한쪽에 사과, 다른 쪽에 귤을 올려 사과 쪽이 내려간 모습"}], "keywords": [{"word": "무게", "meaning": "지구가 물체를 끌어당기는 힘의 크기"}, {"word": "용수철저울", "meaning": "용수철이 늘어나는 길이로 무게를 재는 저울"}, {"word": "받침점", "meaning": "수평 잡기에서 물체를 받치는 가운데 점"}, {"word": "수평", "meaning": "어느 쪽으로도 기울지 않은 상태"}, {"word": "양팔저울", "meaning": "수평 잡기 원리로 두 물체의 무게를 비교하는 저울"}], "expressions": [], "quiz": [{"q": "무게는 무엇일까요?", "choices": ["물체의 크기", "물체의 색깔", "지구가 물체를 끌어당기는 힘의 크기", "물체의 온도"], "answer": 2, "explain": "지구가 물체를 끌어당기는 힘의 크기를 무게라고 해요."}, {"q": "추 1개를 걸면 3cm 늘어나는 용수철에 같은 추 4개를 걸면 몇 cm 늘어날까요?", "choices": ["7cm", "12cm", "4cm", "9cm"], "answer": 1, "explain": "추 1개마다 3cm씩 일정하게 늘어나므로 3×4=12cm예요."}, {"q": "시소에서 몸무게가 다른 두 사람이 수평을 잡으려면?", "choices": ["무거운 사람이 받침점에 더 가깝게 앉는다", "가벼운 사람이 받침점에 더 가깝게 앉는다", "둘 다 끝에 앉는다", "둘 다 일어선다"], "answer": 0, "explain": "무거운 물체는 받침점에 더 가깝게 놓아야 수평이 돼요."}, {"q": "양팔저울에서 왼쪽 접시가 아래로 내려갔어요. 어느 쪽이 더 무거울까요?", "choices": ["오른쪽", "왼쪽", "둘이 같다", "알 수 없다"], "answer": 1, "explain": "양팔저울은 더 무거운 쪽이 아래로 내려가요."}, {"q": "무게가 같은 두 물체로 수평을 잡으려면?", "choices": ["한 물체를 받침점 위에 놓는다", "한쪽에만 놓는다", "받침점에서 같은 거리에 놓는다", "아무 데나 놓는다"], "answer": 2, "explain": "무게가 같으면 받침점에서 같은 거리에 놓아야 수평이 돼요."}], "summary": ["무게는 지구가 물체를 끌어당기는 힘의 크기예요.", "용수철은 무게에 따라 일정하게 늘어나며, 이를 이용해 무게를 재요.", "무거운 물체는 받침점에 가깝게 놓아야 수평이 잡혀요."], "parent_tip": "부모님께: 아이들은 '크면 무겁다'고 생각하기 쉽습니다. 크기는 크지만 가벼운 스펀지와 작지만 무거운 쇠붙이를 들어 보게 하고, '시소에서 엄마랑 균형을 맞추려면 누가 어디에 앉아야 할까?'를 물어보면 수평 잡기 원리를 쉽게 떠올립니다."}$json$::jsonb,4) on conflict (slug) do nothing;
update public.topics set lesson_slug='s3-04' where band='3~4' and subject='과학' and name='물체의 무게';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('s3-05','3~4','과학','혼합물의 분리','섞인 물질을 어떻게 다시 나눌까?','assets/img/l_s3-05.jpg',$json${"intro": "콩, 팥, 좁쌀이 한 그릇에 뒤섞였어요. 하나하나 손으로 골라내려면 너무 오래 걸리겠죠? 더 쉬운 방법이 있을까요?", "sections": [{"heading": "혼합물이란?", "paras": ["두 가지 이상의 물질이 섞여 있는 것을 '혼합물'이라고 해요. 섞여 있어도 각 물질의 성질은 그대로 남아 있어요.", "김밥, 팥빙수, 잡곡, 바닷물(물+소금)도 모두 혼합물이에요. 그래서 각 물질의 성질 차이를 이용하면 다시 나눌(분리할) 수 있어요."], "example": "콩·팥·좁쌀을 섞어도 콩은 콩대로, 팥은 팥대로 크기와 색이 그대로예요.", "figure": "콩, 팥, 좁쌀이 섞인 그릇 그림"}, {"heading": "알갱이 크기로 나누기 – 체", "paras": ["알갱이의 크기가 다른 혼합물은 '체'로 나눌 수 있어요. 체의 눈보다 작은 알갱이는 빠져나가고 큰 알갱이는 체에 남아요.", "눈의 크기가 다른 체를 차례로 쓰면 콩, 팥, 좁쌀을 모두 나눌 수 있어요."], "example": "모래사장에서 체로 모래를 거르면 조개껍데기만 남아요.", "figure": "눈 크기가 다른 체 두 개로 콩, 팥, 좁쌀을 차례로 분리하는 과정 그림"}, {"heading": "자석으로 나누기", "paras": ["철로 된 물체가 섞여 있으면 자석으로 쉽게 골라낼 수 있어요. 자석에 붙는 성질을 이용한 것이지요.", "재활용 공장에서는 큰 자석으로 철 캔과 알루미늄 캔을 나눠요."], "example": "모래 속에 섞인 철 가루는 자석을 대면 자석에 달라붙어 나와요.", "figure": "모래와 철 가루 혼합물에 자석을 대어 철 가루만 끌려 나오는 모습"}, {"heading": "물에 녹는 성질로 나누기 – 거름", "paras": ["소금과 모래가 섞여 있으면 먼저 물을 부어 저어요. 소금은 물에 녹고 모래는 녹지 않아요.", "이것을 거름종이를 올린 깔때기에 부으면 모래는 거름종이 위에 남고 소금물만 아래로 빠져요. 이렇게 거름종이로 거르는 것을 '거름'이라고 해요."], "example": "커피를 내릴 때 커피 가루는 필터에 남고 커피 물만 내려오는 것도 거름이에요.", "figure": "깔때기에 거름종이를 끼우고 소금물과 모래를 부어 거르는 실험 장치 그림"}, {"heading": "물을 날려 보내 나누기 – 증발", "paras": ["거름으로 얻은 소금물을 가열하거나 햇볕에 오래 두면 물이 증발해 날아가고 하얀 소금만 남아요.", "바닷가 염전에서는 바닷물을 햇볕과 바람에 증발시켜 소금을 얻어요."], "example": "", "figure": "넓은 염전에 바닷물을 가두고 하얀 소금을 긁어모으는 모습"}], "keywords": [{"word": "혼합물", "meaning": "두 가지 이상의 물질이 섞여 있는 것"}, {"word": "분리", "meaning": "섞여 있는 물질을 나누는 것"}, {"word": "체", "meaning": "알갱이 크기 차이로 물질을 나누는 도구"}, {"word": "거름", "meaning": "거름종이로 녹지 않은 물질을 걸러 내는 방법"}, {"word": "증발", "meaning": "물이 표면에서 수증기가 되어 날아가는 것"}], "expressions": [], "quiz": [{"q": "다음 중 혼합물이 아닌 것은?", "choices": ["팥빙수", "잡곡", "바닷물", "순수한 물"], "answer": 3, "explain": "순수한 물은 한 가지 물질이에요. 나머지는 여러 물질이 섞인 혼합물이에요."}, {"q": "콩과 좁쌀이 섞여 있을 때 가장 쉽게 나누는 방법은?", "choices": ["체로 거른다", "물에 녹인다", "불로 태운다", "자석을 댄다"], "answer": 0, "explain": "콩과 좁쌀은 알갱이 크기가 달라서 체로 나눌 수 있어요."}, {"q": "모래와 철 가루를 나누는 데 알맞은 도구는?", "choices": ["거름종이", "체", "자석", "돋보기"], "answer": 2, "explain": "철 가루는 자석에 붙고 모래는 붙지 않아요."}, {"q": "소금과 모래 혼합물을 물에 녹여 거르면 거름종이 위에 남는 것은?", "choices": ["소금", "모래", "소금물", "아무것도 안 남는다"], "answer": 1, "explain": "모래는 물에 녹지 않아 거름종이 위에 남고, 소금은 물에 녹아 빠져나가요."}, {"q": "소금물에서 소금을 얻으려면 어떻게 해야 할까요?", "choices": ["체로 거른다", "자석을 댄다", "얼린다", "물을 증발시킨다"], "answer": 3, "explain": "물이 증발해 날아가면 소금만 남아요."}], "summary": ["혼합물은 여러 물질이 섞인 것이고, 섞여도 각 물질의 성질은 그대로예요.", "크기는 체, 철은 자석, 녹는 성질은 거름으로 나눠요.", "소금물의 물을 증발시키면 소금을 얻을 수 있어요."], "parent_tip": "부모님께: 아이들은 소금이 물에 녹으면 '없어졌다'고 생각하곤 합니다. 소금물을 조금 맛보게 하거나 접시에 담아 며칠 두어 소금이 다시 나타나는 것을 보여 주세요. '주방에서 혼합물을 나누는 도구는 뭐가 있을까?'(체, 커피 필터, 국자 등)를 함께 찾아보는 것도 좋습니다."}$json$::jsonb,5) on conflict (slug) do nothing;
update public.topics set lesson_slug='s3-05' where band='3~4' and subject='과학' and name='혼합물의 분리';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('s3-06','3~4','과학','동물의 한살이','동물은 어떻게 태어나고 자랄까?','assets/img/l_s3-06.jpg',$json${"intro": "봄에 배추밭을 날던 흰나비는 어디에서 왔을까요? 처음부터 나비였을까요?", "sections": [{"heading": "한살이란?", "paras": ["동물이 알이나 새끼로 태어나서 자라 어른이 되고, 다시 알이나 새끼를 낳는 과정을 '한살이'라고 해요.", "동물마다 한살이 모습이 달라요. 어떤 동물은 자라면서 생김새가 크게 바뀌고, 어떤 동물은 모습이 거의 그대로예요."], "example": "", "figure": "알에서 어른까지 둥글게 이어진 한살이 순환 화살표 그림"}, {"heading": "배추흰나비의 한살이", "paras": ["배추흰나비는 '알 → 애벌레 → 번데기 → 어른벌레(나비)' 순서로 자라요. 알은 주로 배추나 케일 잎 뒷면에 낳아요.", "애벌레는 잎을 먹으며 허물을 벗고 자라요. 번데기 때는 아무것도 먹지 않고 움직이지 않지만, 그 안에서 어른벌레로 변하고 있어요."], "example": "배추흰나비 애벌레는 배추 잎을 갉아 먹어 잎에 구멍을 내요.", "figure": "배추흰나비의 알, 애벌레, 번데기, 어른벌레를 순서대로 그린 그림"}, {"heading": "완전 탈바꿈과 불완전 탈바꿈", "paras": ["배추흰나비, 나비, 벌, 파리, 무당벌레처럼 번데기 단계를 거치는 것을 '완전 탈바꿈'이라고 해요.", "잠자리, 매미, 메뚜기, 사마귀는 '알 → 애벌레 → 어른벌레'로 자라고 번데기 단계가 없어요. 이것을 '불완전 탈바꿈'이라고 해요."], "example": "잠자리 애벌레(학배기)는 물속에서 살다가 물 밖으로 나와 허물을 벗고 잠자리가 돼요.", "figure": "완전 탈바꿈(알-애벌레-번데기-어른)과 불완전 탈바꿈(알-애벌레-어른)을 위아래로 비교한 그림"}, {"heading": "알을 낳는 동물, 새끼를 낳는 동물", "paras": ["닭, 개구리, 거북, 물고기처럼 알을 낳는 동물이 있어요. 닭의 알은 약 21일 동안 품으면 병아리가 깨어나요.", "개, 고양이, 소, 사람처럼 새끼를 낳는 동물은 어미 배 속에서 어느 정도 자란 뒤 태어나고, 어릴 때 어미젖을 먹고 자라요."], "example": "개구리는 알 → 올챙이 → 개구리 순서로 자라면서 아가미 대신 폐로 숨 쉬게 돼요.", "figure": "알을 낳는 동물(닭, 개구리)과 새끼를 낳는 동물(개, 소)을 나눈 그림"}], "keywords": [{"word": "한살이", "meaning": "동물이 태어나 자라서 자손을 남기는 과정"}, {"word": "애벌레", "meaning": "알에서 깨어난 어린 곤충"}, {"word": "번데기", "meaning": "애벌레가 어른벌레가 되기 전 움직이지 않는 단계"}, {"word": "완전 탈바꿈", "meaning": "알-애벌레-번데기-어른벌레로 자라는 것"}, {"word": "불완전 탈바꿈", "meaning": "번데기 단계 없이 알-애벌레-어른벌레로 자라는 것"}], "expressions": [], "quiz": [{"q": "배추흰나비의 한살이 순서로 옳은 것은?", "choices": ["알 → 번데기 → 애벌레 → 어른벌레", "알 → 애벌레 → 번데기 → 어른벌레", "애벌레 → 알 → 번데기 → 어른벌레", "알 → 어른벌레 → 애벌레 → 번데기"], "answer": 1, "explain": "배추흰나비는 알, 애벌레, 번데기, 어른벌레 순서로 자라요."}, {"q": "번데기 단계가 없는 불완전 탈바꿈을 하는 곤충은?", "choices": ["배추흰나비", "벌", "잠자리", "무당벌레"], "answer": 2, "explain": "잠자리는 알-애벌레-어른벌레로 자라 번데기 단계가 없어요."}, {"q": "배추흰나비 애벌레가 자라면서 하는 일은?", "choices": ["허물을 벗는다", "알을 낳는다", "날개로 난다", "꽃꿀을 빤다"], "answer": 0, "explain": "애벌레는 잎을 먹고 여러 번 허물을 벗으며 커져요."}, {"q": "다음 중 새끼를 낳는 동물은?", "choices": ["닭", "개구리", "거북", "고양이"], "answer": 3, "explain": "고양이는 새끼를 낳고 젖을 먹여 길러요. 나머지는 알을 낳아요."}, {"q": "번데기 시기의 특징으로 옳은 것은?", "choices": ["잎을 많이 먹는다", "거의 움직이지 않고 먹지 않는다", "알을 낳는다", "날아다닌다"], "answer": 1, "explain": "번데기는 먹지 않고 움직이지 않지만 안에서 어른벌레로 변하고 있어요."}], "summary": ["한살이는 동물이 태어나 자라서 자손을 남기는 과정이에요.", "배추흰나비는 알-애벌레-번데기-어른벌레로 자라요(완전 탈바꿈).", "잠자리처럼 번데기 없이 자라는 것은 불완전 탈바꿈이에요."], "parent_tip": "부모님께: 아이들은 애벌레와 나비를 서로 다른 동물로 생각하기 쉽습니다. 나비 사진과 애벌레 사진을 보여 주며 '이 둘이 같은 동물이래, 어떻게 바뀔까?'라고 물어보세요. 사람도 아기-어린이-어른으로 자라지만 탈바꿈은 하지 않는다는 점을 비교해 보면 좋습니다."}$json$::jsonb,6) on conflict (slug) do nothing;
update public.topics set lesson_slug='s3-06' where band='3~4' and subject='과학' and name='동물의 한살이';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('s3-07','3~4','과학','식물의 한살이','씨앗은 어떻게 자라서 다시 씨앗이 될까?','assets/img/l_s3-07.jpg',$json${"intro": "작은 강낭콩 한 알을 심으면 싹이 나고 꽃이 피고, 어느새 콩이 주렁주렁 열려요. 그 과정을 따라가 볼까요?", "sections": [{"heading": "씨가 싹 트려면", "paras": ["씨가 싹 트려면 알맞은 양의 '물'과 알맞은 '온도'가 필요해요. 물을 주지 않거나 너무 추우면 싹이 트지 않아요.", "씨가 싹 틀 때는 씨 속에 들어 있는 양분을 쓰기 때문에 빛이 없어도 싹이 틀 수 있어요. 하지만 싹이 튼 뒤 잘 자라려면 빛이 필요해요."], "example": "물에 적신 솜 위의 강낭콩은 싹이 트고, 마른 솜 위의 강낭콩은 그대로예요.", "figure": "젖은 솜과 마른 솜 위에 놓인 강낭콩을 비교한 그림"}, {"heading": "싹이 트고 자라요", "paras": ["강낭콩은 싹이 틀 때 뿌리가 먼저 나오고, 이어서 떡잎 두 장이 땅 위로 올라와요. 떡잎은 씨 속 양분을 담고 있어서 시간이 지나면 쭈글쭈글해지고 떨어져요.", "그다음 본잎이 나고 줄기가 길어지며 잎의 수가 늘어나요. 식물이 잘 자라려면 물, 빛, 알맞은 온도와 공기가 필요해요."], "example": "콩나물은 빛 없이 길러서 잎이 노랗지만, 햇빛을 받으면 초록색으로 변해요.", "figure": "강낭콩 싹이 트는 과정: 뿌리 → 떡잎 → 본잎 순서 그림"}, {"heading": "꽃이 피고 열매를 맺어요", "paras": ["식물이 충분히 자라면 꽃이 피고, 꽃이 진 자리에 열매가 생겨요. 열매 속에는 다음 한살이를 시작할 씨가 들어 있어요.", "강낭콩은 꼬투리가 열매이고, 그 안의 콩알 하나하나가 씨예요."], "example": "사과를 반으로 자르면 가운데에 작은 씨가 들어 있어요.", "figure": "강낭콩 꽃, 꼬투리, 꼬투리 속 콩알을 순서대로 그린 그림"}, {"heading": "한해살이와 여러해살이", "paras": ["강낭콩, 벼, 옥수수, 해바라기처럼 한 해 안에 한살이를 마치고 죽는 식물을 '한해살이 식물'이라고 해요.", "사과나무, 감나무, 개나리, 무궁화처럼 여러 해 동안 살면서 해마다 꽃과 열매를 맺는 식물을 '여러해살이 식물'이라고 해요."], "example": "벼는 봄에 심어 가을에 거두고 나면 죽지만, 감나무는 해마다 감이 열려요.", "figure": "한해살이(벼, 강낭콩)와 여러해살이(사과나무, 개나리)를 나눈 그림"}], "keywords": [{"word": "한살이", "meaning": "씨가 싹 터서 자라 꽃과 열매를 맺고 다시 씨를 남기는 과정"}, {"word": "떡잎", "meaning": "싹이 틀 때 처음 나오는, 양분을 담은 잎"}, {"word": "본잎", "meaning": "떡잎 다음에 나오는 잎"}, {"word": "한해살이 식물", "meaning": "한 해 안에 한살이를 마치고 죽는 식물"}, {"word": "여러해살이 식물", "meaning": "여러 해 동안 살면서 해마다 꽃과 열매를 맺는 식물"}], "expressions": [], "quiz": [{"q": "씨가 싹 트는 데 꼭 필요한 조건 두 가지는?", "choices": ["빛과 바람", "물과 알맞은 온도", "흙과 비료", "소리와 빛"], "answer": 1, "explain": "씨는 알맞은 물과 온도가 있으면 싹이 터요. 씨 속 양분을 쓰기 때문에 빛은 꼭 필요하지 않아요."}, {"q": "강낭콩이 싹 틀 때 가장 먼저 나오는 것은?", "choices": ["꽃", "본잎", "뿌리", "열매"], "answer": 2, "explain": "강낭콩은 뿌리가 먼저 나오고 그다음 떡잎이 올라와요."}, {"q": "다음 중 한해살이 식물은?", "choices": ["사과나무", "감나무", "개나리", "벼"], "answer": 3, "explain": "벼는 한 해 안에 한살이를 마치는 한해살이 식물이에요."}, {"q": "강낭콩 꼬투리 속 콩알은 무엇일까요?", "choices": ["씨", "뿌리", "떡잎", "꽃잎"], "answer": 0, "explain": "꼬투리는 열매이고 그 안의 콩알이 씨예요."}, {"q": "식물의 한살이 순서로 옳은 것은?", "choices": ["꽃 → 씨 → 싹 → 열매", "싹 → 씨 → 열매 → 꽃", "씨 → 싹 → 꽃 → 열매", "열매 → 꽃 → 싹 → 씨"], "answer": 2, "explain": "씨가 싹 트고 자라 꽃이 피고, 열매를 맺어 다시 씨를 남겨요."}], "summary": ["씨는 알맞은 물과 온도가 있으면 싹 터요.", "식물은 싹 → 자람 → 꽃 → 열매(씨) 순서로 한살이를 해요.", "한해살이 식물은 한 해에, 여러해살이 식물은 여러 해 동안 살아요."], "parent_tip": "부모님께: 아이들은 '씨가 싹 트려면 햇빛이 꼭 필요하다'고 자주 오해합니다. 강낭콩을 젖은 솜에 올려 하나는 밝은 곳, 하나는 어두운 상자 속에 두고 비교해 보세요. '마트에서 파는 콩나물은 왜 노랄까?'라고 물어보는 것도 좋은 대화거리입니다."}$json$::jsonb,7) on conflict (slug) do nothing;
update public.topics set lesson_slug='s3-07' where band='3~4' and subject='과학' and name='식물의 한살이';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('s3-08','3~4','과학','물의 상태 변화','물은 어떻게 얼음과 수증기로 변할까?','assets/img/l_s3-08.jpg',$json${"intro": "냉동실에 넣은 물은 얼음이 되고, 끓는 냄비에서는 김이 올라와요. 물은 어떻게 이렇게 모습을 바꿀까요?", "sections": [{"heading": "물의 세 가지 상태", "paras": ["물은 세 가지 상태로 있어요. 단단하고 모양이 일정한 '얼음(고체)', 흐르고 담는 그릇에 따라 모양이 바뀌는 '물(액체)', 눈에 보이지 않는 '수증기(기체)'예요.", "물은 온도에 따라 얼음, 물, 수증기로 상태가 바뀌어요. 주전자에서 나오는 하얀 김은 사실 수증기가 식어서 생긴 아주 작은 물방울이에요."], "example": "", "figure": "얼음, 물, 수증기가 화살표로 서로 바뀌는 순환 그림"}, {"heading": "물이 얼 때와 얼음이 녹을 때", "paras": ["물이 얼어 얼음이 되면 부피(차지하는 공간)는 늘어나지만, 무게는 변하지 않아요. 그래서 물을 가득 채운 유리병을 얼리면 병이 깨질 수 있어요.", "반대로 얼음이 녹아 물이 되면 부피는 줄어들고 무게는 그대로예요."], "example": "추운 겨울에 수도관 속 물이 얼면 부피가 늘어나 수도관이 터지기도 해요.", "figure": "물을 넣은 시험관과 얼린 뒤 높이가 올라간 시험관 비교 그림"}, {"heading": "물이 수증기가 되는 두 가지 방법", "paras": ["물 표면에서 물이 천천히 수증기로 변하는 것을 '증발'이라고 해요. 젖은 빨래가 마르는 것이 증발이에요.", "물을 가열하면 물 표면뿐 아니라 물속에서도 기포(거품)가 생기며 빠르게 수증기로 변하는데, 이것을 '끓음'이라고 해요. 증발보다 끓음이 훨씬 빨라요."], "example": "어항의 물이 며칠 지나면 조금씩 줄어드는 것은 증발 때문이에요.", "figure": "마르는 빨래(증발)와 보글보글 끓는 냄비(끓음)를 나란히 비교한 그림"}, {"heading": "수증기가 물이 되는 응결", "paras": ["공기 중의 수증기가 차가운 물체 표면에 닿아 물방울로 변하는 것을 '응결'이라고 해요.", "차가운 음료수 컵 겉면에 물방울이 맺히는 것은 컵 안의 물이 새어 나온 것이 아니라, 공기 중 수증기가 응결한 거예요."], "example": "추운 날 따뜻한 방 안의 창문 안쪽에 물방울이 맺히는 것도 응결이에요.", "figure": "얼음물이 든 컵 겉면에 물방울이 맺힌 모습"}], "keywords": [{"word": "얼음", "meaning": "물의 고체 상태로, 단단하고 모양이 일정함"}, {"word": "수증기", "meaning": "물의 기체 상태로, 눈에 보이지 않음"}, {"word": "증발", "meaning": "물 표면에서 물이 수증기로 변하는 것"}, {"word": "끓음", "meaning": "물 표면과 물속에서 물이 수증기로 빠르게 변하는 것"}, {"word": "응결", "meaning": "수증기가 차가운 물체에 닿아 물방울로 변하는 것"}], "expressions": [], "quiz": [{"q": "물이 얼어 얼음이 되면 어떻게 변할까요?", "choices": ["부피와 무게가 모두 늘어난다", "부피는 늘어나고 무게는 같다", "부피는 줄고 무게는 같다", "부피와 무게가 모두 줄어든다"], "answer": 1, "explain": "물이 얼면 부피는 늘어나지만 무게는 변하지 않아요."}, {"q": "젖은 빨래가 마르는 것과 관계있는 것은?", "choices": ["증발", "응결", "끓음", "얼음이 녹음"], "answer": 0, "explain": "물 표면에서 물이 천천히 수증기로 변하는 증발 때문이에요."}, {"q": "차가운 컵 겉면에 물방울이 맺히는 까닭은?", "choices": ["컵 안의 물이 새어 나와서", "컵이 녹아서", "공기 중 수증기가 응결해서", "얼음이 증발해서"], "answer": 2, "explain": "공기 중의 수증기가 차가운 컵에 닿아 물방울로 변한 거예요."}, {"q": "끓음에 대한 설명으로 옳은 것은?", "choices": ["물 표면에서만 천천히 일어난다", "물이 얼음이 되는 것이다", "수증기가 물이 되는 것이다", "물속에서도 기포가 생기며 빠르게 일어난다"], "answer": 3, "explain": "끓음은 물 표면과 물속에서 모두 수증기로 변하며 증발보다 빨라요."}, {"q": "물의 기체 상태를 무엇이라고 할까요?", "choices": ["얼음", "수증기", "이슬", "서리"], "answer": 1, "explain": "물의 기체 상태는 수증기이고 눈에 보이지 않아요."}], "summary": ["물은 온도에 따라 얼음(고체), 물(액체), 수증기(기체)로 상태가 바뀌어요.", "물이 얼면 부피는 늘어나고 무게는 그대로예요.", "물이 수증기가 되는 것은 증발과 끓음, 수증기가 물이 되는 것은 응결이에요."], "parent_tip": "부모님께: 아이들은 주전자의 하얀 김을 수증기라고 생각하거나, 차가운 컵의 물방울을 컵 속 물이 스며 나온 것이라고 생각하기 쉽습니다. 빈 컵에 얼음만 넣어도 겉에 물방울이 맺히는지 함께 확인해 보고, '이 물은 어디서 왔을까?'라고 물어보세요."}$json$::jsonb,8) on conflict (slug) do nothing;
update public.topics set lesson_slug='s3-08' where band='3~4' and subject='과학' and name='물의 상태 변화';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('s3-09','3~4','과학','지구와 달','지구와 달은 어떻게 생겼을까?','assets/img/l_s3-09.jpg',$json${"intro": "밤하늘의 둥근 달을 보면 토끼 모양 무늬가 보여요. 달은 어떤 곳일까요? 그리고 우리가 사는 지구는 어떤 모습일까요?", "sections": [{"heading": "지구는 둥글어요", "paras": ["우주에서 찍은 사진을 보면 지구는 공처럼 둥근 모양이에요. 지구가 너무 커서 땅 위에 서 있는 우리에게는 평평해 보일 뿐이에요.", "지구 표면에는 육지와 바다가 있는데, 바다가 육지보다 훨씬 넓어요. 바다가 지구 표면의 약 70%를 차지해요."], "example": "멀리서 다가오는 배는 꼭대기의 돛부터 보이기 시작하는데, 지구가 둥글기 때문이에요.", "figure": "우주에서 본 파랗고 둥근 지구 사진"}, {"heading": "지구에는 공기와 물이 있어요", "paras": ["지구는 공기로 둘러싸여 있어요. 공기가 있어서 생물이 숨을 쉴 수 있고, 바람이 불고 구름이 생겨요.", "또 지구에는 물이 있어 생물이 살아갈 수 있어요. 알맞은 온도, 공기, 물이 있어서 지구에는 많은 생물이 살아요."], "example": "", "figure": "공기층에 둘러싸인 지구와 바다, 숲, 동물을 함께 그린 그림"}, {"heading": "달은 어떻게 생겼을까요?", "paras": ["달도 지구처럼 둥근 공 모양이에요. 크기는 지구보다 작아서 지름이 지구의 약 4분의 1이에요.", "달 표면의 어둡게 보이는 넓은 곳을 '달의 바다'라고 하는데, 실제로 물이 있는 것은 아니에요. 또 달 표면에는 운석이 부딪쳐 생긴 움푹 파인 구덩이인 '충돌 구덩이(크레이터)'가 많아요."], "example": "보름달의 어두운 무늬(달의 바다)를 보고 옛사람들은 방아 찧는 토끼를 떠올렸어요.", "figure": "달 표면의 어두운 '바다'와 둥근 충돌 구덩이를 표시한 사진"}, {"heading": "지구와 달 비교하기", "paras": ["달에는 공기와 물이 없어요. 그래서 바람이 불지 않고, 생물이 살 수 없어요. 공기가 없어서 소리도 전해지지 않아요.", "또 낮에는 아주 뜨겁고 밤에는 아주 차가워요. 지구는 공기와 물이 있어 생물이 살기에 알맞은 환경이에요."], "example": "달에 간 우주 비행사의 발자국은 바람이 없어서 오랫동안 그대로 남아 있어요.", "figure": "지구와 달을 나란히 놓고 공기·물·생물 유무를 표로 비교한 그림"}], "keywords": [{"word": "육지", "meaning": "지구 표면에서 물로 덮이지 않은 땅"}, {"word": "바다", "meaning": "지구 표면에서 짠물로 덮인 넓은 곳"}, {"word": "공기", "meaning": "지구를 둘러싸고 있어 생물이 숨 쉴 수 있게 해 주는 기체"}, {"word": "달의 바다", "meaning": "달 표면에서 어둡게 보이는 넓고 평평한 곳(물은 없음)"}, {"word": "충돌 구덩이", "meaning": "운석이 부딪쳐 생긴 둥글게 움푹 파인 곳"}], "expressions": [], "quiz": [{"q": "지구 표면에서 더 넓은 곳은?", "choices": ["육지", "바다", "둘이 같다", "알 수 없다"], "answer": 1, "explain": "바다가 지구 표면의 약 70%를 차지해 육지보다 넓어요."}, {"q": "달에 대한 설명으로 옳은 것은?", "choices": ["공기가 많다", "바다에 물이 가득하다", "공기와 물이 없다", "생물이 많이 산다"], "answer": 2, "explain": "달에는 공기와 물이 없어서 생물이 살 수 없어요."}, {"q": "달 표면에 있는 둥글게 움푹 파인 곳을 무엇이라고 할까요?", "choices": ["충돌 구덩이", "화산", "강", "바다"], "answer": 0, "explain": "운석이 부딪쳐 생긴 구덩이를 충돌 구덩이(크레이터)라고 해요."}, {"q": "지구에 생물이 살 수 있는 까닭으로 알맞지 않은 것은?", "choices": ["물이 있다", "공기가 있다", "알맞은 온도이다", "충돌 구덩이가 많다"], "answer": 3, "explain": "지구에는 물, 공기, 알맞은 온도가 있어 생물이 살 수 있어요."}, {"q": "달에서 우주 비행사의 발자국이 오래 남는 까닭은?", "choices": ["달이 차가워서", "달이 작아서", "바람이 불지 않아서", "달이 둥글어서"], "answer": 2, "explain": "달에는 공기가 없어 바람이 불지 않아 발자국이 지워지지 않아요."}], "summary": ["지구는 둥글고, 바다가 육지보다 넓어요.", "지구에는 공기와 물이 있어 생물이 살 수 있어요.", "달은 둥글고 지구보다 작으며, 공기와 물이 없고 충돌 구덩이가 많아요."], "parent_tip": "부모님께: '달의 바다'라는 이름 때문에 달에 물이 있다고 오해하는 아이가 많습니다. 보름달이 뜨는 날 함께 달을 보며 어두운 무늬를 찾아보고, '달에 가면 친구 목소리가 들릴까?'처럼 지구와 비교하는 질문을 해 보세요."}$json$::jsonb,9) on conflict (slug) do nothing;
update public.topics set lesson_slug='s3-09' where band='3~4' and subject='과학' and name='지구와 달';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('s5-01','5~6','과학','우리 몸의 구조와 기능','우리 몸은 어떻게 움직이고 살아갈까?','assets/img/l_s5-01.jpg',$json${"intro": "밥을 먹고, 숨을 쉬고, 달리기를 할 때 우리 몸속에서는 여러 기관이 함께 일하고 있어요. 어떤 기관들이 어떤 일을 할까요?", "sections": [{"heading": "뼈와 근육 – 운동 기관", "paras": ["뼈는 몸의 형태를 만들고 몸을 지탱하며, 뇌·심장·폐 같은 몸속 기관을 보호해요.", "근육은 뼈에 연결되어 있어요. 근육의 길이가 줄어들거나 늘어나면서 뼈를 움직이게 해요. 팔을 구부리면 팔 안쪽 근육이 줄어들면서 아래팔뼈가 올라와요."], "example": "갈비뼈는 새장처럼 심장과 폐를 감싸 보호해요.", "figure": "팔을 구부릴 때 위팔 안쪽 근육이 짧아지는 모습을 나타낸 그림"}, {"heading": "소화 기관 – 음식물을 잘게 부숴요", "paras": ["음식물은 '입 → 식도 → 위 → 작은창자 → 큰창자 → 항문' 순서로 지나가요. 입에서는 이가 음식물을 잘게 부수고 침과 섞어요.", "위는 위액으로 음식물을 더 잘게 쪼개고, 작은창자는 영양소와 물을 흡수해요. 큰창자는 남은 물을 흡수하고, 찌꺼기는 항문으로 나가요. 간, 쓸개, 이자는 소화를 도와요."], "example": "밥을 오래 씹으면 단맛이 나는 것은 침이 녹말을 소화하기 때문이에요.", "figure": "입에서 항문까지 소화 기관과 음식물이 지나가는 경로를 표시한 인체 그림"}, {"heading": "호흡 기관과 순환 기관", "paras": ["숨을 들이마시면 공기가 '코 → 기관 → 기관지 → 폐'로 들어가요. 폐에서는 몸에 필요한 산소를 받아들이고, 몸에서 생긴 이산화 탄소를 내보내요.", "심장은 펌프 작용으로 혈액을 온몸으로 보내요. 혈액은 혈관을 따라 돌면서 영양소와 산소를 온몸에 전해 주고, 다시 심장으로 돌아와요."], "example": "달리기를 하면 숨이 가빠지고 심장이 빨리 뛰는 것은 몸에 산소와 영양소가 더 많이 필요하기 때문이에요.", "figure": "폐와 심장, 온몸으로 퍼진 혈관(빨간색·파란색)을 나타낸 인체 그림"}, {"heading": "배설 기관 – 노폐물을 내보내요", "paras": ["몸속에서 영양소를 쓰고 나면 필요 없는 '노폐물'이 생겨요. 혈액 속 노폐물은 '콩팥'에서 걸러져 오줌이 돼요.", "오줌은 방광에 모였다가 몸 밖으로 나가요. 콩팥은 강낭콩 모양으로 등 쪽 허리에 좌우 한 개씩 있어요."], "example": "물을 많이 마신 날 화장실에 자주 가는 것도 배설 기관이 일하기 때문이에요.", "figure": "콩팥, 오줌관, 방광의 위치를 나타낸 그림"}, {"heading": "감각 기관과 자극의 전달", "paras": ["눈, 귀, 코, 혀, 피부 같은 감각 기관은 빛, 소리, 냄새, 맛, 온도 같은 자극을 받아들여요.", "받아들인 자극은 신경을 통해 뇌로 전달되고, 뇌가 어떻게 행동할지 결정해 다시 신경을 통해 운동 기관에 명령을 보내요."], "example": "날아오는 공을 눈으로 보고 → 뇌가 판단하고 → 손을 뻗어 잡아요.", "figure": "공을 보고 뇌로 신호가 가고, 다시 손으로 명령이 가는 화살표 그림"}], "keywords": [{"word": "운동 기관", "meaning": "뼈와 근육처럼 몸을 움직이게 하는 기관"}, {"word": "소화", "meaning": "음식물을 잘게 쪼개 흡수할 수 있게 만드는 것"}, {"word": "호흡", "meaning": "산소를 받아들이고 이산화 탄소를 내보내는 것"}, {"word": "순환", "meaning": "심장의 펌프 작용으로 혈액이 온몸을 도는 것"}, {"word": "배설", "meaning": "몸속 노폐물을 몸 밖으로 내보내는 것"}, {"word": "자극", "meaning": "감각 기관이 받아들이는 빛, 소리, 냄새 같은 신호"}], "expressions": [], "quiz": [{"q": "음식물이 지나가는 순서로 옳은 것은?", "choices": ["입 → 위 → 식도 → 작은창자 → 큰창자", "입 → 식도 → 위 → 작은창자 → 큰창자", "입 → 식도 → 큰창자 → 위 → 작은창자", "입 → 위 → 작은창자 → 식도 → 큰창자"], "answer": 1, "explain": "음식물은 입, 식도, 위, 작은창자, 큰창자를 지나 항문으로 나가요."}, {"q": "혈액을 온몸으로 보내는 펌프 역할을 하는 기관은?", "choices": ["폐", "위", "심장", "콩팥"], "answer": 2, "explain": "심장이 펌프 작용으로 혈액을 온몸으로 보내요."}, {"q": "혈액 속 노폐물을 걸러 오줌을 만드는 기관은?", "choices": ["콩팥", "방광", "간", "큰창자"], "answer": 0, "explain": "콩팥이 혈액 속 노폐물을 걸러 오줌을 만들고, 방광은 오줌을 모아 둬요."}, {"q": "폐에서 일어나는 일로 옳은 것은?", "choices": ["음식물을 소화한다", "오줌을 만든다", "혈액을 만든다", "산소를 받아들이고 이산화 탄소를 내보낸다"], "answer": 3, "explain": "폐는 호흡 기관으로 산소와 이산화 탄소를 주고받아요."}, {"q": "뼈를 움직이게 하는 것은?", "choices": ["신경만", "근육의 길이 변화", "혈액", "피부"], "answer": 1, "explain": "뼈에 연결된 근육이 줄어들거나 늘어나면서 뼈가 움직여요."}], "summary": ["뼈와 근육은 몸을 지탱하고 움직이게 해요.", "소화·호흡·순환·배설 기관이 함께 영양소와 산소를 얻고 노폐물을 내보내요.", "감각 기관이 받은 자극은 신경을 통해 뇌로 전달되고, 뇌가 행동을 명령해요."], "parent_tip": "부모님께: 아이들은 위가 영양소를 흡수한다고 생각하거나, 방광이 오줌을 만든다고 헷갈리곤 합니다. 저녁 식사 때 '지금 먹은 밥은 어디를 지나가게 될까?', '줄넘기를 하고 나면 왜 숨이 차고 심장이 빨리 뛸까?' 같은 질문으로 여러 기관이 함께 일한다는 점을 이야기해 보세요."}$json$::jsonb,101) on conflict (slug) do nothing;
update public.topics set lesson_slug='s5-01' where band='5~6' and subject='과학' and name='우리 몸의 구조와 기능';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('s5-02','5~6','과학','산과 염기','식초와 비눗물은 무엇이 다를까?','assets/img/l_s5-02.jpg',$json${"intro": "레몬즙은 시큼하고, 비눗물은 미끌미끌해요. 우리 주변의 용액은 성질에 따라 어떻게 나눌 수 있을까요?", "sections": [{"heading": "지시약으로 용액 분류하기", "paras": ["용액의 성질에 따라 색깔이 변하는 물질을 '지시약'이라고 해요. 지시약을 쓰면 겉보기에 비슷한 용액도 산성과 염기성으로 나눌 수 있어요.", "리트머스 종이를 쓰면, 산성 용액은 푸른색 리트머스 종이를 붉은색으로, 염기성 용액은 붉은색 리트머스 종이를 푸른색으로 바꿔요."], "example": "식초에 푸른색 리트머스 종이를 넣으면 붉게 변해요. 식초는 산성이에요.", "figure": "푸른색 리트머스 종이가 식초에서 붉게, 붉은색 리트머스 종이가 비눗물에서 푸르게 변하는 그림"}, {"heading": "여러 가지 지시약", "paras": ["페놀프탈레인 용액은 산성 용액에서는 색깔이 변하지 않고, 염기성 용액에서는 붉은색으로 변해요.", "붉은 양배추로 만든 지시약은 산성 용액에서 붉은색 계열, 염기성 용액에서 푸른색이나 노란색 계열로 변해요. BTB 용액은 산성에서 노란색, 염기성에서 파란색으로 변해요."], "example": "붉은 양배추 지시약에 레몬즙을 넣으면 붉게, 비눗물을 넣으면 푸르게 변해요.", "figure": "붉은 양배추 지시약이 담긴 시험관들이 산성(붉은색)부터 염기성(푸른·노란색)까지 색이 다른 모습"}, {"heading": "산성 용액과 염기성 용액의 성질", "paras": ["산성 용액은 대리석이나 달걀 껍데기를 녹이는 성질이 있어요. 넣으면 기포가 생기면서 녹아요.", "염기성 용액은 두부나 삶은 달걀흰자 같은 단백질을 녹여 흐물흐물하게 만들어요."], "example": "대리석으로 만든 문화재는 산성비에 조금씩 녹아 훼손될 수 있어요.", "figure": "묽은 염산에 달걀 껍데기를 넣어 기포가 생기는 모습과 수산화 나트륨 용액에 두부가 흐물해진 모습"}, {"heading": "산성 용액과 염기성 용액을 섞으면", "paras": ["산성 용액에 염기성 용액을 조금씩 넣으면 산성이 점점 약해지다가 염기성으로 바뀌어요. 반대로 염기성 용액에 산성 용액을 넣으면 염기성이 점점 약해져요.", "이 성질은 생활에서 많이 쓰여요. 속이 쓰릴 때 먹는 제산제(염기성)는 위산(산성)을 약하게 하고, 생선을 손질한 도마를 식초(산성)로 닦으면 비린내(염기성)가 줄어요."], "example": "벌레에게 물려 가려울 때 염기성인 암모니아수를 바르는 것도 같은 원리예요.", "figure": "산성 용액에 염기성 용액을 한 방울씩 넣을 때 지시약 색이 바뀌는 시험관 그림"}], "keywords": [{"word": "지시약", "meaning": "용액의 성질에 따라 색깔이 변하는 물질"}, {"word": "산성 용액", "meaning": "푸른색 리트머스 종이를 붉게 바꾸는 용액"}, {"word": "염기성 용액", "meaning": "붉은색 리트머스 종이를 푸르게 바꾸는 용액"}, {"word": "리트머스 종이", "meaning": "산성·염기성을 알아보는 종이 지시약"}, {"word": "페놀프탈레인 용액", "meaning": "염기성 용액에서만 붉은색으로 변하는 지시약"}], "expressions": [], "quiz": [{"q": "푸른색 리트머스 종이를 붉은색으로 바꾸는 용액은?", "choices": ["식초", "비눗물", "유리 세정제", "석회수"], "answer": 0, "explain": "식초는 산성 용액이라 푸른색 리트머스 종이를 붉게 바꿔요."}, {"q": "페놀프탈레인 용액을 넣었을 때 붉은색으로 변하는 용액은?", "choices": ["레몬즙", "식초", "비눗물", "탄산수"], "answer": 2, "explain": "페놀프탈레인 용액은 염기성 용액에서 붉은색으로 변해요."}, {"q": "달걀 껍데기를 넣었을 때 기포가 생기며 녹는 용액은?", "choices": ["산성 용액", "염기성 용액", "모든 용액", "어떤 용액도 녹이지 않음"], "answer": 0, "explain": "산성 용액은 달걀 껍데기나 대리석을 녹여요."}, {"q": "두부를 넣었을 때 두부가 흐물흐물해지는 용액은?", "choices": ["산성 용액", "염기성 용액", "물", "설탕물"], "answer": 1, "explain": "염기성 용액은 두부나 삶은 달걀흰자를 녹여요."}, {"q": "속이 쓰릴 때 먹는 제산제의 원리로 옳은 것은?", "choices": ["산성 물질로 위산을 강하게 한다", "위를 차갑게 한다", "염기성 물질로 위산의 산성을 약하게 한다", "음식을 녹인다"], "answer": 2, "explain": "제산제는 염기성이라서 산성인 위산을 약하게 해요."}], "summary": ["지시약을 쓰면 용액을 산성과 염기성으로 분류할 수 있어요.", "산성은 대리석·달걀 껍데기를, 염기성은 두부·달걀흰자를 녹여요.", "산성과 염기성 용액을 섞으면 서로의 성질이 약해져요."], "parent_tip": "부모님께: 아이들은 '산성은 위험하고 염기성은 안전하다'처럼 단순하게 생각하기도 합니다. 집에서 붉은 양배추 물을 끓여 식초, 레몬즙, 베이킹 소다 물, 비눗물 등에 넣어 색 변화를 보며 '어느 쪽이 산성일까?'를 함께 맞혀 보세요. 세제류는 반드시 보호자가 다뤄 주세요."}$json$::jsonb,102) on conflict (slug) do nothing;
update public.topics set lesson_slug='s5-02' where band='5~6' and subject='과학' and name='산과 염기';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('s5-03','5~6','과학','빛과 렌즈','돋보기로 보면 왜 크게 보일까?','assets/img/l_s5-03.jpg',$json${"intro": "돋보기로 개미를 보면 커다랗게 보이고, 햇빛을 한 점에 모으면 종이를 태울 수도 있어요. 렌즈는 어떻게 빛을 다룰까요?", "sections": [{"heading": "햇빛은 여러 빛깔로 되어 있어요", "paras": ["햇빛을 프리즘에 통과시키면 하얀 종이 위에 빨강, 주황, 노랑, 초록, 파랑, 남색, 보라처럼 여러 빛깔이 나타나요.", "이것으로 햇빛이 여러 가지 빛깔의 빛으로 이루어져 있다는 것을 알 수 있어요."], "example": "비가 그친 뒤 하늘에 생기는 무지개는 공기 중 물방울이 프리즘처럼 햇빛을 여러 빛깔로 나눈 거예요.", "figure": "프리즘을 통과한 햇빛이 무지갯빛으로 나뉘는 그림"}, {"heading": "빛은 경계에서 꺾여요 – 굴절", "paras": ["빛이 공기 중에서 물이나 유리로 비스듬히 들어가면 두 물질의 경계에서 꺾여 나아가요. 이것을 '빛의 굴절'이라고 해요.", "빛이 경계에 수직으로(똑바로) 들어가면 꺾이지 않고 그대로 나아가요."], "example": "물이 든 컵에 젓가락을 넣으면 젓가락이 수면에서 꺾여 보여요.", "figure": "물컵 속 젓가락이 수면에서 꺾여 보이는 모습과 빛이 꺾이는 경로 화살표"}, {"heading": "볼록 렌즈의 특징", "paras": ["볼록 렌즈는 가운데가 가장자리보다 두꺼운 렌즈예요. 볼록 렌즈를 통과한 빛은 굴절하여 한 곳으로 모여요.", "햇빛을 볼록 렌즈로 모으면 빛이 모인 곳은 더 밝고 온도도 높아요. 그래서 검은 종이를 태울 수 있어요(눈으로 직접 보면 위험해요!)."], "example": "물이 담긴 둥근 어항이나 유리구슬도 볼록 렌즈처럼 빛을 모을 수 있어요.", "figure": "볼록 렌즈를 통과한 평행한 햇빛이 한 점으로 모이는 그림"}, {"heading": "볼록 렌즈로 본 모습", "paras": ["볼록 렌즈로 가까운 물체를 보면 실제보다 크게 보여요. 멀리 있는 물체를 보면 상하좌우가 바뀌어(거꾸로) 보이기도 해요.", "볼록 렌즈의 성질을 이용한 도구로는 돋보기, 현미경, 망원경, 사진기, 확대경 등이 있어요."], "example": "간이 사진기를 만들면 볼록 렌즈 때문에 스크린에 바깥 풍경이 거꾸로 비쳐요.", "figure": "돋보기로 가까운 글자는 크게, 먼 풍경은 거꾸로 보이는 두 장면 비교"}], "keywords": [{"word": "프리즘", "meaning": "빛을 여러 빛깔로 나누는 투명한 삼각기둥 모양의 기구"}, {"word": "빛의 굴절", "meaning": "빛이 서로 다른 물질의 경계에서 꺾여 나아가는 것"}, {"word": "볼록 렌즈", "meaning": "가운데가 가장자리보다 두꺼운 렌즈"}, {"word": "돋보기", "meaning": "볼록 렌즈로 물체를 크게 보이게 하는 도구"}, {"word": "간이 사진기", "meaning": "볼록 렌즈와 스크린으로 만든 간단한 사진기"}], "expressions": [], "quiz": [{"q": "프리즘에 햇빛을 통과시키면 어떻게 될까요?", "choices": ["빛이 사라진다", "여러 빛깔로 나뉜다", "검은색이 된다", "빛이 더 하얘진다"], "answer": 1, "explain": "햇빛은 여러 빛깔의 빛으로 이루어져 있어 프리즘을 지나면 나뉘어 보여요."}, {"q": "물이 든 컵 속 젓가락이 꺾여 보이는 까닭은?", "choices": ["빛의 굴절", "빛의 반사", "그림자", "소리의 반사"], "answer": 0, "explain": "빛이 물과 공기의 경계에서 꺾이기 때문이에요."}, {"q": "볼록 렌즈의 모양으로 옳은 것은?", "choices": ["가장자리가 가운데보다 두껍다", "모든 곳의 두께가 같다", "가운데가 가장자리보다 두껍다", "가운데에 구멍이 있다"], "answer": 2, "explain": "볼록 렌즈는 가운데가 가장자리보다 두꺼워요."}, {"q": "볼록 렌즈를 이용한 도구가 아닌 것은?", "choices": ["돋보기", "현미경", "사진기", "평면 거울"], "answer": 3, "explain": "평면 거울은 빛을 반사하는 도구이고 렌즈가 아니에요."}, {"q": "볼록 렌즈로 햇빛을 모은 곳의 특징은?", "choices": ["더 어둡고 차갑다", "더 밝고 온도가 높다", "색이 검게 변한다", "아무 변화가 없다"], "answer": 1, "explain": "빛이 한 곳에 모여서 그곳은 밝고 뜨거워져요."}], "summary": ["햇빛은 여러 빛깔의 빛으로 이루어져 있어요.", "빛은 서로 다른 물질의 경계에서 꺾여요(굴절).", "볼록 렌즈는 빛을 모으고, 물체를 크게 또는 거꾸로 보이게 해요."], "parent_tip": "부모님께: 아이들은 빛의 '반사'와 '굴절'을 헷갈려 합니다. 거울에 비친 모습은 반사, 물컵 속 빨대가 꺾여 보이는 것은 굴절이라고 짝지어 주세요. 돋보기로 햇빛을 모으는 활동은 반드시 보호자와 함께하고, 렌즈로 해를 직접 보지 않도록 알려 주세요."}$json$::jsonb,103) on conflict (slug) do nothing;
update public.topics set lesson_slug='s5-03' where band='5~6' and subject='과학' and name='빛과 렌즈';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('s5-04','5~6','과학','태양계와 별','태양계에는 어떤 행성들이 있을까?','assets/img/l_s5-04.jpg',$json${"intro": "밤하늘에는 반짝이는 별이 가득해요. 그런데 그중에는 별이 아닌 '행성'도 섞여 있다는 사실, 알고 있나요?", "sections": [{"heading": "태양은 우리에게 꼭 필요해요", "paras": ["태양은 스스로 빛과 열을 내는 별이에요. 태양 빛 덕분에 식물이 양분을 만들고, 동물은 그 식물을 먹고 살아요.", "태양은 물을 증발시켜 비와 눈이 내리게 하고, 우리가 생활하기에 알맞은 온도를 만들어 줘요. 태양이 없다면 지구의 생물은 살 수 없어요."], "example": "햇빛으로 전기를 만드는 태양 전지판, 바닷물을 말려 소금을 얻는 염전도 태양 에너지를 이용해요.", "figure": "태양 빛을 받아 자라는 식물, 태양 전지판, 염전 그림"}, {"heading": "태양계의 구성원", "paras": ["태양과 태양의 영향을 받는 천체들, 그리고 그 공간을 '태양계'라고 해요. 태양계의 중심에는 태양이 있어요.", "태양 둘레를 도는 행성은 태양에서 가까운 순서대로 수성, 금성, 지구, 화성, 목성, 토성, 천왕성, 해왕성 8개예요. 달처럼 행성 둘레를 도는 천체는 '위성'이라고 해요."], "example": "외우기 팁: '수·금·지·화·목·토·천·해'!", "figure": "태양을 중심으로 8개 행성이 순서대로 늘어선 태양계 그림"}, {"heading": "행성의 크기와 거리", "paras": ["태양계 행성 중 가장 큰 것은 목성이고, 가장 작은 것은 수성이에요. 지구를 기준으로 보면 목성은 지름이 지구의 약 11배나 돼요.", "수성, 금성, 지구, 화성은 상대적으로 작고 표면이 암석으로 되어 있어요. 목성, 토성, 천왕성, 해왕성은 크고 주로 기체로 되어 있으며 고리가 있어요. 태양에서 멀수록 행성 사이의 거리도 대체로 멀어요."], "example": "지구 지름을 1이라고 하면 목성은 약 11.2, 수성은 약 0.4예요.", "figure": "지구 크기를 1로 놓고 8개 행성의 크기를 비교한 막대 또는 원 그림"}, {"heading": "별과 행성은 달라요", "paras": ["별은 태양처럼 스스로 빛을 내는 천체예요. 행성은 스스로 빛을 내지 못하고 태양 빛을 반사해서 밝게 보여요.", "별은 아주 멀리 있어서 여러 날 관측해도 위치가 거의 변하지 않지만, 행성은 태양 둘레를 돌기 때문에 여러 날 관측하면 별들 사이에서 위치가 조금씩 바뀌어요."], "example": "새벽이나 저녁에 아주 밝게 보이는 '샛별'은 별이 아니라 행성인 금성이에요.", "figure": "며칠 동안 별자리 사이에서 위치가 바뀐 행성을 점선으로 표시한 그림"}, {"heading": "북쪽 하늘의 별자리와 북극성", "paras": ["옛날 사람들은 밝은 별들을 이어 동물이나 물건 모양을 떠올려 '별자리'라고 이름 붙였어요. 북쪽 하늘에는 북두칠성, 카시오페이아자리, 작은곰자리가 있어요.", "북극성은 항상 북쪽 하늘에 있어서 방위를 찾는 데 도움이 돼요. 북두칠성 국자 끝의 두 별을 이은 거리의 약 5배만큼 떨어진 곳에 북극성이 있어요. 카시오페이아자리를 이용해서도 찾을 수 있어요."], "example": "북극성을 바라보면 내가 바라보는 쪽이 북쪽, 등 뒤가 남쪽이에요.", "figure": "북두칠성 국자 끝 두 별에서 5배 거리에 북극성을 찾는 방법을 나타낸 별자리 그림"}], "keywords": [{"word": "태양계", "meaning": "태양과 태양의 영향을 받는 천체들, 그리고 그 공간"}, {"word": "행성", "meaning": "태양 둘레를 도는, 스스로 빛을 내지 못하는 천체"}, {"word": "위성", "meaning": "행성 둘레를 도는 천체(예: 달)"}, {"word": "별", "meaning": "스스로 빛을 내는 천체"}, {"word": "별자리", "meaning": "밝은 별들을 이어 이름을 붙인 것"}, {"word": "북극성", "meaning": "항상 북쪽 하늘에 있어 방위를 알려 주는 별"}], "expressions": [], "quiz": [{"q": "태양계에서 가장 큰 행성은?", "choices": ["지구", "토성", "목성", "해왕성"], "answer": 2, "explain": "목성이 가장 크며 지름이 지구의 약 11배예요."}, {"q": "태양에서 가장 가까운 행성은?", "choices": ["수성", "금성", "지구", "화성"], "answer": 0, "explain": "태양에서 가까운 순서는 수성, 금성, 지구, 화성…이에요."}, {"q": "별과 행성의 차이로 옳은 것은?", "choices": ["행성은 스스로 빛을 낸다", "별은 태양 둘레를 돈다", "별은 스스로 빛을 내고, 행성은 태양 빛을 반사한다", "별과 행성은 같은 것이다"], "answer": 2, "explain": "별은 스스로 빛을 내지만 행성은 태양 빛을 반사해 밝게 보여요."}, {"q": "북두칠성으로 북극성을 찾을 때, 국자 끝 두 별 사이 거리의 몇 배만큼 가면 될까요?", "choices": ["2배", "3배", "5배", "10배"], "answer": 2, "explain": "국자 끝 두 별을 이은 거리의 약 5배 떨어진 곳에 북극성이 있어요."}, {"q": "태양이 우리 생활에 주는 영향이 아닌 것은?", "choices": ["식물이 양분을 만든다", "물이 증발해 비가 내린다", "알맞은 온도를 만든다", "밀물과 썰물을 주로 일으킨다"], "answer": 3, "explain": "밀물과 썰물은 주로 달의 영향으로 생겨요. 나머지는 태양 덕분이에요."}], "summary": ["태양은 스스로 빛과 열을 내며 지구의 생물에게 꼭 필요해요.", "태양계 행성은 수성·금성·지구·화성·목성·토성·천왕성·해왕성 8개이고, 목성이 가장 커요.", "별은 스스로 빛을 내고, 북극성은 북두칠성이나 카시오페이아자리로 찾을 수 있어요."], "parent_tip": "부모님께: 아이들은 '밤하늘에서 반짝이는 것은 모두 별'이라고 생각하거나 달도 별이라고 말하곤 합니다. 맑은 밤에 함께 북쪽 하늘을 보며 북두칠성을 찾고 북극성까지 따라가 보세요. '샛별은 왜 별이 아닐까?'라는 질문도 좋은 대화 소재입니다."}$json$::jsonb,104) on conflict (slug) do nothing;
update public.topics set lesson_slug='s5-04' where band='5~6' and subject='과학' and name='태양계와 별';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('s5-05','5~6','과학','전기의 이용','전구에 불이 켜지려면 어떻게 연결해야 할까?','assets/img/l_s5-05.jpg',$json${"intro": "스위치를 누르면 방에 불이 켜지고, 리모컨으로 텔레비전이 켜져요. 전기는 어떻게 흘러서 일을 할까요?", "sections": [{"heading": "전기 회로 만들기", "paras": ["전지, 전선, 전구, 스위치 같은 전기 부품을 연결해 전기가 흐르도록 한 것을 '전기 회로'라고 해요.", "전구에 불이 켜지려면 전구를 전지의 (+)극과 (-)극에 각각 연결해, 끊어진 곳 없이 하나의 길로 이어져야 해요. 스위치를 끄면 회로가 끊겨 불이 꺼져요."], "example": "전선 한쪽이 전지에서 빠지면 회로가 끊어져 전구에 불이 켜지지 않아요.", "figure": "전지-스위치-전구가 전선으로 고리처럼 이어진 전기 회로 그림"}, {"heading": "전구의 직렬연결과 병렬연결", "paras": ["전구 두 개 이상을 한 줄로 연결하는 것을 '직렬연결', 여러 갈래로 나누어 연결하는 것을 '병렬연결'이라고 해요.", "전구를 병렬연결하면 직렬연결할 때보다 전구가 더 밝아요. 또 병렬연결에서는 전구 하나가 꺼져도 나머지 전구는 계속 켜져 있지만, 직렬연결에서는 하나가 꺼지면 나머지도 모두 꺼져요."], "example": "집 안의 전등과 전기 기구는 병렬연결되어 있어서 하나를 꺼도 다른 것은 켜져 있어요.", "figure": "전구 두 개를 한 줄로 이은 직렬연결과 두 갈래로 이은 병렬연결을 비교한 회로도"}, {"heading": "전자석", "paras": ["철심(쇠못)에 에나멜선을 여러 번 감고 전기를 흐르게 하면 철심이 자석이 돼요. 이것을 '전자석'이라고 해요.", "전자석은 전기가 흐를 때만 자석이 되고, 전지를 여러 개 직렬로 연결하면 세기가 더 세져요. 또 전지의 극을 바꾸면 전자석의 N극과 S극도 바뀌어요."], "example": "고철 처리장의 기중기는 전자석으로 고철을 들어 올렸다가 전기를 끊어 내려놓아요.", "figure": "쇠못에 에나멜선을 감고 전지에 연결해 클립을 끌어당기는 전자석 그림"}, {"heading": "전기를 안전하고 아껴 쓰기", "paras": ["젖은 손으로 전기 기구를 만지거나, 콘센트 하나에 플러그를 너무 많이 꽂으면 감전이나 화재가 일어날 수 있어 위험해요. 플러그를 뽑을 때는 전선이 아니라 플러그 머리를 잡아요.", "전기를 만들려면 많은 자원이 들어요. 쓰지 않는 전등은 끄고, 사용하지 않는 기구의 플러그는 뽑고, 냉장고 문은 오래 열어 두지 않아요."], "example": "", "figure": "멀티탭에 플러그가 잔뜩 꽂힌 위험한 모습과 안전하게 사용하는 모습 비교 그림"}], "keywords": [{"word": "전기 회로", "meaning": "전기 부품을 연결해 전기가 흐르도록 한 것"}, {"word": "직렬연결", "meaning": "전구나 전지를 한 줄로 연결하는 것"}, {"word": "병렬연결", "meaning": "전구를 여러 갈래로 나누어 연결하는 것"}, {"word": "전자석", "meaning": "전기가 흐를 때만 자석이 되는 것"}, {"word": "감전", "meaning": "몸에 전기가 흘러 다치는 것"}], "expressions": [], "quiz": [{"q": "전구에 불이 켜지는 조건으로 옳은 것은?", "choices": ["전구를 전지의 (+)극과 (-)극에 끊김 없이 연결한다", "전구를 전지의 (+)극에만 연결한다", "전선을 전구에만 감는다", "스위치를 끈다"], "answer": 0, "explain": "전기 부품이 끊어진 곳 없이 이어져야 전기가 흘러요."}, {"q": "전구 두 개를 병렬연결했을 때의 특징은?", "choices": ["직렬연결보다 어둡다", "전구 하나를 빼도 다른 전구는 켜진다", "전구 하나를 빼면 모두 꺼진다", "전지가 필요 없다"], "answer": 1, "explain": "병렬연결은 길이 여러 갈래라서 하나가 꺼져도 나머지는 켜져요. 밝기도 직렬보다 밝아요."}, {"q": "전자석에 대한 설명으로 옳지 않은 것은?", "choices": ["전기가 흐를 때만 자석이 된다", "전지의 극을 바꾸면 극이 바뀐다", "전지를 직렬로 더 연결하면 세기가 세진다", "전기를 끊어도 항상 자석이다"], "answer": 3, "explain": "전자석은 전기가 흐를 때만 자석의 성질을 가져요."}, {"q": "우리 집 전등과 전기 기구는 주로 어떻게 연결되어 있을까요?", "choices": ["직렬연결", "병렬연결", "연결되어 있지 않다", "전자석으로 연결"], "answer": 1, "explain": "병렬연결이라서 하나를 꺼도 다른 기구는 계속 쓸 수 있어요."}, {"q": "전기를 안전하게 사용하는 방법은?", "choices": ["젖은 손으로 플러그를 뽑는다", "콘센트 하나에 플러그를 많이 꽂는다", "플러그를 뽑을 때 플러그 머리를 잡는다", "전선을 잡아당겨 뽑는다"], "answer": 2, "explain": "전선을 당기면 선이 손상될 수 있어 플러그 머리를 잡고 뽑아야 해요."}], "summary": ["전기 부품이 끊김 없이 이어져야 전기 회로에 전기가 흘러요.", "전구는 병렬연결이 직렬연결보다 밝고, 하나가 꺼져도 나머지가 켜져요.", "전자석은 전기가 흐를 때만 자석이 되며, 전기는 안전하게 아껴 써야 해요."], "parent_tip": "부모님께: 아이들은 '직렬'과 '병렬'이라는 말을 자주 헷갈립니다. '한 줄 기차'는 직렬, '여러 갈래 길'은 병렬로 짝지어 기억하게 해 주세요. '거실 전등을 끄면 왜 냉장고는 계속 켜져 있을까?'라고 물어보면 병렬연결을 생활과 연결할 수 있습니다."}$json$::jsonb,105) on conflict (slug) do nothing;
update public.topics set lesson_slug='s5-05' where band='5~6' and subject='과학' and name='전기의 이용';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('s5-06','5~6','과학','날씨와 우리 생활','바람은 왜 불고, 구름은 어떻게 생길까?','assets/img/l_s5-06.jpg',$json${"intro": "어떤 날은 빨래가 금방 마르고, 어떤 날은 눅눅해서 잘 안 말라요. 날씨는 왜 날마다 달라질까요?", "sections": [{"heading": "습도", "paras": ["공기 중에 수증기가 포함된 정도를 '습도'라고 해요. 습도는 건습구 습도계로 잴 수 있어요. 건구 온도와 습구 온도의 차이를 구해 습도표에서 찾으면 돼요.", "습도가 높으면 빨래가 잘 마르지 않고 음식이 쉽게 상해요. 습도가 낮으면 피부가 건조해지고 산불이 나기 쉬워요."], "example": "건구 온도와 습구 온도의 차이가 클수록 습도가 낮아요.", "figure": "건구 온도계와 젖은 헝겊을 감은 습구 온도계가 나란히 있는 건습구 습도계 그림"}, {"heading": "이슬, 안개, 구름", "paras": ["공기 중의 수증기가 응결하면 여러 모습이 돼요. 밤에 차가워진 풀잎 표면에 수증기가 응결해 물방울로 맺히면 '이슬'이에요.", "지표면 가까이의 공기가 차가워져 수증기가 작은 물방울로 떠 있으면 '안개', 공기가 하늘 높이 올라가 차가워져 수증기가 물방울이나 얼음 알갱이로 떠 있으면 '구름'이에요."], "example": "구름 속 물방울이 커지고 무거워져 떨어지면 비, 얼음 알갱이가 녹지 않고 떨어지면 눈이 돼요.", "figure": "풀잎의 이슬, 땅 가까이 깔린 안개, 하늘 높이 떠 있는 구름을 한 장면에 그린 그림"}, {"heading": "고기압과 저기압, 그리고 바람", "paras": ["공기의 무게 때문에 생기는 누르는 힘을 '기압'이라고 해요. 차가운 공기는 따뜻한 공기보다 무거워 기압이 높아요. 주위보다 기압이 높은 곳을 '고기압', 낮은 곳을 '저기압'이라고 해요.", "두 지역 사이에 기압 차이가 생기면 공기가 고기압에서 저기압으로 이동하는데, 이것이 '바람'이에요."], "example": "바람 빠진 풍선의 입구를 열면 안쪽(높은 압력)의 공기가 바깥으로 빠져나가는 것과 비슷해요.", "figure": "고기압에서 저기압으로 화살표가 향하는 바람 그림"}, {"heading": "바닷가의 바람 – 해풍과 육풍", "paras": ["낮에는 육지가 바다보다 빨리 데워져요. 육지 위는 저기압, 바다 위는 고기압이 되어 바다에서 육지로 바람이 부는데, 이것을 '해풍'이라고 해요.", "밤에는 육지가 바다보다 빨리 식어서 육지 위가 고기압, 바다 위가 저기압이 돼요. 그래서 육지에서 바다로 '육풍'이 불어요."], "example": "", "figure": "낮에는 바다→육지(해풍), 밤에는 육지→바다(육풍)로 부는 바람을 나란히 비교한 그림"}, {"heading": "계절별 날씨와 공기 덩어리", "paras": ["우리나라는 계절마다 다른 공기 덩어리의 영향을 받아요. 공기 덩어리는 머물던 곳의 온도와 습도 성질을 닮아요.", "겨울에는 북서쪽 대륙에서 오는 차갑고 건조한 공기, 여름에는 남동쪽 바다에서 오는 덥고 습한 공기, 봄·가을에는 남서쪽 대륙에서 오는 따뜻하고 건조한 공기의 영향을 받아요."], "example": "여름이 후텁지근하고 겨울이 춥고 건조한 까닭은 공기 덩어리 때문이에요.", "figure": "우리나라 주변에서 계절별로 영향을 주는 공기 덩어리의 방향과 성질을 표시한 지도"}], "keywords": [{"word": "습도", "meaning": "공기 중에 수증기가 포함된 정도"}, {"word": "응결", "meaning": "수증기가 물방울로 변하는 것"}, {"word": "기압", "meaning": "공기의 무게 때문에 생기는 누르는 힘"}, {"word": "바람", "meaning": "기압 차이로 공기가 고기압에서 저기압으로 이동하는 것"}, {"word": "해풍", "meaning": "낮에 바다에서 육지로 부는 바람"}, {"word": "육풍", "meaning": "밤에 육지에서 바다로 부는 바람"}], "expressions": [], "quiz": [{"q": "바람이 부는 방향으로 옳은 것은?", "choices": ["저기압에서 고기압으로", "고기압에서 저기압으로", "항상 북쪽에서 남쪽으로", "기압과 관계없다"], "answer": 1, "explain": "공기는 기압이 높은 곳에서 낮은 곳으로 이동해요."}, {"q": "낮에 바닷가에서 바다에서 육지로 부는 바람은?", "choices": ["육풍", "해풍", "계절풍", "태풍"], "answer": 1, "explain": "낮에는 육지가 빨리 데워져 저기압이 되므로 바다에서 육지로 해풍이 불어요."}, {"q": "하늘 높이 올라간 공기 속 수증기가 응결해 떠 있는 것은?", "choices": ["이슬", "서리", "안개", "구름"], "answer": 3, "explain": "공기가 높이 올라가 차가워지면 수증기가 응결해 구름이 돼요."}, {"q": "우리나라 여름 날씨에 영향을 주는 공기 덩어리의 성질은?", "choices": ["덥고 습하다", "춥고 건조하다", "따뜻하고 건조하다", "차갑고 습하다"], "answer": 0, "explain": "여름에는 남동쪽 바다에서 오는 덥고 습한 공기 덩어리의 영향을 받아요."}, {"q": "습도가 높을 때 생기는 일로 알맞은 것은?", "choices": ["빨래가 잘 마르지 않는다", "산불이 나기 쉽다", "피부가 건조해진다", "정전기가 잘 생긴다"], "answer": 0, "explain": "공기 중 수증기가 많으면 빨래의 물이 잘 증발하지 않아요."}], "summary": ["습도는 공기 중 수증기의 양으로, 우리 생활에 영향을 줘요.", "수증기가 응결하면 이슬, 안개, 구름이 되고, 구름에서 비와 눈이 내려요.", "바람은 고기압에서 저기압으로 불며, 바닷가에서는 낮에 해풍, 밤에 육풍이 불어요."], "parent_tip": "부모님께: 아이들은 바람이 '저기압에서 고기압으로' 분다고 거꾸로 기억하는 경우가 많습니다. '공기가 꽉 찬 쪽(고기압)에서 덜 찬 쪽(저기압)으로 빠져나간다'고 풍선에 빗대어 설명해 보세요. 일기 예보를 함께 보며 '오늘 습도는 몇 %일까?'를 확인하는 것도 좋습니다."}$json$::jsonb,106) on conflict (slug) do nothing;
update public.topics set lesson_slug='s5-06' where band='5~6' and subject='과학' and name='날씨와 우리 생활';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('s5-07','5~6','과학','식물의 구조와 기능','식물은 어떻게 스스로 양분을 만들까?','assets/img/l_s5-07.jpg',$json${"intro": "동물은 먹이를 먹어야 살지만, 식물은 먹이를 먹지 않는데도 쑥쑥 자라요. 식물의 뿌리, 줄기, 잎, 꽃은 각각 어떤 일을 할까요?", "sections": [{"heading": "식물도 세포로 되어 있어요", "paras": ["모든 생물은 '세포'로 이루어져 있어요. 세포는 매우 작아서 현미경으로 봐야 보여요.", "식물 세포는 세포막 바깥에 단단한 '세포벽'이 있고, 그 안에 핵이 있어요. 동물 세포는 세포벽이 없다는 점이 달라요."], "example": "양파 껍질을 얇게 벗겨 현미경으로 보면 벽돌처럼 쌓인 세포가 보여요.", "figure": "현미경으로 본 양파 표피 세포(세포벽과 핵 표시)"}, {"heading": "뿌리와 줄기", "paras": ["뿌리는 땅속의 물을 흡수하고, 식물을 지지해요. 무나 고구마처럼 양분을 저장하는 뿌리도 있어요. 뿌리털은 물을 흡수하는 면적을 넓혀 줘요.", "줄기는 뿌리에서 흡수한 물이 잎과 꽃까지 이동하는 통로이고, 식물을 지지해요. 감자처럼 양분을 저장하는 줄기도 있어요."], "example": "백합 줄기를 붉은 색소 물에 꽂아 두면 줄기를 자른 면에 붉은 점들이 보여요. 물이 지나간 길이에요.", "figure": "붉은 색소 물에 꽂은 줄기의 가로·세로 단면 그림"}, {"heading": "잎 – 광합성과 증산 작용", "paras": ["식물이 빛을 이용해 물과 이산화 탄소로 스스로 양분을 만드는 것을 '광합성'이라고 해요. 광합성은 주로 잎에서 일어나고, 녹말 같은 양분과 함께 산소가 만들어져요.", "뿌리에서 올라온 물은 잎의 작은 구멍인 '기공'을 통해 수증기가 되어 밖으로 빠져나가는데, 이것을 '증산 작용'이라고 해요. 증산 작용은 뿌리에서 물을 끌어올리고 식물의 온도를 조절하는 데 도움을 줘요."], "example": "빛을 받은 잎에 아이오딘-아이오딘화 칼륨 용액을 떨어뜨리면 청람색으로 변해요. 녹말이 만들어졌다는 뜻이에요.", "figure": "잎에 빛, 물, 이산화 탄소가 들어가고 양분과 산소가 나오는 광합성 그림"}, {"heading": "꽃과 열매", "paras": ["꽃은 주로 암술, 수술, 꽃잎, 꽃받침으로 되어 있어요. 꽃은 씨를 만드는 일을 해요.", "수술에서 만든 꽃가루가 암술로 옮겨지는 것을 '꽃가루받이(수분)'라고 해요. 꽃가루받이가 되면 씨가 생기고, 씨를 싸고 있는 부분이 자라 열매가 돼요. 꽃가루는 곤충, 새, 바람, 물 등이 옮겨 줘요."], "example": "", "figure": "꽃의 암술, 수술, 꽃잎, 꽃받침에 이름표를 붙인 그림과 벌이 꽃가루를 옮기는 모습"}, {"heading": "씨가 퍼지는 방법", "paras": ["열매 속 씨는 여러 방법으로 멀리 퍼져요. 민들레 씨는 솜털이 있어 바람에 날려 가고, 도꼬마리 씨는 갈고리가 있어 동물 털에 붙어 퍼져요.", "벚나무 열매는 동물에게 먹힌 뒤 씨가 똥과 함께 나와 퍼지고, 봉선화는 열매 껍질이 터지면서 씨가 튀어 나가요. 연꽃이나 코코야자는 물에 떠서 퍼져요."], "example": "", "figure": "민들레(바람), 도꼬마리(동물 털), 봉선화(터짐), 코코야자(물) 씨가 퍼지는 모습 모음"}], "keywords": [{"word": "세포", "meaning": "생물을 이루는 기본 단위"}, {"word": "광합성", "meaning": "식물이 빛을 이용해 물과 이산화 탄소로 양분을 만드는 것"}, {"word": "기공", "meaning": "잎에 있는 아주 작은 구멍"}, {"word": "증산 작용", "meaning": "잎의 기공으로 물이 수증기가 되어 빠져나가는 것"}, {"word": "꽃가루받이", "meaning": "수술의 꽃가루가 암술로 옮겨지는 것"}], "expressions": [], "quiz": [{"q": "광합성에 필요한 것으로 짝지어진 것은?", "choices": ["빛, 물, 이산화 탄소", "산소, 소리, 흙", "어둠, 산소, 물", "바람, 열매, 꽃"], "answer": 0, "explain": "식물은 빛을 이용해 물과 이산화 탄소로 양분을 만들어요."}, {"q": "뿌리에서 흡수한 물이 이동하는 통로 역할을 하는 기관은?", "choices": ["꽃", "줄기", "열매", "꽃받침"], "answer": 1, "explain": "줄기는 물이 잎과 꽃까지 이동하는 통로예요."}, {"q": "잎의 기공을 통해 물이 수증기로 빠져나가는 현상은?", "choices": ["광합성", "꽃가루받이", "증산 작용", "응결"], "answer": 2, "explain": "물이 기공을 통해 수증기로 나가는 것을 증산 작용이라고 해요."}, {"q": "식물 세포에는 있지만 동물 세포에는 없는 것은?", "choices": ["핵", "세포막", "세포벽", "물"], "answer": 2, "explain": "식물 세포에는 세포막 바깥에 단단한 세포벽이 있어요."}, {"q": "민들레 씨가 퍼지는 방법은?", "choices": ["동물 털에 붙어서", "바람에 날려서", "껍질이 터져서", "물에 떠서"], "answer": 1, "explain": "민들레 씨는 솜털이 있어 바람에 날려 멀리 퍼져요."}], "summary": ["생물은 세포로 이루어져 있고, 식물 세포에는 세포벽이 있어요.", "뿌리는 물을 흡수하고, 줄기는 물을 옮기며, 잎은 광합성과 증산 작용을 해요.", "꽃은 꽃가루받이를 거쳐 씨와 열매를 만들고, 씨는 여러 방법으로 퍼져요."], "parent_tip": "부모님께: 아이들은 '식물은 흙에서 양분을 먹고 자란다'고 생각하기 쉽습니다. 식물은 빛을 이용해 잎에서 스스로 양분을 만든다는 점을 강조해 주세요. 화분의 잎에 비닐봉지를 씌워 두고 몇 시간 뒤 물방울이 맺힌 것을 보며 '이 물은 어디서 왔을까?'라고 물어보면 증산 작용을 쉽게 이해합니다."}$json$::jsonb,107) on conflict (slug) do nothing;
update public.topics set lesson_slug='s5-07' where band='5~6' and subject='과학' and name='식물의 구조와 기능';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('s5-08','5~6','과학','연소와 소화','불은 어떻게 타고, 어떻게 끌까?','assets/img/l_s5-08.jpg',$json${"intro": "캠핑장의 모닥불, 생일 케이크의 촛불! 물질이 탈 때는 무엇이 필요하고, 불을 끄려면 어떻게 해야 할까요?", "sections": [{"heading": "물질이 탈 때 나타나는 현상", "paras": ["물질이 산소와 빠르게 반응하여 빛과 열을 내는 현상을 '연소'라고 해요.", "초나 알코올이 탈 때는 빛과 열이 나서 주변이 밝고 따뜻해지고, 시간이 지나면 탈 물질의 양이 줄어들어요."], "example": "", "figure": "타고 있는 촛불과 알코올램프의 불꽃 모습"}, {"heading": "연소의 세 가지 조건", "paras": ["물질이 타려면 세 가지가 모두 있어야 해요. 바로 '탈 물질', '산소', 그리고 '발화점 이상의 온도'예요.", "발화점은 물질이 불에 직접 닿지 않아도 스스로 타기 시작하는 가장 낮은 온도예요. 물질마다 발화점이 달라서 같은 온도로 가열해도 먼저 불이 붙는 물질이 있어요."], "example": "크기가 다른 아크릴 통으로 촛불을 덮으면 큰 통 안의 촛불이 더 오래 타요. 산소가 더 많기 때문이에요.", "figure": "탈 물질, 산소, 발화점 이상의 온도를 세 꼭짓점으로 한 삼각형 그림"}, {"heading": "연소 후 생기는 물질", "paras": ["초가 타면 물과 이산화 탄소가 생겨요. 푸른색 염화 코발트 종이가 붉게 변하면 물이 생긴 것이에요.", "초가 탄 뒤 집기병에 석회수를 넣고 흔들면 뿌옇게 흐려지는데, 이것으로 이산화 탄소가 생겼음을 알 수 있어요."], "example": "", "figure": "촛불을 덮은 집기병 안쪽 벽의 푸른색 염화 코발트 종이가 붉게 변한 모습과 뿌옇게 흐려진 석회수"}, {"heading": "불을 끄는 방법 – 소화", "paras": ["불을 끄는 것을 '소화'라고 해요. 연소의 세 가지 조건 중 한 가지 이상을 없애면 불이 꺼져요.", "탈 물질을 없애고(촛불 심지 자르기, 가스 밸브 잠그기), 산소를 막고(모래나 담요 덮기, 소화기 사용), 온도를 발화점 아래로 낮추면(물 뿌리기) 불이 꺼져요."], "example": "알코올램프는 뚜껑을 덮어 산소를 막아서 불을 꺼요.", "figure": "심지 자르기, 뚜껑 덮기, 물 뿌리기로 불을 끄는 세 가지 장면"}, {"heading": "화재 안전", "paras": ["기름이나 전기 때문에 난 불에 물을 뿌리면 불이 더 커지거나 감전될 수 있어서 소화기나 모래를 써야 해요.", "불이 나면 '불이야!' 하고 크게 외치고 119에 신고해요. 젖은 수건으로 코와 입을 막고 몸을 낮춰 계단으로 대피해요. 승강기(엘리베이터)는 타지 않아요."], "example": "", "figure": "젖은 수건으로 입을 막고 몸을 낮춰 비상구로 대피하는 어린이 그림"}], "keywords": [{"word": "연소", "meaning": "물질이 산소와 빠르게 반응하여 빛과 열을 내는 현상"}, {"word": "발화점", "meaning": "물질이 불에 직접 닿지 않아도 스스로 타기 시작하는 온도"}, {"word": "소화", "meaning": "불을 끄는 것"}, {"word": "석회수", "meaning": "이산화 탄소를 만나면 뿌옇게 흐려지는 용액"}, {"word": "염화 코발트 종이", "meaning": "물에 닿으면 푸른색에서 붉은색으로 변하는 종이"}], "expressions": [], "quiz": [{"q": "연소의 조건이 아닌 것은?", "choices": ["탈 물질", "산소", "발화점 이상의 온도", "이산화 탄소"], "answer": 3, "explain": "연소에는 탈 물질, 산소, 발화점 이상의 온도가 필요해요."}, {"q": "초가 탄 뒤 석회수가 뿌옇게 흐려졌다면 어떤 물질이 생긴 것일까요?", "choices": ["물", "산소", "이산화 탄소", "질소"], "answer": 2, "explain": "석회수는 이산화 탄소를 만나면 뿌옇게 흐려져요."}, {"q": "알코올램프 뚜껑을 덮어 불을 끄는 것은 어떤 조건을 없앤 것일까요?", "choices": ["탈 물질", "산소", "발화점 이상의 온도", "빛"], "answer": 1, "explain": "뚜껑을 덮으면 산소가 공급되지 않아 불이 꺼져요."}, {"q": "불이 났을 때 올바른 행동은?", "choices": ["승강기를 타고 빨리 내려간다", "젖은 수건으로 코와 입을 막고 몸을 낮춰 대피한다", "기름에 붙은 불에 물을 붓는다", "숨어서 기다린다"], "answer": 1, "explain": "연기를 마시지 않도록 코와 입을 막고 몸을 낮춰 계단으로 대피해요."}, {"q": "크기가 다른 통으로 같은 촛불을 덮었을 때 더 오래 타는 경우는?", "choices": ["작은 통", "큰 통", "둘이 같다", "통을 덮으면 바로 꺼진다"], "answer": 1, "explain": "큰 통 안에 산소가 더 많아서 촛불이 더 오래 타요."}], "summary": ["연소는 물질이 산소와 빠르게 반응해 빛과 열을 내는 현상이에요.", "연소에는 탈 물질, 산소, 발화점 이상의 온도가 모두 필요하고, 타면 물과 이산화 탄소가 생겨요.", "세 조건 중 하나 이상을 없애면 불이 꺼지고(소화), 불이 나면 119 신고 후 몸을 낮춰 대피해요."], "parent_tip": "부모님께: 아이들은 '불은 물로만 끈다'고 생각하기 쉽습니다. 식용유에 붙은 불에 물을 부으면 위험하다는 점을 꼭 알려 주세요. 집의 소화기 위치를 함께 확인하고, '우리 집에서 불이 나면 어디로 대피할까?'를 이야기하며 대피 경로를 정해 보시길 권합니다."}$json$::jsonb,108) on conflict (slug) do nothing;
update public.topics set lesson_slug='s5-08' where band='5~6' and subject='과학' and name='연소와 소화';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('s5-09','5~6','과학','생물과 환경','생물은 주변 환경과 어떻게 어울려 살까?','assets/img/l_s5-09.jpg',$json${"intro": "숲에는 나무와 풀, 벌레, 새, 그리고 눈에 보이지 않는 곰팡이와 세균까지 살아요. 이 생물들은 서로, 그리고 햇빛·물·흙과 어떻게 연결되어 있을까요?", "sections": [{"heading": "생태계란?", "paras": ["어떤 장소에서 생물이 주변 환경과 서로 영향을 주고받는 것을 '생태계'라고 해요. 숲, 연못, 바다, 화단도 모두 생태계예요.", "생태계는 동물, 식물, 곰팡이, 세균 같은 '생물 요소'와 햇빛, 물, 온도, 흙, 공기 같은 '비생물 요소'로 이루어져 있어요."], "example": "학교 화단의 꽃(생물 요소)은 햇빛과 물(비생물 요소)이 있어야 잘 자라요.", "figure": "연못 생태계 속 생물 요소(물고기, 개구리, 수초)와 비생물 요소(햇빛, 물, 흙)를 표시한 그림"}, {"heading": "생산자, 소비자, 분해자", "paras": ["생물은 양분을 얻는 방법에 따라 나눌 수 있어요. 식물처럼 햇빛을 이용해 스스로 양분을 만드는 생물을 '생산자'라고 해요.", "다른 생물을 먹어 양분을 얻는 동물은 '소비자', 죽은 생물이나 배출물을 분해해 양분을 얻는 곰팡이와 세균은 '분해자'예요. 분해자가 없다면 죽은 생물과 배출물이 쌓여 지구가 지저분해질 거예요."], "example": "벼(생산자), 메뚜기(소비자), 버섯(분해자)", "figure": "생산자, 소비자, 분해자로 생물을 나눈 분류 그림"}, {"heading": "먹이 사슬과 먹이 그물", "paras": ["생물들 사이의 먹고 먹히는 관계가 사슬처럼 한 줄로 이어진 것을 '먹이 사슬'이라고 해요. 여러 먹이 사슬이 그물처럼 얽힌 것은 '먹이 그물'이에요.", "먹이 그물에서는 한 종류의 먹이가 사라져도 다른 먹이를 먹고 살 수 있어서, 생물이 살아가기에 더 유리해요."], "example": "벼 → 메뚜기 → 개구리 → 뱀 → 매", "figure": "벼, 메뚜기, 개구리, 뱀, 매 등이 화살표로 얽힌 먹이 그물 그림"}, {"heading": "생태계 평형", "paras": ["생태계에서 생물의 종류와 수가 균형을 이루며 안정된 상태를 유지하는 것을 '생태계 평형'이라고 해요.", "어떤 생물이 갑자기 사라지거나 늘어나면 평형이 깨질 수 있어요. 미국 국립 공원에서 늑대가 사라지자 사슴이 크게 늘어 풀과 나무가 줄었고, 다시 늑대를 데려오자 생태계가 차츰 회복되었어요."], "example": "", "figure": "늑대가 사라진 뒤 사슴이 늘고 풀이 줄어드는 변화를 단계별로 나타낸 그림"}, {"heading": "환경에 적응한 생물과 환경 보전", "paras": ["생물이 사는 곳의 환경에 알맞게 생김새나 생활 방식을 갖게 되는 것을 '적응'이라고 해요. 선인장은 잎이 가시로 되어 있어 사막에서 물이 덜 빠져나가고, 북극여우는 귀가 작고 털이 두꺼워 추위를 잘 견뎌요.", "쓰레기, 매연, 폐수 같은 환경 오염은 생물이 살아가기 어렵게 만들어요. 일회용품을 줄이고, 분리배출을 잘하고, 대중교통을 이용하는 것이 생태계를 지키는 방법이에요."], "example": "대벌레는 나뭇가지와 비슷한 생김새여서 적의 눈에 잘 띄지 않아요.", "figure": "사막의 선인장과 북극의 북극여우를 나란히 비교한 그림"}], "keywords": [{"word": "생태계", "meaning": "생물이 주변 환경과 서로 영향을 주고받는 것"}, {"word": "비생물 요소", "meaning": "햇빛, 물, 온도, 흙, 공기처럼 살아 있지 않은 요소"}, {"word": "생산자", "meaning": "햇빛을 이용해 스스로 양분을 만드는 생물"}, {"word": "분해자", "meaning": "죽은 생물이나 배출물을 분해해 양분을 얻는 생물"}, {"word": "먹이 그물", "meaning": "여러 먹이 사슬이 그물처럼 얽혀 있는 것"}, {"word": "적응", "meaning": "생물이 환경에 알맞게 생김새나 생활 방식을 갖게 되는 것"}], "expressions": [], "quiz": [{"q": "다음 중 비생물 요소는?", "choices": ["버섯", "개구리", "햇빛", "세균"], "answer": 2, "explain": "햇빛은 살아 있지 않은 비생물 요소예요."}, {"q": "스스로 양분을 만드는 생산자는?", "choices": ["벼", "메뚜기", "곰팡이", "개구리"], "answer": 0, "explain": "식물인 벼는 햇빛을 이용해 스스로 양분을 만들어요."}, {"q": "죽은 생물을 분해해 양분을 얻는 생물끼리 짝지은 것은?", "choices": ["벼, 토끼", "뱀, 매", "곰팡이, 세균", "메뚜기, 개구리"], "answer": 2, "explain": "곰팡이와 세균은 분해자예요."}, {"q": "먹이 그물이 먹이 사슬보다 생물이 살아가기에 유리한 까닭은?", "choices": ["생물 수가 줄어서", "한 먹이가 없어져도 다른 먹이를 먹을 수 있어서", "먹고 먹히는 관계가 없어서", "모든 생물이 생산자라서"], "answer": 1, "explain": "먹이 그물은 여러 먹이 관계가 얽혀 있어 한 먹이가 사라져도 다른 먹이를 먹을 수 있어요."}, {"q": "선인장의 잎이 가시로 되어 있는 것은 무엇에 적응한 결과일까요?", "choices": ["추운 환경", "물이 부족한 환경", "어두운 환경", "물이 많은 환경"], "answer": 1, "explain": "가시 모양 잎은 물이 빠져나가는 것을 줄여 건조한 사막에 적응한 거예요."}], "summary": ["생태계는 생물 요소와 비생물 요소가 서로 영향을 주고받는 것이에요.", "생물은 생산자·소비자·분해자로 나뉘고, 먹이 사슬이 얽혀 먹이 그물을 이뤄요.", "생태계 평형은 쉽게 깨질 수 있으므로 환경을 보전해야 해요."], "parent_tip": "부모님께: 아이들은 분해자(곰팡이, 세균)를 '나쁜 것'으로만 생각하기 쉽습니다. 낙엽이 쌓여 흙이 되는 모습을 보며 분해자의 역할을 이야기해 주세요. 산책길에서 '이 생물은 생산자일까, 소비자일까?'를 맞혀 보거나, '모기가 모두 사라지면 어떤 일이 생길까?'를 함께 상상해 보는 것도 좋습니다."}$json$::jsonb,109) on conflict (slug) do nothing;
update public.topics set lesson_slug='s5-09' where band='5~6' and subject='과학' and name='생물과 환경';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m3-01','3~4','수학','분수','피자를 똑같이 나누면 어떤 수가 될까?','assets/img/l_m3-01.jpg',$json${"intro": "피자 한 판을 친구 4명과 똑같이 나눠 먹으면 나는 얼마만큼 먹는 걸까요? 이럴 때 쓰는 수가 바로 분수예요.", "sections": [{"heading": "똑같이 나누어야 분수예요", "paras": ["분수는 전체를 '똑같이' 나눈 것 중의 몇 개인지 나타내는 수예요. 크기가 서로 다르게 나누면 분수로 말할 수 없어요.", "피자 한 판을 똑같이 4조각으로 나눈 것 중 1조각은 4분의 1이라고 읽고 1/4이라고 써요."], "example": "피자 1판을 똑같이 4조각으로 나눈 것 중 1조각 → 1/4 (4분의 1)", "figure": "똑같이 4조각으로 나눈 피자에서 1조각만 색칠된 그림"}, {"heading": "분모와 분자", "paras": ["분수에서 가로선 아래에 있는 수를 분모, 위에 있는 수를 분자라고 해요.", "분모는 전체를 몇 개로 똑같이 나누었는지, 분자는 그중 몇 개인지를 알려 줘요. 분자가 1인 1/2, 1/3, 1/4 같은 분수를 단위분수라고 해요."], "example": "3/5 → 전체를 똑같이 5로 나눈 것 중 3개 (분모 5, 분자 3)", "figure": "막대를 5칸으로 똑같이 나누고 3칸을 색칠한 뒤 분모·분자에 화살표로 이름을 붙인 그림"}, {"heading": "진분수, 가분수, 대분수", "paras": ["분자가 분모보다 작은 분수는 진분수예요(예: 2/3). 분자가 분모와 같거나 분모보다 큰 분수는 가분수예요(예: 4/4, 7/4).", "1과 3/4처럼 자연수와 진분수로 이루어진 분수는 대분수라고 해요. 가분수는 대분수로, 대분수는 가분수로 바꿀 수 있어요."], "example": "7/4 → 1/4이 7개 → 4개가 모이면 1이 되므로 1과 3/4", "figure": "1/4 조각 7개 중 4개가 모여 원 하나를 이루고 3개가 남은 그림"}, {"heading": "이렇게 풀어요: 어떤 수의 분수만큼 구하기", "paras": ["12의 2/3가 얼마인지 구해 볼까요? ① 12를 똑같이 3묶음으로 나눠요. ② 한 묶음에는 4개가 있어요. 이것이 12의 1/3이에요.", "③ 2/3는 그런 묶음 2개이므로 4 + 4 = 8이에요. 분모만큼 묶음을 만들고, 분자만큼 묶음을 세면 돼요."], "example": "12의 1/3 = 4, 12의 2/3 = 8", "figure": "사탕 12개를 4개씩 3묶음으로 나누고 그중 2묶음에 동그라미를 친 그림"}, {"heading": "분수의 크기 비교", "paras": ["분모가 같은 분수는 분자가 클수록 더 큰 분수예요. 2/7보다 5/7이 더 커요.", "단위분수는 분모가 클수록 한 조각이 작아져서 더 작은 분수가 돼요. 그래서 1/3이 1/5보다 커요."], "example": "1/3 > 1/5 (3조각으로 나눈 한 조각이 5조각으로 나눈 한 조각보다 커요)", "figure": "같은 길이의 막대 두 개를 3칸과 5칸으로 나누어 한 칸씩 색칠해 비교한 그림"}], "keywords": [{"word": "분수", "meaning": "전체를 똑같이 나눈 것 중의 몇 개를 나타내는 수"}, {"word": "분모", "meaning": "가로선 아래의 수, 전체를 몇으로 나누었는지"}, {"word": "분자", "meaning": "가로선 위의 수, 그중 몇 개인지"}, {"word": "단위분수", "meaning": "분자가 1인 분수"}, {"word": "가분수", "meaning": "분자가 분모와 같거나 큰 분수"}, {"word": "대분수", "meaning": "자연수와 진분수로 이루어진 분수"}], "expressions": [], "quiz": [{"q": "18의 1/3은 얼마일까요?", "choices": ["5", "6", "9", "3"], "answer": 1, "explain": "18을 똑같이 3묶음으로 나누면 한 묶음에 6개씩이에요."}, {"q": "다음 중 가장 큰 분수는 무엇일까요?", "choices": ["2/7", "3/7", "4/7", "5/7"], "answer": 3, "explain": "분모가 같으면 분자가 클수록 커요. 분자 5가 가장 커요."}, {"q": "11/4를 대분수로 바르게 나타낸 것은?", "choices": ["1과 3/4", "2와 1/4", "2와 3/4", "3과 1/4"], "answer": 2, "explain": "1/4이 4개면 1이므로 11개는 1이 2개, 1/4이 3개 남아 2와 3/4이에요."}, {"q": "다음 단위분수 중 가장 큰 것은?", "choices": ["1/2", "1/5", "1/8", "1/3"], "answer": 0, "explain": "단위분수는 분모가 작을수록 한 조각이 커서 1/2이 가장 커요."}, {"q": "다음 중 가분수는 무엇일까요?", "choices": ["2/5", "1/3", "7/4", "4/9"], "answer": 2, "explain": "분자 7이 분모 4보다 크므로 7/4는 가분수예요."}], "summary": ["분수는 전체를 똑같이 나눈 것 중의 몇 개를 나타내요.", "분모는 나눈 개수, 분자는 그중 몇 개인지를 알려 줘요.", "분모가 같으면 분자가 클수록, 단위분수는 분모가 작을수록 커요."], "parent_tip": "아이들은 '분모가 크면 더 큰 분수'라고 착각하기 쉽습니다. 피자나 종이띠를 실제로 3조각, 5조각으로 나눠 보게 하면 금방 이해합니다. \"케이크를 8명이 나눌 때와 4명이 나눌 때 어느 쪽 조각이 더 클까?\"처럼 물어봐 주세요."}$json$::jsonb,31) on conflict (slug) do nothing;
update public.topics set lesson_slug='m3-01' where band='3~4' and subject='수학' and name='분수';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m3-02','3~4','수학','곱셈','큰 수의 곱셈은 어떻게 할까?','assets/img/l_m3-02.jpg',$json${"intro": "한 상자에 달걀이 30개씩 들어 있는데 40상자가 있다면 달걀은 모두 몇 개일까요? 하나하나 세지 않아도 곱셈으로 빠르게 알 수 있어요.", "sections": [{"heading": "곱셈은 같은 수를 여러 번 더한 것", "paras": ["4 + 4 + 4처럼 같은 수를 여러 번 더할 때 곱셈식 4 × 3으로 간단하게 쓸 수 있어요.", "곱셈은 자리를 바꿔도 결과가 같아요. 4 × 3과 3 × 4는 둘 다 12예요."], "example": "4 + 4 + 4 = 4 × 3 = 12", "figure": "사과 4개씩 담긴 접시 3개가 나란히 놓인 그림"}, {"heading": "(세 자리 수) × (한 자리 수)", "paras": ["일의 자리부터 차례로 곱하고, 곱이 10이 넘으면 윗자리로 올려 줘요. 이것을 올림이라고 해요.", "156 × 4는 일의 자리 6 × 4 = 24에서 4를 쓰고 2를 올려요. 십의 자리 5 × 4 = 20에 올린 2를 더해 22, 2를 쓰고 2를 올려요. 백의 자리 1 × 4 = 4에 2를 더해 6이에요."], "example": "213 × 3 = 639, 156 × 4 = 624", "figure": "156 × 4 세로셈에서 올림한 숫자를 작게 위에 적은 그림"}, {"heading": "이렇게 풀어요: (두 자리 수) × (두 자리 수)", "paras": ["24 × 13을 풀어 볼까요? ① 24 × 3 = 72를 먼저 구해요. ② 24 × 10 = 240을 구해요(13의 1은 십의 자리라서 10이에요).", "③ 두 곱을 더하면 72 + 240 = 312예요. 곱하는 수를 일의 자리와 십의 자리로 나누어 곱한 뒤 더하는 거예요."], "example": "24 × 13 = 24 × 3 + 24 × 10 = 72 + 240 = 312", "figure": "가로 24칸, 세로 13칸 모눈을 3줄과 10줄로 나누어 색을 다르게 칠한 그림"}, {"heading": "0이 있는 곱셈과 어림", "paras": ["30 × 40은 3 × 4 = 12를 구한 뒤, 두 수의 끝에 있는 0의 개수(2개)만큼 0을 붙이면 1200이에요.", "답이 맞는지 어림해 보는 습관도 좋아요. 198 × 3은 약 200 × 3 = 600쯤 되겠다고 미리 생각해 볼 수 있어요."], "example": "30 × 40 = 1200 (3 × 4 = 12에 0 두 개)", "figure": "달걀 30개 상자 40개가 쌓여 있는 창고 그림"}], "keywords": [{"word": "곱셈", "meaning": "같은 수를 여러 번 더한 것을 간단히 나타내는 계산"}, {"word": "곱", "meaning": "곱셈을 해서 나온 값"}, {"word": "올림", "meaning": "한 자리의 곱이 10이 넘을 때 윗자리로 올려 주는 것"}, {"word": "어림", "meaning": "대강 짐작해서 셈하는 것"}], "expressions": [], "quiz": [{"q": "213 × 3은 얼마일까요?", "choices": ["639", "636", "609", "693"], "answer": 0, "explain": "3 × 3 = 9, 1 × 3 = 3, 2 × 3 = 6이라서 639예요."}, {"q": "47 × 6은 얼마일까요?", "choices": ["242", "272", "282", "286"], "answer": 2, "explain": "7 × 6 = 42에서 4를 올리고, 4 × 6 = 24에 4를 더해 28이라 282예요."}, {"q": "25 × 14는 얼마일까요?", "choices": ["300", "350", "325", "375"], "answer": 1, "explain": "25 × 4 = 100, 25 × 10 = 250, 둘을 더하면 350이에요."}, {"q": "귤이 한 상자에 32개씩 15상자 있어요. 귤은 모두 몇 개일까요?", "choices": ["450개", "470개", "480개", "490개"], "answer": 2, "explain": "32 × 15 = 32 × 5 + 32 × 10 = 160 + 320 = 480이에요."}, {"q": "40 × 30은 얼마일까요?", "choices": ["120", "1200", "12000", "700"], "answer": 1, "explain": "4 × 3 = 12에 0을 두 개 붙이면 1200이에요."}], "summary": ["곱셈은 같은 수를 여러 번 더한 것을 간단히 나타내요.", "일의 자리부터 곱하고, 10이 넘으면 윗자리로 올림해요.", "두 자리 수를 곱할 때는 일의 자리와 십의 자리로 나누어 곱한 뒤 더해요."], "parent_tip": "(두 자리)×(두 자리)에서 십의 자리를 곱할 때 0을 빠뜨리고 자리를 잘못 맞추는 실수가 가장 많습니다. \"13의 1은 진짜로 얼마야?\"라고 물어 10이라는 것을 스스로 말하게 해 주세요. 장보기 영수증으로 \"이게 3개면 얼마일까?\"를 어림해 보는 것도 좋습니다."}$json$::jsonb,32) on conflict (slug) do nothing;
update public.topics set lesson_slug='m3-02' where band='3~4' and subject='수학' and name='곱셈';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m3-03','3~4','수학','자료의 정리','조사한 내용을 한눈에 보려면 어떻게 할까?','assets/img/l_m3-03.jpg',$json${"intro": "우리 반 친구들이 가장 좋아하는 과일은 무엇일까요? 친구들에게 물어본 결과를 표와 그래프로 정리하면 한눈에 알 수 있어요.", "sections": [{"heading": "자료를 모아 표로 정리해요", "paras": ["궁금한 것을 정하고 친구들에게 물어 모은 것을 자료라고 해요. 손을 들게 하거나 붙임 딱지를 붙이게 해서 모을 수 있어요.", "모은 자료는 항목별로 수를 세어 표로 정리해요. 표에는 합계를 적는 칸도 있어서 모두 몇 명인지 바로 알 수 있어요."], "example": "사과 7명, 바나나 5명, 딸기 9명, 포도 4명 → 합계 25명", "figure": "과일 이름과 학생 수, 합계 칸이 있는 표 그림"}, {"heading": "그림그래프로 나타내요", "paras": ["그림그래프는 수량을 그림으로 나타낸 그래프예요. 큰 그림과 작은 그림을 정해 큰 수도 간단하게 나타낼 수 있어요.", "큰 사과 그림이 10상자, 작은 사과 그림이 1상자를 뜻한다면 32상자는 큰 그림 3개와 작은 그림 2개로 그려요."], "example": "큰 그림 = 10, 작은 그림 = 1 → 32는 큰 그림 3개 + 작은 그림 2개", "figure": "마을별 사과 생산량을 큰 사과 그림과 작은 사과 그림으로 나타낸 그림그래프"}, {"heading": "막대그래프로 나타내요", "paras": ["막대그래프는 수량을 막대의 길이로 나타낸 그래프예요. 막대가 길수록 수가 많아서 크기를 비교하기 쉬워요.", "그래프를 그릴 때는 가로와 세로에 무엇을 나타낼지 정하고, 눈금 한 칸이 몇을 나타낼지 정한 뒤 막대를 그려요. 제목도 꼭 붙여요."], "example": "세로 눈금 한 칸이 1명일 때, 딸기는 9칸, 포도는 4칸 높이의 막대", "figure": "좋아하는 과일 4가지를 세로 막대로 나타낸 막대그래프"}, {"heading": "이렇게 풀어요: 그래프 읽기", "paras": ["① 제목을 보고 무엇을 조사했는지 알아봐요. ② 눈금 한 칸이 얼마인지 확인해요. ③ 막대 길이나 그림 수를 세어 수를 읽어요.", "가장 많은 것과 가장 적은 것을 찾고, 차이도 구할 수 있어요. 딸기(9명)와 포도(4명)의 차이는 9 − 4 = 5명이에요."], "example": "가장 많은 과일: 딸기 9명, 가장 적은 과일: 포도 4명, 차이 5명", "figure": "막대그래프에서 가장 긴 막대와 가장 짧은 막대에 표시를 한 그림"}], "keywords": [{"word": "자료", "meaning": "조사해서 모은 내용"}, {"word": "표", "meaning": "항목과 수를 칸에 나누어 정리한 것"}, {"word": "그림그래프", "meaning": "수량을 그림으로 나타낸 그래프"}, {"word": "막대그래프", "meaning": "수량을 막대의 길이로 나타낸 그래프"}, {"word": "눈금", "meaning": "그래프에서 수를 읽을 수 있게 그은 일정한 간격의 표시"}], "expressions": [], "quiz": [{"q": "사과 7명, 바나나 5명, 딸기 9명, 포도 4명이에요. 조사한 학생은 모두 몇 명일까요?", "choices": ["23명", "24명", "25명", "26명"], "answer": 2, "explain": "7 + 5 + 9 + 4 = 25명이에요."}, {"q": "위 조사에서 가장 많은 학생이 좋아하는 과일은?", "choices": ["사과", "바나나", "딸기", "포도"], "answer": 2, "explain": "딸기가 9명으로 가장 많아요."}, {"q": "위 조사에서 딸기를 좋아하는 학생은 포도를 좋아하는 학생보다 몇 명 더 많을까요?", "choices": ["3명", "4명", "5명", "6명"], "answer": 2, "explain": "9 − 4 = 5명 더 많아요."}, {"q": "큰 그림은 10개, 작은 그림은 1개를 나타내요. 큰 그림 4개와 작은 그림 3개는 얼마일까요?", "choices": ["7개", "34개", "43개", "403개"], "answer": 2, "explain": "10이 4개면 40, 1이 3개면 3이라 43개예요."}, {"q": "막대그래프에서 세로 눈금 한 칸이 2명이에요. 막대가 6칸이면 몇 명일까요?", "choices": ["6명", "8명", "12명", "3명"], "answer": 2, "explain": "한 칸이 2명이므로 6칸은 2 × 6 = 12명이에요."}], "summary": ["조사한 자료는 표로 정리하면 합계를 쉽게 알 수 있어요.", "그림그래프는 그림으로, 막대그래프는 막대의 길이로 수량을 나타내요.", "그래프를 읽을 때는 눈금 한 칸이나 그림 하나가 얼마인지 먼저 확인해요."], "parent_tip": "아이들은 눈금 한 칸이 1이 아닐 때(2명, 5명 등) 칸 수를 그대로 답하는 실수를 자주 합니다. 가족이 좋아하는 간식이나 일주일 날씨를 함께 조사해 직접 그래프로 그려 보게 하고, \"한 칸을 2로 하면 어떻게 달라질까?\"라고 물어봐 주세요."}$json$::jsonb,33) on conflict (slug) do nothing;
update public.topics set lesson_slug='m3-03' where band='3~4' and subject='수학' and name='자료의 정리';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m3-04','3~4','수학','덧셈과 뺄셈','받아올림과 받아내림, 왜 필요할까?','assets/img/l_m3-04.jpg',$json${"intro": "도서관에 동화책 456권과 과학책 278권이 있어요. 모두 몇 권일까요? 세 자리 수끼리 더하고 빼는 방법을 알아봐요.", "sections": [{"heading": "자리를 맞추어 일의 자리부터", "paras": ["세 자리 수를 계산할 때는 백, 십, 일의 자리를 세로로 맞추어 쓰고 일의 자리부터 계산해요.", "같은 자리끼리 계산해야 하는 이유는 같은 숫자라도 자리에 따라 나타내는 값이 다르기 때문이에요. 324에서 3은 300, 2는 20, 4는 4예요."], "example": "324 + 152 = 476 (일 4+2=6, 십 2+5=7, 백 3+1=4)", "figure": "백·십·일 자리 칸에 숫자를 맞추어 쓴 세로셈 그림"}, {"heading": "이렇게 풀어요: 받아올림이 있는 덧셈", "paras": ["456 + 278을 풀어 볼까요? ① 일의 자리 6 + 8 = 14, 4를 쓰고 10은 십의 자리로 1을 올려요.", "② 십의 자리 5 + 7 + 1 = 13, 3을 쓰고 백의 자리로 1을 올려요. ③ 백의 자리 4 + 2 + 1 = 7이에요. 답은 734예요."], "example": "456 + 278 = 734", "figure": "456 + 278 세로셈에서 받아올린 1을 작게 위에 적은 그림"}, {"heading": "이렇게 풀어요: 받아내림이 있는 뺄셈", "paras": ["503 − 267을 풀어 볼까요? 일의 자리 3에서 7을 뺄 수 없어요. 십의 자리가 0이라서 백의 자리에서 먼저 받아내려요.", "백의 자리 5는 4가 되고 십의 자리는 10이 돼요. 다시 십의 자리에서 1을 일의 자리로 내리면 십은 9, 일은 13이에요. 13 − 7 = 6, 9 − 6 = 3, 4 − 2 = 2라서 236이에요."], "example": "503 − 267 = 236", "figure": "503 − 267 세로셈에서 받아내린 숫자를 고쳐 쓴 그림"}, {"heading": "어림하고 검산해요", "paras": ["계산하기 전에 어림하면 답이 맞는지 짐작할 수 있어요. 312 + 289는 약 300 + 300 = 600쯤이고, 실제로는 601이에요.", "뺄셈은 덧셈으로 검산할 수 있어요. 503 − 267 = 236이 맞는지 236 + 267을 계산하면 503이 나와요."], "example": "검산: 236 + 267 = 503 → 503 − 267 = 236이 맞아요", "figure": "뺄셈식과 검산 덧셈식을 화살표로 이은 그림"}], "keywords": [{"word": "받아올림", "meaning": "같은 자리의 합이 10 이상일 때 윗자리로 1을 올리는 것"}, {"word": "받아내림", "meaning": "뺄 수 없을 때 윗자리에서 10을 빌려 오는 것"}, {"word": "어림", "meaning": "대강 짐작해서 셈하는 것"}, {"word": "검산", "meaning": "계산이 맞는지 다시 확인하는 것"}], "expressions": [], "quiz": [{"q": "368 + 457은 얼마일까요?", "choices": ["715", "815", "825", "725"], "answer": 2, "explain": "8 + 7 = 15, 6 + 5 + 1 = 12, 3 + 4 + 1 = 8이라서 825예요."}, {"q": "702 − 358은 얼마일까요?", "choices": ["344", "354", "456", "444"], "answer": 0, "explain": "백의 자리에서 받아내려 계산하면 344예요. 344 + 358 = 702로 검산할 수 있어요."}, {"q": "512 − 289 = 223을 검산하는 식으로 알맞은 것은?", "choices": ["223 + 289 = 512", "512 + 289 = 801", "289 − 223 = 66", "512 − 223 = 279"], "answer": 0, "explain": "뺄셈의 답과 빼는 수를 더하면 처음 수가 나와요."}, {"q": "어제 줄넘기를 245번, 오늘 186번 했어요. 모두 몇 번 했을까요?", "choices": ["421번", "431번", "331번", "441번"], "answer": 1, "explain": "245 + 186 = 431번이에요."}, {"q": "색종이 600장 중 247장을 썼어요. 남은 색종이는 몇 장일까요?", "choices": ["353장", "363장", "453장", "347장"], "answer": 0, "explain": "600 − 247 = 353장이에요."}], "summary": ["자리를 맞추어 쓰고 일의 자리부터 계산해요.", "덧셈에서 10이 넘으면 받아올림, 뺄셈에서 뺄 수 없으면 받아내림을 해요.", "어림으로 답을 짐작하고, 뺄셈은 덧셈으로 검산해요."], "parent_tip": "703 − 268처럼 십의 자리가 0인 뺄셈에서 받아내림을 두 번 해야 하는 경우를 가장 어려워합니다. 동전(100원, 10원, 1원)으로 실제로 바꿔 주며 계산해 보면 이해가 빠릅니다. 답을 낸 뒤 \"덧셈으로 확인해 볼까?\"라고 검산 습관을 길러 주세요."}$json$::jsonb,34) on conflict (slug) do nothing;
update public.topics set lesson_slug='m3-04' where band='3~4' and subject='수학' and name='덧셈과 뺄셈';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m3-05','3~4','수학','나눗셈','똑같이 나누면 몇 개씩일까?','assets/img/l_m3-05.jpg',$json${"intro": "쿠키 12개를 친구 3명이 똑같이 나눠 먹으려면 한 명이 몇 개씩 먹어야 할까요? 이럴 때 나눗셈을 써요.", "sections": [{"heading": "나눗셈의 두 가지 뜻", "paras": ["12 ÷ 3은 '12를 3명에게 똑같이 나누면 한 명에 몇 개?'라는 뜻도 되고, '12를 3개씩 묶으면 몇 묶음?'이라는 뜻도 돼요.", "12 ÷ 3 = 4에서 12는 나누어지는 수, 3은 나누는 수, 4는 몫이라고 해요."], "example": "12 ÷ 3 = 4 (쿠키 12개를 3명이 나누면 한 명에 4개)", "figure": "쿠키 12개를 접시 3개에 4개씩 나누어 담은 그림"}, {"heading": "곱셈과 나눗셈은 친구예요", "paras": ["나눗셈의 몫은 곱셈구구로 찾을 수 있어요. 12 ÷ 3의 몫은 3 × □ = 12에서 □를 찾으면 돼요.", "그래서 4 × 3 = 12라는 곱셈식 하나로 12 ÷ 3 = 4, 12 ÷ 4 = 3이라는 나눗셈식 두 개를 만들 수 있어요."], "example": "4 × 3 = 12 → 12 ÷ 3 = 4, 12 ÷ 4 = 3", "figure": "곱셈식 하나에서 나눗셈식 두 개로 화살표가 뻗어 나가는 그림"}, {"heading": "나머지가 있는 나눗셈", "paras": ["29 ÷ 4는 4씩 7묶음을 만들면 28이 되고 1이 남아요. 이것을 29 ÷ 4 = 7 … 1이라고 쓰고, 1을 나머지라고 해요.", "나머지는 항상 나누는 수보다 작아야 해요. 계산이 맞는지는 '나누는 수 × 몫 + 나머지 = 나누어지는 수'로 확인해요."], "example": "29 ÷ 4 = 7 … 1 → 확인: 4 × 7 + 1 = 29", "figure": "구슬 29개를 4개씩 7묶음으로 묶고 1개가 남은 그림"}, {"heading": "이렇게 풀어요: 세로로 나누기", "paras": ["75 ÷ 3을 풀어 볼까요? ① 십의 자리 7을 3으로 나누면 몫 2, 나머지 1이에요. 몫 2를 십의 자리에 써요.", "② 남은 1(10을 뜻해요)과 일의 자리 5를 합쳐 15를 만들어요. ③ 15 ÷ 3 = 5, 몫 5를 일의 자리에 써요. 답은 25예요. 4학년에서는 156 ÷ 12 = 13처럼 두 자리 수로 나누는 것도 같은 방법으로 해요."], "example": "75 ÷ 3 = 25, 156 ÷ 12 = 13", "figure": "75 ÷ 3 나눗셈 세로식에서 단계별로 몫을 쓰는 그림"}], "keywords": [{"word": "나눗셈", "meaning": "어떤 수를 똑같이 나누는 계산"}, {"word": "몫", "meaning": "나눗셈을 해서 나온 값"}, {"word": "나머지", "meaning": "똑같이 나누고 남은 수, 나누는 수보다 작아요"}, {"word": "나누어떨어진다", "meaning": "나머지가 0인 것"}], "expressions": [], "quiz": [{"q": "42 ÷ 6의 몫은 얼마일까요?", "choices": ["6", "7", "8", "9"], "answer": 1, "explain": "6 × 7 = 42이므로 몫은 7이에요."}, {"q": "29 ÷ 4의 몫과 나머지는?", "choices": ["몫 6, 나머지 5", "몫 7, 나머지 1", "몫 7, 나머지 2", "몫 8, 나머지 1"], "answer": 1, "explain": "4 × 7 = 28이고 1이 남아요. 나머지 5는 4보다 커서 틀려요."}, {"q": "84 ÷ 4는 얼마일까요?", "choices": ["21", "22", "24", "12"], "answer": 0, "explain": "8 ÷ 4 = 2, 4 ÷ 4 = 1이라서 21이에요."}, {"q": "사탕 50개를 7명이 똑같이 나누면 한 명에 몇 개씩 주고 몇 개가 남을까요?", "choices": ["6개씩, 8개 남음", "7개씩, 1개 남음", "7개씩, 2개 남음", "8개씩, 1개 남음"], "answer": 1, "explain": "7 × 7 = 49이므로 7개씩 주고 1개가 남아요."}, {"q": "38 ÷ 5 = 7 … 3이 맞는지 확인하는 식은?", "choices": ["5 × 7 + 3 = 38", "5 × 3 + 7 = 22", "38 × 5 = 190", "7 × 3 + 5 = 26"], "answer": 0, "explain": "나누는 수 × 몫 + 나머지 = 나누어지는 수로 확인해요."}], "summary": ["나눗셈은 똑같이 나누거나 똑같이 묶을 때 써요.", "나눗셈의 몫은 곱셈구구로 찾을 수 있어요.", "나머지는 나누는 수보다 작아야 하고, 나누는 수 × 몫 + 나머지로 확인해요."], "parent_tip": "나머지가 나누는 수보다 큰데도 그대로 답하는 실수가 흔합니다. \"남은 걸로 한 명에게 하나씩 더 줄 수 있지 않을까?\"라고 물어 스스로 고치게 해 주세요. 간식을 가족 수대로 나누어 보는 활동이 가장 좋은 연습입니다."}$json$::jsonb,35) on conflict (slug) do nothing;
update public.topics set lesson_slug='m3-05' where band='3~4' and subject='수학' and name='나눗셈';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m3-06','3~4','수학','길이와 시간','mm, km, 초는 언제 쓸까?','assets/img/l_m3-06.jpg',$json${"intro": "개미의 몸길이와 학교까지의 거리를 같은 단위로 재면 불편하겠죠? 길이와 시간에는 상황에 맞는 여러 단위가 있어요.", "sections": [{"heading": "1cm보다 작은 단위 mm", "paras": ["자의 1cm 사이에는 작은 눈금 10칸이 있어요. 작은 눈금 한 칸의 길이를 1mm(1밀리미터)라고 해요.", "그래서 1cm = 10mm예요. 3cm보다 5mm 더 긴 길이는 3cm 5mm라고 쓰고, 35mm와 같아요."], "example": "3cm 5mm = 30mm + 5mm = 35mm", "figure": "자를 크게 확대해 1cm 안의 작은 눈금 10칸을 보여 주는 그림"}, {"heading": "1000m보다 긴 단위 km", "paras": ["먼 거리를 나타낼 때는 km(킬로미터)를 써요. 1000m = 1km예요.", "2km보다 300m 더 먼 거리는 2km 300m이고, 2300m와 같아요."], "example": "2km 300m = 2000m + 300m = 2300m", "figure": "집에서 학교, 도서관까지의 거리를 km와 m로 표시한 지도 그림"}, {"heading": "1분보다 짧은 단위 초", "paras": ["초바늘이 작은 눈금 한 칸을 가는 시간이 1초예요. 초바늘이 시계를 한 바퀴 돌면 60초이고, 이것이 1분이에요.", "그래서 1분 = 60초, 1시간 = 60분이에요. 2분 10초는 120초 + 10초 = 130초예요."], "example": "1분 = 60초, 2분 10초 = 130초", "figure": "초바늘이 있는 시계에서 초바늘이 한 바퀴 도는 모습을 화살표로 나타낸 그림"}, {"heading": "이렇게 풀어요: 시간의 덧셈과 뺄셈", "paras": ["1시간 40분 + 35분: ① 분끼리 더하면 40 + 35 = 75분. ② 60분은 1시간이므로 75분 = 1시간 15분. ③ 1시간 + 1시간 15분 = 2시간 15분이에요.", "4시 20분 − 1시 45분: 20분에서 45분을 뺄 수 없으니 1시간을 60분으로 바꿔 3시 80분으로 생각해요. 80 − 45 = 35분, 3 − 1 = 2시간이라서 2시간 35분이에요."], "example": "1시간 40분 + 35분 = 2시간 15분, 4시 20분 − 1시 45분 = 2시간 35분", "figure": "시간 받아올림과 받아내림을 세로셈으로 보여 주는 그림"}], "keywords": [{"word": "mm(밀리미터)", "meaning": "1cm를 10칸으로 똑같이 나눈 한 칸의 길이"}, {"word": "km(킬로미터)", "meaning": "1000m를 나타내는 길이 단위"}, {"word": "초", "meaning": "1분을 60으로 나눈 짧은 시간"}, {"word": "시간", "meaning": "어떤 시각부터 어떤 시각까지의 동안"}], "expressions": [], "quiz": [{"q": "7cm 4mm는 몇 mm일까요?", "choices": ["74mm", "704mm", "11mm", "47mm"], "answer": 0, "explain": "7cm = 70mm이므로 70 + 4 = 74mm예요."}, {"q": "3050m는 몇 km 몇 m일까요?", "choices": ["3km 5m", "3km 50m", "3km 500m", "30km 50m"], "answer": 1, "explain": "3000m = 3km이고 50m가 남아 3km 50m예요."}, {"q": "2분 15초는 몇 초일까요?", "choices": ["35초", "125초", "135초", "215초"], "answer": 2, "explain": "2분 = 120초이므로 120 + 15 = 135초예요."}, {"q": "2시 50분에서 25분이 지나면 몇 시 몇 분일까요?", "choices": ["2시 75분", "3시 5분", "3시 15분", "3시 25분"], "answer": 2, "explain": "50 + 25 = 75분 = 1시간 15분이라서 3시 15분이에요."}, {"q": "5시 10분에서 2시간 30분 전은 몇 시 몇 분일까요?", "choices": ["2시 40분", "3시 20분", "2시 20분", "3시 40분"], "answer": 0, "explain": "5시 10분을 4시 70분으로 바꾸면 70 − 30 = 40분, 4 − 2 = 2시라서 2시 40분이에요."}], "summary": ["1cm = 10mm, 1km = 1000m예요.", "1분 = 60초, 1시간 = 60분이에요.", "시간 계산에서는 60분이 되면 1시간으로 올리고, 모자라면 1시간을 60분으로 바꿔요."], "parent_tip": "시간 계산에서 아이들은 100을 기준으로 받아내림하는 실수(예: 80분이 아니라 110분으로 계산)를 자주 합니다. 아날로그 시계를 함께 보며 \"60분이 되면 바늘이 어디로 가지?\"라고 확인해 주세요. 외출 시 \"도착까지 몇 분 남았을까?\"를 계산해 보게 하면 좋습니다."}$json$::jsonb,36) on conflict (slug) do nothing;
update public.topics set lesson_slug='m3-06' where band='3~4' and subject='수학' and name='길이와 시간';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m3-07','3~4','수학','들이와 무게','물병에 물이 얼마나 들어갈까?','assets/img/l_m3-07.jpg',$json${"intro": "우유갑과 물통 중 어느 쪽에 물이 더 많이 들어갈까요? 수박과 사과 중 어느 쪽이 더 무거울까요? 들이와 무게를 재는 단위를 알아봐요.", "sections": [{"heading": "들이와 단위 L, mL", "paras": ["그릇 안에 담을 수 있는 양을 들이라고 해요. 들이의 단위에는 L(리터)와 mL(밀리리터)가 있어요.", "1L = 1000mL예요. 1L보다 300mL 더 많은 들이는 1L 300mL이고, 1300mL와 같아요."], "example": "1L 300mL = 1000mL + 300mL = 1300mL", "figure": "1L 우유갑과 200mL 우유갑을 나란히 놓고 들이를 표시한 그림"}, {"heading": "무게와 단위 kg, g, t", "paras": ["물건이 무거운 정도를 무게라고 해요. 무게의 단위에는 g(그램), kg(킬로그램), t(톤)이 있어요.", "1kg = 1000g이고, 아주 무거운 트럭 같은 것은 1t = 1000kg을 써요. 2kg 500g은 2500g과 같아요."], "example": "2kg 500g = 2000g + 500g = 2500g", "figure": "저울 위에 사과(g), 수박(kg), 트럭(t)을 그려 단위를 비교한 그림"}, {"heading": "이렇게 풀어요: 들이의 덧셈", "paras": ["1L 300mL + 2L 800mL를 풀어 볼까요? ① mL끼리 더하면 300 + 800 = 1100mL. ② 1000mL는 1L이므로 1100mL = 1L 100mL.", "③ L끼리 더하면 1 + 2 = 3L이고, 올라온 1L를 더해 4L. 답은 4L 100mL예요."], "example": "1L 300mL + 2L 800mL = 4L 100mL", "figure": "L와 mL를 따로 세로셈으로 계산하고 1000mL를 1L로 올리는 그림"}, {"heading": "이렇게 풀어요: 무게의 뺄셈", "paras": ["3kg 200g − 1kg 500g을 풀어 볼까요? 200g에서 500g을 뺄 수 없어요. 1kg을 1000g으로 바꿔 2kg 1200g으로 생각해요.", "1200 − 500 = 700g, 2 − 1 = 1kg이라서 답은 1kg 700g이에요. 들이의 뺄셈도 1L를 1000mL로 바꾸어 같은 방법으로 해요."], "example": "3kg 200g − 1kg 500g = 1kg 700g", "figure": "kg과 g 세로셈에서 1kg을 1000g으로 받아내린 그림"}], "keywords": [{"word": "들이", "meaning": "그릇 안에 담을 수 있는 양"}, {"word": "L와 mL", "meaning": "들이의 단위, 1L = 1000mL"}, {"word": "무게", "meaning": "물건이 무거운 정도"}, {"word": "kg과 g", "meaning": "무게의 단위, 1kg = 1000g"}, {"word": "t(톤)", "meaning": "1000kg을 나타내는 무게 단위"}], "expressions": [], "quiz": [{"q": "2L 50mL는 몇 mL일까요?", "choices": ["250mL", "2050mL", "2500mL", "2005mL"], "answer": 1, "explain": "2L = 2000mL이므로 2000 + 50 = 2050mL예요."}, {"q": "4500g은 몇 kg 몇 g일까요?", "choices": ["4kg 500g", "45kg", "4kg 50g", "450kg"], "answer": 0, "explain": "4000g = 4kg이고 500g이 남아 4kg 500g이에요."}, {"q": "1L 600mL + 700mL는 얼마일까요?", "choices": ["1L 1300mL", "2L 300mL", "2L 30mL", "8L 600mL"], "answer": 1, "explain": "600 + 700 = 1300mL = 1L 300mL이므로 모두 2L 300mL예요."}, {"q": "5kg − 2kg 300g은 얼마일까요?", "choices": ["3kg 300g", "2kg 700g", "3kg 700g", "2kg 300g"], "answer": 1, "explain": "5kg을 4kg 1000g으로 바꾸면 1000 − 300 = 700g, 4 − 2 = 2kg이에요."}, {"q": "트럭의 무게를 나타내기에 가장 알맞은 단위는?", "choices": ["mL", "g", "t", "L"], "answer": 2, "explain": "트럭처럼 아주 무거운 것은 t(톤) 단위를 써요."}], "summary": ["들이는 담을 수 있는 양이고 1L = 1000mL예요.", "무게의 단위는 g, kg, t이고 1kg = 1000g, 1t = 1000kg이에요.", "같은 단위끼리 계산하고 1000이 되면 큰 단위로 바꿔요."], "parent_tip": "들이와 무게를 헷갈리는 아이가 많습니다. 부엌의 계량컵과 저울로 직접 재 보며 \"이건 양을 재는 걸까, 무거운 정도를 재는 걸까?\"라고 물어봐 주세요. 우유갑, 생수병에 적힌 mL와 과자 봉지의 g을 찾아보는 것도 좋은 연습입니다."}$json$::jsonb,37) on conflict (slug) do nothing;
update public.topics set lesson_slug='m3-07' where band='3~4' and subject='수학' and name='들이와 무게';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m3-08','3~4','수학','평면도형','선과 각으로 어떤 도형을 만들까?','assets/img/l_m3-08.jpg',$json${"intro": "공책, 창문, 책상 모서리를 잘 보면 반듯한 선과 꼭 맞는 각이 숨어 있어요. 평면도형의 이름과 특징을 알아봐요.", "sections": [{"heading": "선분, 반직선, 직선", "paras": ["두 점을 곧게 이은 선을 선분이라고 해요. 선분 ㄱㄴ처럼 두 점의 이름으로 불러요.", "한 점에서 시작해 한쪽으로 끝없이 늘인 곧은 선은 반직선, 양쪽으로 끝없이 늘인 곧은 선은 직선이에요."], "example": "점 3개를 두 개씩 모두 이으면 선분이 3개 생겨요", "figure": "선분, 반직선, 직선을 나란히 그리고 끝없이 늘어나는 쪽에 화살표를 표시한 그림"}, {"heading": "각과 직각", "paras": ["한 점에서 그은 두 반직선으로 이루어진 도형을 각이라고 해요. 각을 이루는 점을 꼭짓점, 두 반직선을 변이라고 해요.", "종이를 반듯하게 두 번 접었을 때 생기는 각을 직각이라고 해요. 시계가 3시를 가리킬 때 두 바늘이 이루는 각도 직각이에요."], "example": "3시 정각의 시곗바늘 → 직각", "figure": "종이를 두 번 접어 만든 직각과 3시를 가리키는 시계 그림"}, {"heading": "이렇게 찾아요: 직각 확인하기", "paras": ["① 삼각자의 직각인 부분이나 접어 만든 직각 종이를 준비해요. ② 각의 꼭짓점에 직각 부분의 꼭짓점을 맞춰요.", "③ 한 변을 겹친 뒤 다른 한 변도 꼭 겹치면 직각이에요. 직각은 꼭짓점에 작은 네모(⌐) 표시를 해서 나타내요."], "example": "직사각형의 네 각에 삼각자를 대 보면 모두 꼭 맞아요 → 직각 4개", "figure": "삼각자의 직각을 도형의 각에 대 보는 손 그림"}, {"heading": "직각삼각형, 직사각형, 정사각형", "paras": ["한 각이 직각인 삼각형은 직각삼각형이에요. 네 각이 모두 직각인 사각형은 직사각형이에요.", "네 각이 모두 직각이고 네 변의 길이도 모두 같은 사각형은 정사각형이에요. 그래서 정사각형은 직사각형이라고도 할 수 있지만, 모든 직사각형이 정사각형은 아니에요."], "example": "직각삼각형: 직각 1개, 직사각형: 직각 4개, 정사각형: 직각 4개 + 네 변의 길이가 같음", "figure": "직각삼각형, 직사각형, 정사각형을 나란히 그리고 직각 표시를 한 그림"}], "keywords": [{"word": "선분", "meaning": "두 점을 곧게 이은 선"}, {"word": "반직선", "meaning": "한 점에서 한쪽으로 끝없이 늘인 곧은 선"}, {"word": "직선", "meaning": "양쪽으로 끝없이 늘인 곧은 선"}, {"word": "각", "meaning": "한 점에서 그은 두 반직선으로 이루어진 도형"}, {"word": "직각", "meaning": "종이를 반듯하게 두 번 접었을 때 생기는 각"}, {"word": "정사각형", "meaning": "네 각이 직각이고 네 변의 길이가 같은 사각형"}], "expressions": [], "quiz": [{"q": "양쪽으로 끝없이 늘인 곧은 선의 이름은?", "choices": ["선분", "반직선", "직선", "곡선"], "answer": 2, "explain": "양쪽으로 끝없이 늘어나면 직선이에요."}, {"q": "직사각형에는 직각이 몇 개 있을까요?", "choices": ["1개", "2개", "3개", "4개"], "answer": 3, "explain": "직사각형은 네 각이 모두 직각이에요."}, {"q": "정사각형에 대한 설명으로 알맞은 것은?", "choices": ["직각이 1개 있다", "네 각이 직각이고 네 변의 길이가 같다", "세 변으로 이루어져 있다", "곧은 선이 하나도 없다"], "answer": 1, "explain": "정사각형은 네 각이 모두 직각이고 네 변의 길이가 모두 같아요."}, {"q": "시계가 3시 정각을 가리킬 때 긴바늘과 짧은바늘이 이루는 각은?", "choices": ["직각", "직각보다 작은 각", "직각보다 큰 각", "각이 생기지 않는다"], "answer": 0, "explain": "3시 정각에는 두 바늘이 직각을 이뤄요."}, {"q": "한 점에서 시작해 한쪽으로만 끝없이 늘인 곧은 선은?", "choices": ["직선", "반직선", "선분", "꼭짓점"], "answer": 1, "explain": "한쪽으로만 끝없이 늘어나면 반직선이에요."}], "summary": ["선분은 두 점을 이은 선, 반직선은 한쪽으로, 직선은 양쪽으로 끝없이 늘인 선이에요.", "종이를 반듯하게 두 번 접은 각이 직각이에요.", "직각삼각형은 직각 1개, 직사각형은 직각 4개, 정사각형은 직각 4개에 네 변이 모두 같아요."], "parent_tip": "반직선 ㄱㄴ과 반직선 ㄴㄱ이 서로 다르다는 것(시작점이 다름)을 많이 헷갈립니다. 집 안에서 직각을 찾는 '직각 사냥'을 하며 \"정사각형은 직사각형일까? 반대도 맞을까?\"라고 물어봐 주세요."}$json$::jsonb,38) on conflict (slug) do nothing;
update public.topics set lesson_slug='m3-08' where band='3~4' and subject='수학' and name='평면도형';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m5-01','5~6','수학','직육면체','상자 모양에는 어떤 비밀이 있을까?','assets/img/l_m5-01.jpg',$json${"intro": "과자 상자, 주사위, 벽돌은 모두 비슷한 모양이에요. 면과 모서리, 꼭짓점을 세어 보며 이 입체도형의 특징을 알아봐요.", "sections": [{"heading": "직육면체와 정육면체", "paras": ["직사각형 6개로 둘러싸인 도형을 직육면체라고 해요. 정사각형 6개로 둘러싸인 도형은 정육면체예요.", "정사각형은 직사각형이기도 하니까 정육면체도 직육면체라고 할 수 있어요. 하지만 모든 직육면체가 정육면체는 아니에요."], "example": "과자 상자 → 직육면체, 주사위 → 정육면체", "figure": "과자 상자 모양 직육면체와 주사위 모양 정육면체를 나란히 놓은 그림"}, {"heading": "면, 모서리, 꼭짓점", "paras": ["선분으로 둘러싸인 부분을 면, 면과 면이 만나는 선분을 모서리, 모서리와 모서리가 만나는 점을 꼭짓점이라고 해요.", "직육면체는 면 6개, 모서리 12개, 꼭짓점 8개예요. 마주 보는 두 면은 서로 평행하고 이런 면이 3쌍 있어요. 한 면과 만나는 4개의 면은 그 면과 수직이에요."], "example": "직육면체: 면 6개, 모서리 12개, 꼭짓점 8개, 평행한 면 3쌍", "figure": "직육면체에서 면, 모서리, 꼭짓점에 이름표를 붙인 그림"}, {"heading": "겨냥도와 전개도", "paras": ["직육면체 모양을 잘 알 수 있게 그린 그림을 겨냥도라고 해요. 보이는 모서리 9개는 실선으로, 보이지 않는 모서리 3개는 점선으로 그려요.", "직육면체의 모서리를 잘라 평면 위에 펼친 그림은 전개도예요. 전개도를 접었을 때 겹치는 면이 없고 마주 보는 면 3쌍이 모양과 크기가 같아야 해요."], "example": "겨냥도: 실선 9개 + 점선 3개 = 모서리 12개", "figure": "직육면체 겨냥도(실선과 점선)와 펼친 전개도를 함께 그린 그림"}, {"heading": "이렇게 풀어요: 모든 모서리 길이의 합", "paras": ["가로 4cm, 세로 3cm, 높이 2cm인 직육면체의 모든 모서리 길이의 합을 구해 볼까요? ① 길이가 같은 모서리가 4개씩 3묶음 있어요.", "② 한 묶음씩 더하면 4 + 3 + 2 = 9cm. ③ 4묶음이 있으니 9 × 4 = 36cm예요. 정육면체는 모서리 12개의 길이가 모두 같아서 한 모서리가 5cm면 5 × 12 = 60cm예요."], "example": "(4 + 3 + 2) × 4 = 36cm, 정육면체 한 모서리 5cm → 5 × 12 = 60cm", "figure": "같은 길이의 모서리 4개씩을 같은 색으로 칠한 직육면체 그림"}], "keywords": [{"word": "직육면체", "meaning": "직사각형 6개로 둘러싸인 도형"}, {"word": "정육면체", "meaning": "정사각형 6개로 둘러싸인 도형"}, {"word": "모서리", "meaning": "면과 면이 만나는 선분"}, {"word": "꼭짓점", "meaning": "모서리와 모서리가 만나는 점"}, {"word": "겨냥도", "meaning": "입체도형의 모양을 알 수 있게 그린 그림"}, {"word": "전개도", "meaning": "입체도형의 모서리를 잘라 평면에 펼친 그림"}], "expressions": [], "quiz": [{"q": "직육면체의 꼭짓점은 몇 개일까요?", "choices": ["6개", "8개", "12개", "4개"], "answer": 1, "explain": "직육면체는 면 6개, 모서리 12개, 꼭짓점 8개예요."}, {"q": "직육면체의 겨냥도에서 점선으로 그리는 모서리는 몇 개일까요?", "choices": ["1개", "2개", "3개", "9개"], "answer": 2, "explain": "보이지 않는 모서리 3개를 점선으로 그려요."}, {"q": "직육면체에서 한 면과 수직인 면은 몇 개일까요?", "choices": ["1개", "2개", "4개", "5개"], "answer": 2, "explain": "마주 보는 면 1개를 뺀 나머지 4개의 면이 수직이에요."}, {"q": "한 모서리가 7cm인 정육면체의 모든 모서리 길이의 합은?", "choices": ["42cm", "56cm", "84cm", "49cm"], "answer": 2, "explain": "정육면체 모서리 12개의 길이가 모두 같아서 7 × 12 = 84cm예요."}, {"q": "직육면체에서 서로 평행한 면은 모두 몇 쌍일까요?", "choices": ["2쌍", "3쌍", "4쌍", "6쌍"], "answer": 1, "explain": "마주 보는 면끼리 평행하고 3쌍이 있어요."}], "summary": ["직육면체는 직사각형 6개, 정육면체는 정사각형 6개로 둘러싸여 있어요.", "직육면체는 면 6개, 모서리 12개, 꼭짓점 8개예요.", "겨냥도는 보이지 않는 모서리 3개를 점선으로, 전개도는 펼친 모양으로 나타내요."], "parent_tip": "겨냥도에서 보이지 않는 모서리를 빠뜨리거나 전개도에서 겹치는 면을 찾지 못하는 경우가 많습니다. 빈 과자 상자를 모서리를 따라 직접 잘라 펼쳐 보면 효과적입니다. \"이 면과 마주 보는 면은 어디일까?\"라고 물어봐 주세요."}$json$::jsonb,131) on conflict (slug) do nothing;
update public.topics set lesson_slug='m5-01' where band='5~6' and subject='수학' and name='직육면체';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m5-02','5~6','수학','직육면체의 부피','상자 안의 공간은 얼마나 클까?','assets/img/l_m5-02.jpg',$json${"intro": "두 상자 중 어느 쪽에 물건이 더 많이 들어갈까요? 겉으로 보기에 비슷해도 공간의 크기는 다를 수 있어요. 공간의 크기를 수로 나타내는 방법을 알아봐요.", "sections": [{"heading": "부피와 1cm³", "paras": ["어떤 물건이 공간에서 차지하는 크기를 부피라고 해요. 부피를 비교하려면 기준이 되는 단위가 필요해요.", "한 모서리가 1cm인 정육면체의 부피를 1cm³라 쓰고 1세제곱센티미터라고 읽어요. 이 쌓기나무가 몇 개 들어가는지 세면 부피를 알 수 있어요."], "example": "1cm³ 쌓기나무 12개로 만든 직육면체 → 부피 12cm³", "figure": "한 모서리가 1cm인 쌓기나무와 그것으로 쌓은 직육면체 그림"}, {"heading": "이렇게 풀어요: 직육면체의 부피", "paras": ["가로 5cm, 세로 4cm, 높이 3cm인 직육면체를 생각해 봐요. ① 바닥 한 층에는 1cm³ 쌓기나무가 5 × 4 = 20개 깔려요.", "② 이런 층이 높이만큼 3층 있으니 20 × 3 = 60개예요. 그래서 직육면체의 부피 = 가로 × 세로 × 높이 = 60cm³예요."], "example": "5 × 4 × 3 = 60cm³", "figure": "쌓기나무 20개가 한 층을 이루고 3층으로 쌓인 직육면체 그림"}, {"heading": "정육면체의 부피", "paras": ["정육면체는 가로, 세로, 높이가 모두 같아요. 그래서 정육면체의 부피 = 한 모서리 × 한 모서리 × 한 모서리예요.", "한 모서리가 6cm인 정육면체의 부피는 6 × 6 × 6 = 216cm³예요."], "example": "6 × 6 × 6 = 216cm³", "figure": "한 모서리가 6cm라고 표시된 정육면체 그림"}, {"heading": "큰 부피의 단위 m³", "paras": ["방이나 컨테이너처럼 큰 부피는 한 모서리가 1m인 정육면체의 부피 1m³(1세제곱미터)를 써요.", "1m = 100cm이므로 1m³ = 100 × 100 × 100 = 1000000cm³예요. 가로 2m, 세로 1m, 높이 3m인 상자의 부피는 6m³이고, 6000000cm³와 같아요."], "example": "1m³ = 1000000cm³, 2 × 1 × 3 = 6m³", "figure": "1m³ 정육면체 안에 작은 1cm³ 쌓기나무가 가득한 모습을 상상한 그림"}], "keywords": [{"word": "부피", "meaning": "물건이 공간에서 차지하는 크기"}, {"word": "cm³(세제곱센티미터)", "meaning": "한 모서리가 1cm인 정육면체의 부피"}, {"word": "m³(세제곱미터)", "meaning": "한 모서리가 1m인 정육면체의 부피"}, {"word": "겉넓이", "meaning": "입체도형 겉면 전체의 넓이"}], "expressions": [], "quiz": [{"q": "가로 8cm, 세로 5cm, 높이 2cm인 직육면체의 부피는?", "choices": ["15cm³", "40cm³", "80cm³", "160cm³"], "answer": 2, "explain": "8 × 5 × 2 = 80cm³예요."}, {"q": "한 모서리가 4cm인 정육면체의 부피는?", "choices": ["12cm³", "16cm³", "48cm³", "64cm³"], "answer": 3, "explain": "4 × 4 × 4 = 64cm³예요."}, {"q": "3m³는 몇 cm³일까요?", "choices": ["300cm³", "3000cm³", "300000cm³", "3000000cm³"], "answer": 3, "explain": "1m³ = 1000000cm³이므로 3m³ = 3000000cm³예요."}, {"q": "부피가 120cm³인 직육면체의 가로가 6cm, 세로가 5cm예요. 높이는 몇 cm일까요?", "choices": ["3cm", "4cm", "5cm", "6cm"], "answer": 1, "explain": "6 × 5 = 30이고 30 × 높이 = 120이므로 높이는 4cm예요."}, {"q": "1cm³ 쌓기나무를 가로 3개, 세로 3개씩 4층으로 쌓았어요. 부피는?", "choices": ["10cm³", "24cm³", "36cm³", "48cm³"], "answer": 2, "explain": "한 층에 3 × 3 = 9개, 4층이면 9 × 4 = 36개라 36cm³예요."}], "summary": ["부피는 물건이 공간에서 차지하는 크기예요.", "직육면체의 부피 = 가로 × 세로 × 높이, 정육면체의 부피 = 한 모서리 × 한 모서리 × 한 모서리예요.", "1m³ = 1000000cm³예요."], "parent_tip": "1m³ = 100cm³로 잘못 아는 경우가 아주 많습니다. 가로·세로·높이가 모두 100배가 되므로 100 × 100 × 100이라는 점을 짚어 주세요. 집에 있는 상자의 길이를 재서 부피를 구하고 \"부피가 같은데 모양이 다른 상자도 있을까?\"라고 물어보면 좋습니다."}$json$::jsonb,132) on conflict (slug) do nothing;
update public.topics set lesson_slug='m5-02' where band='5~6' and subject='수학' and name='직육면체의 부피';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m5-03','5~6','수학','약수와 배수','나누어떨어지는 수에는 어떤 규칙이 있을까?','assets/img/l_m5-03.jpg',$json${"intro": "사탕 12개를 남김없이 똑같이 나누려면 몇 명에게 나눌 수 있을까요? 이 질문의 답을 찾다 보면 약수와 배수를 만나게 돼요.", "sections": [{"heading": "약수: 나누어떨어지게 하는 수", "paras": ["어떤 수를 나누어떨어지게 하는 수를 그 수의 약수라고 해요. 12는 1, 2, 3, 4, 6, 12로 나누면 나누어떨어지므로 이 수들이 12의 약수예요.", "1은 모든 수의 약수이고, 어떤 수 자신도 항상 그 수의 약수예요."], "example": "12의 약수: 1, 2, 3, 4, 6, 12", "figure": "사탕 12개를 1명, 2명, 3명, 4명, 6명, 12명에게 남김없이 나누는 모습을 표로 정리한 그림"}, {"heading": "배수: 몇 배 한 수", "paras": ["어떤 수를 1배, 2배, 3배…한 수를 그 수의 배수라고 해요. 4의 배수는 4, 8, 12, 16…처럼 끝없이 이어져요.", "4 × 3 = 12에서 12는 4와 3의 배수이고, 4와 3은 12의 약수예요. 약수와 배수는 곱셈식 하나로 연결되어 있어요."], "example": "4의 배수: 4, 8, 12, 16, …", "figure": "수직선 위에 4씩 뛰어 센 자리에 표시를 한 그림"}, {"heading": "공약수와 최대공약수", "paras": ["두 수의 공통된 약수를 공약수, 그중 가장 큰 수를 최대공약수라고 해요.", "18의 약수는 1, 2, 3, 6, 9, 18이고 24의 약수는 1, 2, 3, 4, 6, 8, 12, 24예요. 공약수는 1, 2, 3, 6이고 최대공약수는 6이에요. 공약수는 최대공약수의 약수와 같아요."], "example": "18과 24의 최대공약수 = 6", "figure": "18의 약수와 24의 약수를 두 원에 넣고 겹치는 부분에 공약수를 쓴 그림"}, {"heading": "이렇게 풀어요: 최소공배수 구하기", "paras": ["두 수의 공통된 배수를 공배수, 그중 가장 작은 수를 최소공배수라고 해요. ① 18과 24를 둘 다 나눌 수 있는 수로 나눠요: 2로 나누면 9와 12, 3으로 나누면 3과 4.", "② 더 이상 공통으로 나눌 수 없으면 멈춰요. ③ 나눈 수를 곱하면 최대공약수 2 × 3 = 6, 나눈 수와 남은 수를 모두 곱하면 최소공배수 2 × 3 × 3 × 4 = 72예요."], "example": "18과 24의 최소공배수 = 2 × 3 × 3 × 4 = 72", "figure": "18과 24를 공약수로 차례로 나누는 거꾸로 된 나눗셈 그림(ㄴ자 모양)"}], "keywords": [{"word": "약수", "meaning": "어떤 수를 나누어떨어지게 하는 수"}, {"word": "배수", "meaning": "어떤 수를 1배, 2배, 3배…한 수"}, {"word": "공약수", "meaning": "두 수의 공통된 약수"}, {"word": "최대공약수", "meaning": "공약수 중 가장 큰 수"}, {"word": "공배수", "meaning": "두 수의 공통된 배수"}, {"word": "최소공배수", "meaning": "공배수 중 가장 작은 수"}], "expressions": [], "quiz": [{"q": "20의 약수는 모두 몇 개일까요?", "choices": ["4개", "5개", "6개", "8개"], "answer": 2, "explain": "20의 약수는 1, 2, 4, 5, 10, 20으로 6개예요."}, {"q": "30과 45의 최대공약수는?", "choices": ["5", "10", "15", "90"], "answer": 2, "explain": "30과 45를 둘 다 나누어떨어지게 하는 가장 큰 수는 15예요."}, {"q": "6과 8의 최소공배수는?", "choices": ["2", "14", "24", "48"], "answer": 2, "explain": "6의 배수와 8의 배수에서 처음으로 같은 수는 24예요."}, {"q": "다음 중 7의 배수가 아닌 것은?", "choices": ["14", "21", "36", "49"], "answer": 2, "explain": "36 ÷ 7 = 5 … 1로 나누어떨어지지 않아요."}, {"q": "A 버스는 12분마다, B 버스는 18분마다 출발해요. 두 버스가 동시에 출발한 뒤 다음에 동시에 출발하는 것은 몇 분 후일까요?", "choices": ["6분 후", "30분 후", "36분 후", "216분 후"], "answer": 2, "explain": "12와 18의 최소공배수인 36분 후예요."}], "summary": ["약수는 어떤 수를 나누어떨어지게 하는 수, 배수는 어떤 수를 몇 배 한 수예요.", "최대공약수는 공약수 중 가장 큰 수, 최소공배수는 공배수 중 가장 작은 수예요.", "공약수는 최대공약수의 약수이고, 공배수는 최소공배수의 배수예요."], "parent_tip": "약수와 배수의 뜻을 서로 바꿔 말하는 실수가 많습니다. \"12와 4 중 누가 누구의 약수야?\"처럼 짧게 자주 물어 주세요. 문장제에서 최대공약수와 최소공배수 중 무엇을 써야 할지 헷갈려 하면 \"똑같이 나누는 문제인지, 다시 만나는 문제인지\"를 먼저 생각하게 해 주세요."}$json$::jsonb,133) on conflict (slug) do nothing;
update public.topics set lesson_slug='m5-03' where band='5~6' and subject='수학' and name='약수와 배수';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m5-04','5~6','수학','분수의 덧셈과 뺄셈','분모가 다른 분수는 어떻게 더할까?','assets/img/l_m5-04.jpg',$json${"intro": "피자 1/2판과 1/3판을 합치면 얼마일까요? 조각 크기가 다르면 바로 더할 수 없어요. 조각 크기를 똑같이 맞추는 방법을 알아봐요.", "sections": [{"heading": "크기가 같은 분수와 약분", "paras": ["분모와 분자에 0이 아닌 같은 수를 곱하거나 같은 수로 나누면 크기가 같은 분수가 돼요. 1/2 = 2/4 = 3/6이에요.", "분모와 분자를 공약수로 나누어 간단하게 만드는 것을 약분이라고 해요. 6/8을 2로 약분하면 3/4이에요. 더 이상 약분할 수 없는 분수를 기약분수라고 해요."], "example": "6/8 = 3/4 (분모와 분자를 2로 나눔)", "figure": "같은 크기의 막대를 2칸, 4칸, 6칸으로 나누어 1/2, 2/4, 3/6을 비교한 그림"}, {"heading": "통분: 분모를 같게 만들기", "paras": ["분모가 다른 분수의 분모를 같게 만드는 것을 통분이라고 해요. 이때 같게 만든 분모를 공통분모라고 해요.", "공통분모는 두 분모의 최소공배수를 쓰면 수가 작아서 계산이 편해요. 1/2과 1/3은 최소공배수 6을 공통분모로 해서 3/6과 2/6으로 통분해요."], "example": "1/2 = 3/6, 1/3 = 2/6", "figure": "1/2과 1/3을 각각 6칸 막대로 다시 나누어 조각 크기를 맞춘 그림"}, {"heading": "이렇게 풀어요: 진분수의 덧셈과 뺄셈", "paras": ["1/2 + 1/3: ① 통분하면 3/6 + 2/6. ② 분모는 그대로 두고 분자끼리 더하면 5/6이에요.", "3/4 − 1/6: ① 4와 6의 최소공배수 12로 통분하면 9/12 − 2/12. ② 분자끼리 빼면 7/12예요. 답이 약분되면 기약분수로 나타내요."], "example": "1/2 + 1/3 = 3/6 + 2/6 = 5/6, 3/4 − 1/6 = 9/12 − 2/12 = 7/12", "figure": "통분한 두 분수의 조각을 이어 붙이고 떼어 내는 모습을 막대로 나타낸 그림"}, {"heading": "이렇게 풀어요: 대분수의 덧셈과 뺄셈", "paras": ["2와 1/3 + 1과 3/4: 자연수끼리 2 + 1 = 3, 분수끼리 4/12 + 9/12 = 13/12 = 1과 1/12. 합치면 4와 1/12예요.", "3과 1/5 − 1과 1/2: 분수끼리 2/10 − 5/10은 뺄 수 없으니 자연수 1을 10/10으로 바꿔 2와 12/10 − 1과 5/10 = 1과 7/10이에요. 대분수를 가분수로 바꿔 계산해도 돼요."], "example": "2와 1/3 + 1과 3/4 = 4와 1/12, 3과 1/5 − 1과 1/2 = 1과 7/10", "figure": "자연수 부분과 분수 부분을 나누어 계산하는 과정을 칸으로 정리한 그림"}], "keywords": [{"word": "약분", "meaning": "분모와 분자를 공약수로 나누어 간단히 하는 것"}, {"word": "기약분수", "meaning": "더 이상 약분할 수 없는 분수"}, {"word": "통분", "meaning": "분모가 다른 분수의 분모를 같게 만드는 것"}, {"word": "공통분모", "meaning": "통분하여 같게 만든 분모"}], "expressions": [], "quiz": [{"q": "2/3 + 1/4는 얼마일까요?", "choices": ["3/7", "3/12", "11/12", "9/12"], "answer": 2, "explain": "12로 통분하면 8/12 + 3/12 = 11/12예요."}, {"q": "5/6 − 1/4는 얼마일까요?", "choices": ["4/2", "7/12", "1/3", "4/12"], "answer": 1, "explain": "12로 통분하면 10/12 − 3/12 = 7/12예요."}, {"q": "1과 2/5 + 2와 1/2은 얼마일까요?", "choices": ["3과 3/7", "3과 9/10", "4와 1/10", "3과 3/10"], "answer": 1, "explain": "자연수 1 + 2 = 3, 분수 4/10 + 5/10 = 9/10이라 3과 9/10이에요."}, {"q": "4와 1/3 − 2와 1/2은 얼마일까요?", "choices": ["2와 1/6", "1과 5/6", "2와 5/6", "1과 1/6"], "answer": 1, "explain": "2/6 − 3/6은 뺄 수 없어 3과 8/6 − 2와 3/6 = 1과 5/6이에요."}, {"q": "12/18을 기약분수로 나타내면?", "choices": ["6/9", "4/6", "2/3", "3/4"], "answer": 2, "explain": "12와 18의 최대공약수 6으로 나누면 2/3이에요."}], "summary": ["분모와 분자에 같은 수를 곱하거나 나누면 크기가 같은 분수가 돼요.", "분모가 다른 분수는 통분한 뒤 분자끼리 더하거나 빼요.", "답은 약분해서 기약분수로 나타내요."], "parent_tip": "분모끼리, 분자끼리 더하는 실수(1/2 + 1/3 = 2/5)가 가장 흔합니다. 피자나 종이띠로 \"2/5가 1/2보다 작은데 더한 게 더 작아질 수 있을까?\"라고 물어 스스로 모순을 발견하게 해 주세요. 계산 후 약분을 잊지 않도록 마지막 확인 습관을 들여 주세요."}$json$::jsonb,134) on conflict (slug) do nothing;
update public.topics set lesson_slug='m5-04' where band='5~6' and subject='수학' and name='분수의 덧셈과 뺄셈';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m5-05','5~6','수학','소수의 곱셈','소수끼리 곱하면 소수점은 어디로 갈까?','assets/img/l_m5-05.jpg',$json${"intro": "주스 한 컵이 0.3L인데 4컵을 마시면 모두 몇 L일까요? 소수의 곱셈은 자연수의 곱셈과 소수점 위치만 알면 쉽게 풀 수 있어요.", "sections": [{"heading": "(소수) × (자연수)", "paras": ["0.3 × 4는 0.3을 4번 더한 것과 같아요. 0.3 + 0.3 + 0.3 + 0.3 = 1.2예요.", "0.3은 0.1이 3개이므로 0.3 × 4는 0.1이 12개, 즉 1.2라고 생각할 수도 있어요. 1.25 × 3도 자연수처럼 125 × 3 = 375를 구한 뒤 소수 두 자리로 맞추면 3.75예요."], "example": "0.3 × 4 = 1.2, 1.25 × 3 = 3.75", "figure": "0.3L 주스 컵 4개를 모아 1.2L 병에 붓는 그림"}, {"heading": "(자연수) × (소수)", "paras": ["6 × 0.7은 6의 0.7배라는 뜻이에요. 1보다 작은 수를 곱하면 곱은 처음 수보다 작아져요.", "6 × 7 = 42를 구하고, 곱하는 소수가 소수 한 자리이므로 곱도 소수 한 자리로 나타내면 4.2예요."], "example": "6 × 0.7 = 4.2 (6보다 작아져요)", "figure": "길이 6m 막대를 10칸으로 나누어 그중 7칸을 색칠한 그림"}, {"heading": "이렇게 풀어요: (소수) × (소수)", "paras": ["1.5 × 2.3을 풀어 볼까요? ① 소수점을 없애고 자연수처럼 15 × 23 = 345를 구해요.", "② 곱하는 두 수의 소수점 아래 자리 수를 더해요. 1.5는 한 자리, 2.3도 한 자리라서 1 + 1 = 2자리예요. ③ 345에서 소수 두 자리를 만들면 3.45예요. 0.4 × 0.6도 4 × 6 = 24에서 소수 두 자리를 만들어 0.24예요."], "example": "1.5 × 2.3 = 3.45, 0.4 × 0.6 = 0.24", "figure": "가로 1을 10칸, 세로 1을 10칸으로 나눈 모눈에서 4칸 × 6칸을 색칠해 0.24를 나타낸 그림"}, {"heading": "곱의 소수점 위치 규칙", "paras": ["소수에 10, 100, 1000을 곱하면 곱하는 수의 0의 개수만큼 소수점이 오른쪽으로 옮겨 가요. 3.25 × 10 = 32.5, 3.25 × 100 = 325예요.", "반대로 0.1, 0.01을 곱하면 소수점 아래 자리 수만큼 소수점이 왼쪽으로 옮겨 가요. 3.25 × 0.1 = 0.325예요."], "example": "3.25 × 10 = 32.5, 3.25 × 100 = 325, 3.25 × 1000 = 3250, 3.25 × 0.1 = 0.325", "figure": "소수점이 오른쪽, 왼쪽으로 한 칸씩 이동하는 모습을 화살표로 나타낸 그림"}], "keywords": [{"word": "소수", "meaning": "0.1, 2.35처럼 소수점을 사용해 나타낸 수"}, {"word": "소수점", "meaning": "자연수 부분과 소수 부분 사이에 찍는 점"}, {"word": "소수 한 자리 수", "meaning": "소수점 아래 숫자가 하나인 소수(예: 0.7)"}, {"word": "곱", "meaning": "곱셈을 해서 나온 값"}], "expressions": [], "quiz": [{"q": "0.8 × 6은 얼마일까요?", "choices": ["0.48", "4.8", "48", "6.8"], "answer": 1, "explain": "8 × 6 = 48이고 소수 한 자리라서 4.8이에요."}, {"q": "2.4 × 0.5는 얼마일까요?", "choices": ["0.12", "1.2", "12", "2.9"], "answer": 1, "explain": "24 × 5 = 120이고 소수 두 자리를 만들면 1.20 = 1.2예요."}, {"q": "1.25 × 100은 얼마일까요?", "choices": ["12.5", "125", "1250", "0.0125"], "answer": 1, "explain": "100을 곱하면 소수점이 오른쪽으로 두 칸 옮겨 가서 125예요."}, {"q": "0.3 × 0.07은 얼마일까요?", "choices": ["0.21", "0.021", "2.1", "0.0021"], "answer": 1, "explain": "3 × 7 = 21이고 소수점 아래 자리 수가 1 + 2 = 3자리라서 0.021이에요."}, {"q": "물이 1.5L씩 든 병이 4개 있어요. 물은 모두 몇 L일까요?", "choices": ["5.5L", "6L", "6.5L", "0.6L"], "answer": 1, "explain": "1.5 × 4 = 6.0이므로 6L예요."}], "summary": ["소수의 곱셈은 자연수처럼 곱한 뒤 소수점을 찍어요.", "곱의 소수점 아래 자리 수는 곱하는 두 수의 소수점 아래 자리 수의 합이에요.", "10, 100, 1000을 곱하면 소수점이 0의 개수만큼 오른쪽으로 옮겨 가요."], "parent_tip": "2.4 × 0.5 = 1.20처럼 끝자리 0을 지우는 과정에서 소수점 위치를 헷갈리는 경우가 많습니다. 계산 전에 \"2.4의 반쯤이니 1 근처겠지?\"라고 어림하게 하면 실수를 줄일 수 있습니다. 마트 가격표(100g당 가격)로 곱셈을 해 보는 것도 좋습니다."}$json$::jsonb,135) on conflict (slug) do nothing;
update public.topics set lesson_slug='m5-05' where band='5~6' and subject='수학' and name='소수의 곱셈';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m5-06','5~6','수학','비와 비율','두 수를 나눗셈으로 비교해 볼까?','assets/img/l_m5-06.jpg',$json${"intro": "농구 슛을 20번 던져 7번 넣은 친구와 10번 던져 4번 넣은 친구 중 누가 더 잘 넣었을까요? 비와 비율을 알면 공정하게 비교할 수 있어요.", "sections": [{"heading": "두 수를 비교하는 두 가지 방법", "paras": ["두 수는 뺄셈으로 비교할 수도 있고 나눗셈으로 비교할 수도 있어요. 모둠 수가 늘어날 때 사람 수와 도구 수의 차이는 변하지만, 몇 배인지는 변하지 않을 수 있어요.", "이렇게 나눗셈으로 비교할 때 쓰는 것이 비예요. 두 수 3과 5를 비교할 때 기호 :을 써서 3 : 5라고 나타내요."], "example": "모둠원 4명, 가위 2개 → 사람 수는 가위 수의 2배 (4 : 2)", "figure": "모둠마다 학생 4명과 가위 2개가 있는 모습을 여러 모둠 반복해 그린 그림"}, {"heading": "비 읽기와 기준량", "paras": ["3 : 5는 '3 대 5', '3과 5의 비', '5에 대한 3의 비', '3의 5에 대한 비'라고 읽어요.", "비 3 : 5에서 기호 : 의 오른쪽에 있는 5는 기준량, 왼쪽에 있는 3은 비교하는 양이에요. 순서를 바꾸면 다른 비가 되니 조심해요."], "example": "3 : 5 → 비교하는 양 3, 기준량 5", "figure": "3 : 5 비에서 왼쪽은 '비교하는 양', 오른쪽은 '기준량'이라고 이름표를 붙인 그림"}, {"heading": "비율과 백분율", "paras": ["기준량에 대한 비교하는 양의 크기를 비율이라고 해요. 비율 = 비교하는 양 ÷ 기준량이고, 분수나 소수로 나타내요. 3 : 5의 비율은 3/5 = 0.6이에요.", "기준량을 100으로 할 때의 비율을 백분율이라 하고 기호 %를 써요. 비율에 100을 곱하면 백분율이 돼요. 0.6은 60%예요."], "example": "3 : 5 → 비율 3/5 = 0.6 → 백분율 60%", "figure": "100칸 모눈 중 60칸을 색칠해 60%를 나타낸 그림"}, {"heading": "이렇게 풀어요: 생활 속 비율", "paras": ["슛 성공률: 20번 중 7번 → 7 ÷ 20 = 0.35 = 35%. 10번 중 4번 → 4 ÷ 10 = 0.4 = 40%. 그래서 두 번째 친구의 성공률이 더 높아요.", "할인: 20000원짜리 물건을 25% 할인하면 ① 할인 금액 = 20000 × 25/100 = 5000원. ② 판매 가격 = 20000 − 5000 = 15000원이에요."], "example": "7 ÷ 20 = 0.35 (35%), 20000원의 25% = 5000원 → 15000원", "figure": "농구 골대와 성공률 표, 할인 가격표를 함께 그린 그림"}], "keywords": [{"word": "비", "meaning": "두 수를 나눗셈으로 비교하기 위해 기호 :을 써서 나타낸 것"}, {"word": "기준량", "meaning": "비에서 기호 : 의 오른쪽에 있는, 기준이 되는 양"}, {"word": "비교하는 양", "meaning": "비에서 기호 : 의 왼쪽에 있는 양"}, {"word": "비율", "meaning": "기준량에 대한 비교하는 양의 크기"}, {"word": "백분율", "meaning": "기준량을 100으로 할 때의 비율, 기호 % 사용"}], "expressions": [], "quiz": [{"q": "비 4 : 5에서 기준량은 무엇일까요?", "choices": ["4", "5", "9", "20"], "answer": 1, "explain": "기호 : 의 오른쪽에 있는 5가 기준량이에요."}, {"q": "7 : 20의 비율을 소수로 나타내면?", "choices": ["0.35", "2.85", "0.7", "0.27"], "answer": 0, "explain": "7 ÷ 20 = 0.35예요."}, {"q": "비율 0.45를 백분율로 나타내면?", "choices": ["4.5%", "45%", "450%", "0.45%"], "answer": 1, "explain": "0.45 × 100 = 45이므로 45%예요."}, {"q": "3000원짜리 공책을 20% 할인해서 사면 얼마를 내야 할까요?", "choices": ["600원", "2000원", "2400원", "2800원"], "answer": 2, "explain": "할인 금액은 3000 × 20/100 = 600원이므로 3000 − 600 = 2400원이에요."}, {"q": "우리 반 25명 중 안경을 쓴 학생이 10명이에요. 안경을 쓴 학생의 비율을 백분율로 나타내면?", "choices": ["10%", "25%", "40%", "60%"], "answer": 2, "explain": "10 ÷ 25 = 0.4이고 0.4 × 100 = 40%예요."}], "summary": ["비는 두 수를 나눗셈으로 비교할 때 기호 :을 써서 나타내요.", "비율 = 비교하는 양 ÷ 기준량이고 분수나 소수로 나타내요.", "백분율은 비율에 100을 곱하고 %를 붙여요."], "parent_tip": "기준량과 비교하는 양을 거꾸로 놓는 실수가 가장 많습니다. \"무엇을 기준으로 비교하는 거야?\"를 먼저 말하게 해 주세요. 마트 할인 행사나 야구 타율처럼 생활 속 비율을 함께 계산해 보면 개념이 오래 남습니다."}$json$::jsonb,136) on conflict (slug) do nothing;
update public.topics set lesson_slug='m5-06' where band='5~6' and subject='수학' and name='비와 비율';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('m5-07','5~6','수학','원의 넓이','동그란 원의 넓이는 어떻게 구할까?','assets/img/l_m5-07.jpg',$json${"intro": "피자나 시계처럼 동그란 모양은 네모 칸으로 넓이를 세기 어려워요. 원을 잘게 잘라 다시 붙이면 넓이를 구하는 방법이 보여요.", "sections": [{"heading": "원주와 원주율", "paras": ["원의 둘레를 원주라고 해요. 원의 크기가 달라도 원주는 항상 지름의 약 3.14배예요.", "지름에 대한 원주의 비율을 원주율이라고 해요. 원주율은 3.1415926…처럼 끝없이 이어지는 수라서 필요에 따라 3, 3.1, 3.14 등으로 어림해서 써요."], "example": "원주율 = 원주 ÷ 지름 ≈ 3.14", "figure": "여러 크기의 원 옆에 원주를 펼친 끈과 지름 3개 남짓을 나란히 놓아 비교한 그림"}, {"heading": "원주 구하기", "paras": ["원주율 = 원주 ÷ 지름이므로 원주 = 지름 × 원주율이에요. 반지름이 주어지면 지름은 반지름 × 2예요.", "지름이 10cm인 원의 원주는 10 × 3.14 = 31.4cm예요. 거꾸로 원주를 알면 지름 = 원주 ÷ 원주율로 구할 수 있어요."], "example": "지름 10cm → 원주 10 × 3.14 = 31.4cm", "figure": "지름 10cm인 원과 그 둘레를 곧게 펼친 선분 그림"}, {"heading": "원을 잘라 직사각형 만들기", "paras": ["원을 피자처럼 아주 잘게 잘라 위아래로 엇갈리게 붙이면 직사각형에 가까워져요.", "이 직사각형의 가로는 원주의 반(지름 × 원주율 ÷ 2 = 반지름 × 원주율), 세로는 반지름이에요. 그래서 원의 넓이 = 반지름 × 반지름 × 원주율이에요."], "example": "원의 넓이 = (반지름 × 원주율) × 반지름 = 반지름 × 반지름 × 원주율", "figure": "원을 16조각으로 잘라 엇갈려 붙여 직사각형처럼 만들고 가로와 세로에 이름을 붙인 그림"}, {"heading": "이렇게 풀어요: 원의 넓이 구하기", "paras": ["반지름이 5cm인 원의 넓이(원주율 3.14): ① 반지름 × 반지름 = 5 × 5 = 25. ② 25 × 3.14 = 78.5. 답은 78.5cm²예요.", "지름이 주어지면 먼저 반으로 나눠 반지름을 구해요. 지름 8cm → 반지름 4cm → 4 × 4 × 3.14 = 50.24cm²예요."], "example": "반지름 5cm → 78.5cm², 지름 8cm → 반지름 4cm → 50.24cm²", "figure": "반지름 5cm라고 표시한 원과 계산 과정을 나란히 적은 그림"}], "keywords": [{"word": "원주", "meaning": "원의 둘레"}, {"word": "지름", "meaning": "원의 중심을 지나 원 위의 두 점을 이은 선분"}, {"word": "반지름", "meaning": "원의 중심과 원 위의 한 점을 이은 선분, 지름의 반"}, {"word": "원주율", "meaning": "지름에 대한 원주의 비율, 약 3.14"}, {"word": "원의 넓이", "meaning": "반지름 × 반지름 × 원주율"}], "expressions": [], "quiz": [{"q": "지름이 6cm인 원의 원주는? (원주율 3.14)", "choices": ["9.42cm", "18.84cm", "28.26cm", "37.68cm"], "answer": 1, "explain": "원주 = 지름 × 원주율 = 6 × 3.14 = 18.84cm예요."}, {"q": "반지름이 3cm인 원의 넓이는? (원주율 3.14)", "choices": ["9.42cm²", "18.84cm²", "28.26cm²", "113.04cm²"], "answer": 2, "explain": "3 × 3 × 3.14 = 28.26cm²예요."}, {"q": "반지름이 10cm인 원의 넓이는? (원주율 3.14)", "choices": ["31.4cm²", "62.8cm²", "314cm²", "3140cm²"], "answer": 2, "explain": "10 × 10 × 3.14 = 314cm²예요."}, {"q": "원주가 25.12cm인 원의 지름은? (원주율 3.14)", "choices": ["4cm", "8cm", "12cm", "16cm"], "answer": 1, "explain": "지름 = 원주 ÷ 원주율 = 25.12 ÷ 3.14 = 8cm예요."}, {"q": "지름이 12cm인 원의 넓이는? (원주율 3.14)", "choices": ["37.68cm²", "113.04cm²", "452.16cm²", "75.36cm²"], "answer": 1, "explain": "반지름은 6cm이므로 6 × 6 × 3.14 = 113.04cm²예요."}], "summary": ["원주율은 지름에 대한 원주의 비율로 약 3.14예요.", "원주 = 지름 × 원주율이에요.", "원의 넓이 = 반지름 × 반지름 × 원주율이에요."], "parent_tip": "지름이 주어졌는데 반지름으로 바꾸지 않고 넓이를 구하는 실수가 가장 흔합니다. 문제를 읽을 때 '지름'과 '반지름'에 동그라미를 치게 해 주세요. 냄비 뚜껑이나 접시의 둘레를 끈으로 재서 지름으로 나눠 보면 원주율이 약 3.14라는 것을 직접 확인할 수 있습니다."}$json$::jsonb,137) on conflict (slug) do nothing;
update public.topics set lesson_slug='m5-07' where band='5~6' and subject='수학' and name='원의 넓이';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e3-01','3~4','영어','알파벳과 낱말','알파벳 26글자로 어떻게 낱말을 만들까?','assets/img/l_e3-01.jpg',$json${"intro": "간판이나 과자 봉지에서 A, B, C 같은 글자를 본 적 있죠? 이 글자들이 모여서 영어 낱말이 돼요.", "sections": [{"heading": "알파벳은 모두 26글자예요", "paras": ["영어 글자를 알파벳이라고 해요. A부터 Z까지 모두 26글자가 있어요.", "알파벳 노래를 부르면 순서를 쉽게 외울 수 있어요. A, B, C, D, E, F, G~ 하고 따라 불러 봐요."], "example": "A B C D E F G … X Y Z (모두 26개)", "figure": "A부터 Z까지 알파벳 26글자가 무지개색 블록에 하나씩 적힌 그림"}, {"heading": "대문자와 소문자가 있어요", "paras": ["알파벳은 큰 글자(대문자)와 작은 글자(소문자)가 짝을 이뤄요. A와 a, B와 b는 같은 글자예요.", "문장의 첫 글자나 사람 이름의 첫 글자는 대문자로 써요. 나머지는 보통 소문자로 써요."], "example": "A-a, B-b, G-g, Q-q / 이름: Tom, Mina", "figure": "대문자 엄마 글자와 소문자 아기 글자가 손을 잡고 있는 그림"}, {"heading": "글자마다 소리가 있어요", "paras": ["알파벳은 이름과 소리가 달라요. b의 이름은 '비'지만, 낱말 속에서는 '브' 소리를 내요.", "첫소리를 알면 낱말을 읽기 쉬워요. apple은 a(애), ball은 b(브), cat은 c(크) 소리로 시작해요."], "example": "a-apple(사과), b-ball(공), c-cat(고양이), d-dog(개)", "figure": "apple, ball, cat, dog 그림 카드 아래 첫 글자가 크게 강조된 모습"}, {"heading": "글자를 모으면 낱말이 돼요", "paras": ["c, a, t 세 글자를 차례로 붙이면 cat(고양이)이 돼요. 소리를 하나씩 이어 읽으면 '크-애-트, 캣!'이 돼요.", "글자 하나만 바꿔도 다른 낱말이 돼요. cat의 c를 h로 바꾸면 hat(모자)이 돼요."], "example": "c+a+t = cat → h+a+t = hat", "figure": "글자 블록 c, a, t를 이어 붙여 고양이 그림이 나타나는 장면"}], "keywords": [{"word": "알파벳", "meaning": "영어를 쓰는 글자. A부터 Z까지 26개"}, {"word": "대문자", "meaning": "A, B, C처럼 크게 쓰는 글자"}, {"word": "소문자", "meaning": "a, b, c처럼 작게 쓰는 글자"}, {"word": "낱말", "meaning": "뜻을 가진 말 한 덩어리. 예: cat, dog"}], "expressions": [{"en": "apple", "ko": "사과", "note": "a로 시작해요"}, {"en": "ball", "ko": "공", "note": "b로 시작해요"}, {"en": "cat", "ko": "고양이", "note": "c로 시작해요"}, {"en": "dog", "ko": "개", "note": "d로 시작해요"}, {"en": "egg", "ko": "달걀", "note": "e로 시작해요"}, {"en": "What's this?", "ko": "이것은 뭐예요?", "note": "물건 이름을 물을 때"}, {"en": "It's a cat.", "ko": "그것은 고양이예요.", "note": "물건 이름을 알려 줄 때"}], "quiz": [{"q": "알파벳은 모두 몇 글자일까요?", "choices": ["24글자", "25글자", "26글자", "28글자"], "answer": 2, "explain": "영어 알파벳은 A부터 Z까지 모두 26글자예요."}, {"q": "대문자 G와 짝이 되는 소문자는?", "choices": ["q", "g", "j", "p"], "answer": 1, "explain": "G의 소문자는 g예요. q, j, p와 모양이 비슷하니 꼬리 방향을 잘 봐요."}, {"q": "'공'을 뜻하는 낱말은 무엇일까요?", "choices": ["ball", "bag", "egg", "dog"], "answer": 0, "explain": "ball은 공이에요. b 소리 '브'로 시작해요."}, {"q": "cat의 첫 글자를 h로 바꾸면 무슨 낱말이 될까요?", "choices": ["hot", "hen", "hit", "hat"], "answer": 3, "explain": "h+a+t는 hat(모자)이에요. 글자 하나로 뜻이 달라져요."}, {"q": "사과 그림을 보고 \"What's this?\"라고 물으면 알맞은 대답은?", "choices": ["It's an egg.", "It's an apple.", "It's a dog.", "I'm fine."], "answer": 1, "explain": "사과는 apple이니까 It's an apple.이라고 대답해요."}], "summary": ["영어 알파벳은 A부터 Z까지 26글자이고 대문자와 소문자가 있어요.", "알파벳은 이름과 낱말 속 소리가 달라요(b는 '브' 소리).", "글자의 소리를 차례로 이어 읽으면 낱말이 되고, 한 글자만 바꿔도 다른 낱말이 돼요."], "parent_tip": "부모님께: 아이들은 b와 d, p와 q처럼 좌우가 뒤집힌 소문자를 자주 헷갈립니다. 집 안 물건을 가리키며 \"이건 무슨 소리로 시작할까?\"라고 첫소리 놀이를 해 보세요. 알파벳의 이름(비)과 소리(브)를 구분해 주면 읽기가 훨씬 수월해집니다."}$json$::jsonb,61) on conflict (slug) do nothing;
update public.topics set lesson_slug='e3-01' where band='3~4' and subject='영어' and name='알파벳과 낱말';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e3-02','3~4','영어','물건 사고팔기','가게에서 영어로 물건을 사려면 뭐라고 할까?','assets/img/l_e3-02.jpg',$json${"intro": "문구점에서 연필을 사고 싶을 때, 영어로는 어떻게 말할까요? 가게 놀이를 하듯 같이 배워 봐요.", "sections": [{"heading": "갖고 싶은 물건 말하기", "paras": ["가게에 들어가면 점원이 \"Can I help you?(도와 드릴까요?)\"라고 물어요.", "사고 싶은 물건이 있으면 \"I want a pencil.(연필을 사고 싶어요.)\"처럼 I want 뒤에 물건 이름을 붙여요."], "example": "Can I help you? - I want a pencil.", "figure": "문구점 계산대 앞에서 아이가 연필을 가리키고 점원이 웃는 그림"}, {"heading": "값 물어보기", "paras": ["물건값이 궁금하면 \"How much is it?(그것은 얼마예요?)\"라고 물어요.", "점원은 \"It's 500 won.(500원이에요.)\"처럼 It's 뒤에 값을 말해 줘요. 100은 one hundred, 1000은 one thousand라고 읽어요."], "example": "How much is it? - It's 1,000 won.", "figure": "가격표에 1,000 won이라고 적힌 공책 그림"}, {"heading": "물건 주고받으며 인사하기", "paras": ["물건을 건넬 때는 \"Here you are.(여기 있어요.)\"라고 말해요.", "받은 사람은 \"Thank you.(고마워요.)\"라고 하고, 상대는 \"You're welcome.(천만에요.)\"라고 대답해요."], "example": "Here you are. - Thank you. - You're welcome.", "figure": "점원이 공책을 건네고 아이가 돈을 내는 모습"}], "keywords": [{"word": "want", "meaning": "원하다, 갖고 싶다"}, {"word": "How much", "meaning": "얼마"}, {"word": "won", "meaning": "우리나라 돈 단위 '원'"}, {"word": "Here you are.", "meaning": "물건을 건넬 때 하는 말 '여기 있어요'"}], "expressions": [{"en": "Can I help you?", "ko": "도와 드릴까요?", "note": "점원이 손님에게"}, {"en": "I want a pencil.", "ko": "연필을 사고 싶어요.", "note": "갖고 싶은 물건 말하기"}, {"en": "How much is it?", "ko": "그것은 얼마예요?", "note": "값을 물을 때"}, {"en": "It's 500 won.", "ko": "500원이에요.", "note": "값을 알려 줄 때"}, {"en": "Here you are.", "ko": "여기 있어요.", "note": "물건이나 돈을 건넬 때"}, {"en": "Thank you.", "ko": "고마워요."}, {"en": "You're welcome.", "ko": "천만에요.", "note": "고맙다는 말에 대답할 때"}], "quiz": [{"q": "물건값을 물어볼 때 쓰는 말은?", "choices": ["How are you?", "How much is it?", "What's this?", "Can I help you?"], "answer": 1, "explain": "How much is it?은 '얼마예요?'라는 뜻이에요."}, {"q": "\"Can I help you?\"에 알맞은 대답은?", "choices": ["I want an eraser.", "It's sunny.", "I'm ten years old.", "Goodbye."], "answer": 0, "explain": "도와 드릴까 묻는 말에는 사고 싶은 물건을 I want ~.로 말해요."}, {"q": "물건을 건네주면서 하는 말은?", "choices": ["You're welcome.", "Here you are.", "How much?", "Nice to meet you."], "answer": 1, "explain": "Here you are.는 '여기 있어요'라는 뜻으로 물건을 건넬 때 써요."}, {"q": "\"It's 1,000 won.\"의 뜻은?", "choices": ["100원이에요.", "10원이에요.", "1,000원이에요.", "10,000원이에요."], "answer": 2, "explain": "one thousand(1,000)이니까 1,000원이에요."}, {"q": "\"Thank you.\"에 대한 대답으로 알맞은 것은?", "choices": ["Here you are.", "I want a ball.", "How much is it?", "You're welcome."], "answer": 3, "explain": "고맙다는 말에는 You're welcome.(천만에요.)로 대답해요."}], "summary": ["점원은 Can I help you?로 묻고, 손님은 I want ~.로 사고 싶은 것을 말해요.", "값은 How much is it?으로 묻고 It's ~ won.으로 대답해요.", "물건을 건넬 때는 Here you are., 고마울 땐 Thank you.라고 해요."], "parent_tip": "부모님께: 집에 있는 물건에 가격표를 붙여 가게 놀이를 해 보시면 표현이 금방 익숙해집니다. 아이들은 100(one hundred)과 1,000(one thousand)을 헷갈리기 쉬우니 숫자를 바꿔 가며 물어봐 주세요. 아이가 점원 역할도 해 보게 하면 묻는 말과 대답을 모두 연습할 수 있습니다."}$json$::jsonb,62) on conflict (slug) do nothing;
update public.topics set lesson_slug='e3-02' where band='3~4' and subject='영어' and name='물건 사고팔기';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e3-03','3~4','영어','가족 소개하기','우리 가족을 영어로 소개해 볼까?','assets/img/l_e3-03.jpg',$json${"intro": "친구에게 가족사진을 보여 주며 \"우리 아빠야!\"라고 말해 본 적 있나요? 영어로도 똑같이 소개할 수 있어요.", "sections": [{"heading": "가족을 부르는 말", "paras": ["아빠는 father 또는 dad, 엄마는 mother 또는 mom이라고 해요.", "남자 형제는 brother, 여자 형제는 sister예요. 영어에서는 형·오빠·남동생을 모두 brother라고 불러요. 할아버지는 grandfather, 할머니는 grandmother예요."], "example": "dad(아빠), mom(엄마), brother(남자 형제), sister(여자 형제)", "figure": "할아버지, 할머니, 아빠, 엄마, 형, 여동생이 함께 있는 가족 그림에 영어 이름표"}, {"heading": "This is my ~ 로 소개해요", "paras": ["가족을 소개할 때는 \"This is my mom.(이분은 우리 엄마야.)\"처럼 This is my 뒤에 가족 이름을 붙여요.", "my는 '나의'라는 뜻이에요. 우리말로는 '우리 엄마'라고 하지만 영어에서는 my mom이라고 해요."], "example": "This is my brother. (이 아이는 우리 형이야.)", "figure": "아이가 가족사진을 가리키며 친구에게 소개하는 장면"}, {"heading": "누구인지 묻고 답하기", "paras": ["사진 속 사람이 누구인지 궁금하면 \"Who is he?(그는 누구야?)\" 또는 \"Who is she?(그녀는 누구야?)\"라고 물어요.", "남자는 he, 여자는 she를 써요. 대답은 \"He is my dad.\"처럼 해요."], "example": "Who is she? - She is my grandmother.", "figure": "사진 액자 속 할머니를 가리키는 두 친구 그림"}], "keywords": [{"word": "family", "meaning": "가족"}, {"word": "brother", "meaning": "남자 형제(형, 오빠, 남동생)"}, {"word": "sister", "meaning": "여자 형제(누나, 언니, 여동생)"}, {"word": "he / she", "meaning": "그 남자 / 그 여자"}, {"word": "my", "meaning": "나의, 우리"}], "expressions": [{"en": "This is my mom.", "ko": "이분은 우리 엄마야.", "note": "가족을 소개할 때"}, {"en": "This is my brother.", "ko": "이 아이는 우리 형(오빠, 남동생)이야."}, {"en": "Who is he?", "ko": "그는 누구야?", "note": "남자에 대해 물을 때"}, {"en": "Who is she?", "ko": "그녀는 누구야?", "note": "여자에 대해 물을 때"}, {"en": "He is my dad.", "ko": "그는 우리 아빠야."}, {"en": "She is my sister.", "ko": "그녀는 우리 언니(누나, 여동생)야."}, {"en": "I love my family.", "ko": "나는 우리 가족을 사랑해."}], "quiz": [{"q": "'할머니'를 영어로 하면?", "choices": ["grandfather", "mother", "grandmother", "sister"], "answer": 2, "explain": "할머니는 grandmother, 할아버지는 grandfather예요."}, {"q": "아빠를 친구에게 소개할 때 알맞은 말은?", "choices": ["This is my dad.", "Who is he?", "I'm dad.", "She is my dad."], "answer": 0, "explain": "This is my ~.로 소개해요. 아빠는 남자이니 She를 쓰면 안 돼요."}, {"q": "\"Who is she?\"에 알맞은 대답은?", "choices": ["He is my brother.", "She is my mom.", "It's a pencil.", "I'm fine."], "answer": 1, "explain": "she(그녀)를 물었으니 She is ~.로 대답해요."}, {"q": "brother가 가리킬 수 없는 사람은?", "choices": ["형", "오빠", "남동생", "언니"], "answer": 3, "explain": "brother는 남자 형제예요. 언니는 sister예요."}, {"q": "\"I love my family.\"의 뜻은?", "choices": ["나는 우리 가족을 사랑해.", "나는 가족이 많아.", "이분은 우리 가족이야.", "우리 가족은 누구야?"], "answer": 0, "explain": "love는 '사랑하다', family는 '가족'이에요."}], "summary": ["가족은 dad, mom, brother, sister, grandfather, grandmother로 불러요.", "가족을 소개할 때는 This is my ~.라고 말해요.", "누구인지 물을 때 남자는 Who is he?, 여자는 Who is she?를 써요."], "parent_tip": "부모님께: 우리말과 달리 영어는 나이와 상관없이 brother, sister를 쓰기 때문에 아이가 \"형은 영어로 뭐야?\"라고 헷갈려할 수 있습니다. 가족사진을 함께 보며 \"Who is he?\"라고 묻고 아이가 He/She를 골라 대답하게 해 주세요."}$json$::jsonb,63) on conflict (slug) do nothing;
update public.topics set lesson_slug='e3-03' where band='3~4' and subject='영어' and name='가족 소개하기';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e3-04','3~4','영어','날씨 묻고 답하기','오늘 날씨는 영어로 어떻게 말할까?','assets/img/l_e3-04.jpg',$json${"intro": "아침에 창밖을 보며 \"오늘은 비가 오네!\" 하고 말하죠? 영어로도 날씨를 묻고 답할 수 있어요.", "sections": [{"heading": "날씨를 묻는 말", "paras": ["날씨가 궁금할 때는 \"How's the weather?(날씨가 어때?)\"라고 물어요.", "How's는 How is를 줄인 말이고, weather는 '날씨'라는 뜻이에요."], "example": "How's the weather today? (오늘 날씨 어때?)", "figure": "창문 밖을 바라보며 날씨를 궁금해하는 아이 그림"}, {"heading": "It's + 날씨로 대답해요", "paras": ["대답할 때는 It's 뒤에 날씨를 나타내는 말을 붙여요. 이때 It은 '그것'이라는 뜻이 아니라 날씨를 말할 때 쓰는 말이에요.", "맑으면 sunny, 비가 오면 rainy, 흐리면 cloudy, 눈이 오면 snowy, 바람이 불면 windy예요."], "example": "It's sunny. / It's rainy. / It's snowy.", "figure": "해, 비구름, 회색 구름, 눈송이, 바람 그림 아래 sunny, rainy, cloudy, snowy, windy 낱말 카드"}, {"heading": "덥고 추운 것도 말해요", "paras": ["기온을 말할 때도 It's를 써요. 더우면 hot, 추우면 cold, 따뜻하면 warm이에요.", "날씨에 맞게 \"Take your umbrella.(우산 가져가.)\"처럼 챙길 물건을 말해 줄 수도 있어요."], "example": "It's cold. Wear your coat. (추워. 외투 입어.)", "figure": "추운 날 외투와 목도리를 한 아이와 더운 날 반팔 입은 아이를 나란히 그린 그림"}], "keywords": [{"word": "weather", "meaning": "날씨"}, {"word": "sunny", "meaning": "해가 쨍쨍한, 맑은"}, {"word": "rainy", "meaning": "비가 오는"}, {"word": "cloudy", "meaning": "구름이 낀, 흐린"}, {"word": "snowy", "meaning": "눈이 오는"}, {"word": "windy", "meaning": "바람이 부는"}], "expressions": [{"en": "How's the weather?", "ko": "날씨가 어때?", "note": "날씨를 물을 때"}, {"en": "It's sunny.", "ko": "날씨가 맑아."}, {"en": "It's rainy.", "ko": "비가 와."}, {"en": "It's cloudy.", "ko": "흐려."}, {"en": "It's snowy.", "ko": "눈이 와."}, {"en": "It's hot.", "ko": "더워."}, {"en": "It's cold.", "ko": "추워."}, {"en": "Take your umbrella.", "ko": "우산 가져가.", "note": "비 오는 날 챙겨 줄 때"}], "quiz": [{"q": "날씨를 물을 때 쓰는 말은?", "choices": ["How old are you?", "How's the weather?", "How much is it?", "What's this?"], "answer": 1, "explain": "weather는 날씨예요. How's the weather?로 날씨를 물어요."}, {"q": "비가 내리는 그림에 알맞은 말은?", "choices": ["It's sunny.", "It's snowy.", "It's rainy.", "It's hot."], "answer": 2, "explain": "비가 오는 날씨는 rainy예요."}, {"q": "\"It's windy.\"의 뜻은?", "choices": ["바람이 불어.", "눈이 와.", "더워.", "맑아."], "answer": 0, "explain": "windy는 바람이 부는 날씨예요."}, {"q": "눈사람을 만드는 날의 날씨로 알맞은 것은?", "choices": ["It's hot.", "It's sunny and hot.", "It's rainy.", "It's snowy and cold."], "answer": 3, "explain": "눈사람은 눈이 오고 추운 날 만들어요. snowy and cold가 알맞아요."}, {"q": "\"It's rainy.\"라고 들었을 때 이어서 할 말로 알맞은 것은?", "choices": ["Take your umbrella.", "Wear your sunglasses.", "Let's make a snowman.", "Nice to meet you."], "answer": 0, "explain": "비가 오니 우산(umbrella)을 챙기라고 말해요."}], "summary": ["날씨는 How's the weather?로 물어요.", "대답은 It's 뒤에 sunny, rainy, cloudy, snowy, windy를 붙여요.", "더우면 It's hot., 추우면 It's cold.라고 해요."], "parent_tip": "부모님께: 아이들은 rain(비)과 rainy(비가 오는)처럼 -y가 붙는 차이를 자주 헷갈리니 \"It's 다음엔 y가 붙은 말!\"이라고 짚어 주세요. 매일 아침 창밖을 보며 \"How's the weather?\"라고 묻는 습관을 들이면 가장 자연스럽게 익힐 수 있습니다."}$json$::jsonb,64) on conflict (slug) do nothing;
update public.topics set lesson_slug='e3-04' where band='3~4' and subject='영어' and name='날씨 묻고 답하기';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e3-05','3~4','영어','색깔과 수','무지개 색깔과 숫자를 영어로 세어 볼까?','assets/img/l_e3-05.jpg',$json${"intro": "크레파스 상자에는 여러 가지 색이 있고, 사탕 봉지에는 사탕이 여러 개 있죠? 색깔과 수를 영어로 말해 봐요.", "sections": [{"heading": "여러 가지 색깔", "paras": ["빨강은 red, 노랑은 yellow, 파랑은 blue, 초록은 green이에요.", "주황은 orange, 보라는 purple, 분홍은 pink, 검정은 black, 하양은 white예요."], "example": "The apple is red. (사과는 빨간색이야.)", "figure": "크레파스 상자 속 색마다 영어 이름이 적힌 그림"}, {"heading": "색깔을 묻고 답하기", "paras": ["색깔을 물을 때는 \"What color is it?(그것은 무슨 색이야?)\"라고 해요.", "대답은 \"It's blue.(파란색이야.)\"처럼 It's 뒤에 색깔을 붙여요."], "example": "What color is it? - It's yellow.", "figure": "노란 바나나를 들고 색을 묻는 두 친구"}, {"heading": "1부터 20까지 세기", "paras": ["one(1), two(2), three(3), four(4), five(5), six(6), seven(7), eight(8), nine(9), ten(10)이에요.", "11은 eleven, 12는 twelve, 13부터 19까지는 thirteen, fourteen처럼 뒤에 -teen이 붙어요. 20은 twenty예요."], "example": "eleven(11), twelve(12), thirteen(13) … nineteen(19), twenty(20)", "figure": "1부터 20까지 숫자 카드가 줄지어 있는 그림"}, {"heading": "몇 개인지 묻고 답하기", "paras": ["개수를 물을 때는 \"How many apples?(사과가 몇 개야?)\"라고 해요. 둘 이상일 때는 apples처럼 낱말 끝에 s를 붙여요.", "대답은 \"Three apples.(사과 세 개.)\"처럼 숫자를 먼저 말해요."], "example": "How many balls? - Five balls.", "figure": "바구니 속 사과 세 개를 손가락으로 세는 아이"}], "keywords": [{"word": "color", "meaning": "색깔"}, {"word": "red / blue / yellow", "meaning": "빨강 / 파랑 / 노랑"}, {"word": "How many", "meaning": "몇 개"}, {"word": "-teen", "meaning": "13~19를 나타내는 숫자 뒤에 붙는 말"}, {"word": "-s", "meaning": "둘 이상일 때 낱말 끝에 붙는 말"}], "expressions": [{"en": "What color is it?", "ko": "그것은 무슨 색이야?", "note": "색깔을 물을 때"}, {"en": "It's red.", "ko": "빨간색이야."}, {"en": "How many apples?", "ko": "사과가 몇 개야?", "note": "개수를 물을 때"}, {"en": "Three apples.", "ko": "사과 세 개."}, {"en": "I like blue.", "ko": "나는 파란색이 좋아."}, {"en": "Let's count!", "ko": "같이 세어 보자!"}], "quiz": [{"q": "바나나는 무슨 색일까요?", "choices": ["It's purple.", "It's yellow.", "It's black.", "It's blue."], "answer": 1, "explain": "바나나는 노란색, yellow예요."}, {"q": "숫자 12를 영어로 하면?", "choices": ["twelve", "twenty", "two", "eleven"], "answer": 0, "explain": "12는 twelve예요. twenty는 20, eleven은 11이에요."}, {"q": "개수를 물을 때 쓰는 말은?", "choices": ["What color is it?", "How are you?", "How many pencils?", "Who is she?"], "answer": 2, "explain": "How many ~?는 '몇 개야?'라는 뜻이에요."}, {"q": "사과가 네 개 있어요. 알맞은 말은?", "choices": ["Four apple.", "Five apples.", "Fourteen apples.", "Four apples."], "answer": 3, "explain": "4는 four이고, 둘 이상이니 apples로 써요."}, {"q": "\"It's green.\"에 어울리는 것은?", "choices": ["나뭇잎", "눈", "까마귀", "딸기"], "answer": 0, "explain": "green은 초록색이에요. 나뭇잎이 초록색이에요."}], "summary": ["색깔은 What color is it?으로 묻고 It's ~.로 대답해요.", "13부터 19까지는 숫자 뒤에 -teen이 붙어요.", "개수는 How many ~?로 묻고, 둘 이상이면 낱말 끝에 s를 붙여요."], "parent_tip": "부모님께: thirteen(13)과 thirty(30), fourteen(14)과 forty(40)는 소리가 비슷해 헷갈리기 쉽습니다. 간식을 줄 때 \"How many?\"라고 묻고 아이가 영어로 세게 해 보세요. 색깔은 옷을 고를 때 \"What color is it?\"으로 매일 연습할 수 있습니다."}$json$::jsonb,65) on conflict (slug) do nothing;
update public.topics set lesson_slug='e3-05' where band='3~4' and subject='영어' and name='색깔과 수';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e3-06','3~4','영어','인사하기','처음 만난 친구에게 영어로 인사해 볼까?','assets/img/l_e3-06.jpg',$json${"intro": "새 학기에 처음 만난 친구에게 \"안녕, 내 이름은 ○○야!\"라고 말하죠? 영어로도 인사하고 이름을 소개해 봐요.", "sections": [{"heading": "만날 때와 헤어질 때 인사", "paras": ["만나면 \"Hello!\"나 \"Hi!\"라고 인사해요. 둘 다 '안녕!'이라는 뜻이에요.", "헤어질 때는 \"Goodbye!\"나 \"Bye!\" 또는 \"See you later.(나중에 봐.)\"라고 해요. 아침에는 \"Good morning.\"이라고 인사할 수도 있어요."], "example": "Hi, Mina! - Hello, Tom! / Goodbye! - See you!", "figure": "교문 앞에서 손을 흔들며 인사하는 두 아이"}, {"heading": "이름 묻고 소개하기", "paras": ["상대의 이름이 궁금하면 \"What's your name?(네 이름이 뭐야?)\"이라고 물어요.", "대답은 \"I'm Mina.\" 또는 \"My name is Mina.\"라고 해요. 둘 다 '나는 미나야'라는 뜻이에요."], "example": "What's your name? - My name is Jiho.", "figure": "이름표를 가슴에 단 아이가 자기소개하는 그림"}, {"heading": "반갑다고 말하기, 안부 묻기", "paras": ["처음 만났을 때는 \"Nice to meet you.(만나서 반가워.)\"라고 하고, 상대는 \"Nice to meet you, too.(나도 만나서 반가워.)\"라고 대답해요.", "아는 친구에게는 \"How are you?(어떻게 지내?)\"라고 안부를 물어요. \"I'm fine, thank you.(잘 지내, 고마워.)\"라고 대답해요."], "example": "How are you? - I'm good, thanks.", "figure": "악수하며 웃는 두 아이"}], "keywords": [{"word": "Hello / Hi", "meaning": "만났을 때 하는 인사 '안녕'"}, {"word": "Goodbye / Bye", "meaning": "헤어질 때 하는 인사 '잘 가'"}, {"word": "name", "meaning": "이름"}, {"word": "Nice to meet you.", "meaning": "처음 만나서 반갑다는 말"}], "expressions": [{"en": "Hello! / Hi!", "ko": "안녕!", "note": "만났을 때"}, {"en": "Good morning.", "ko": "좋은 아침이야.", "note": "아침 인사"}, {"en": "What's your name?", "ko": "네 이름이 뭐야?"}, {"en": "I'm Mina.", "ko": "나는 미나야."}, {"en": "Nice to meet you.", "ko": "만나서 반가워.", "note": "처음 만났을 때"}, {"en": "Nice to meet you, too.", "ko": "나도 만나서 반가워."}, {"en": "How are you?", "ko": "어떻게 지내?"}, {"en": "Goodbye. See you later.", "ko": "잘 가. 나중에 봐.", "note": "헤어질 때"}], "quiz": [{"q": "헤어질 때 하는 인사는?", "choices": ["Hello!", "Nice to meet you.", "Goodbye!", "Good morning."], "answer": 2, "explain": "Goodbye는 헤어질 때 쓰는 인사예요."}, {"q": "\"What's your name?\"에 알맞은 대답은?", "choices": ["I'm fine.", "My name is Jiho.", "It's sunny.", "Goodbye."], "answer": 1, "explain": "이름을 물었으니 My name is ~. 또는 I'm ~.로 대답해요."}, {"q": "\"Nice to meet you.\"에 알맞은 대답은?", "choices": ["Nice to meet you, too.", "I'm ten.", "See you.", "It's red."], "answer": 0, "explain": "'나도 만나서 반가워'는 Nice to meet you, too.예요."}, {"q": "\"How are you?\"의 뜻은?", "choices": ["너는 몇 살이니?", "네 이름이 뭐야?", "이건 뭐야?", "어떻게 지내?"], "answer": 3, "explain": "How are you?는 안부를 묻는 말이에요."}, {"q": "아침에 선생님을 만났을 때 알맞은 인사는?", "choices": ["Good morning.", "Goodbye.", "See you later.", "You're welcome."], "answer": 0, "explain": "아침 인사는 Good morning.이에요."}], "summary": ["만날 때는 Hello/Hi, 헤어질 때는 Goodbye/Bye라고 해요.", "이름은 What's your name?으로 묻고 I'm ~./My name is ~.로 대답해요.", "처음 만나면 Nice to meet you., 안부는 How are you?로 물어요."], "parent_tip": "부모님께: 아이들은 \"How are you?\"에 늘 \"I'm fine, thank you.\"만 외워 쓰는 경우가 많습니다. I'm good. / I'm great. / I'm so-so.처럼 다양한 대답도 있다고 알려 주세요. 등하교 때 영어로 인사를 주고받는 것만으로도 충분한 연습이 됩니다."}$json$::jsonb,66) on conflict (slug) do nothing;
update public.topics set lesson_slug='e3-06' where band='3~4' and subject='영어' and name='인사하기';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e3-07','3~4','영어','감정 말하기','내 기분을 영어로 어떻게 말할까?','assets/img/l_e3-07.jpg',$json${"intro": "시험을 잘 봐서 기쁠 때도, 친구와 다퉈서 속상할 때도 있죠? 내 기분을 영어로 말해 봐요.", "sections": [{"heading": "기분을 나타내는 말", "paras": ["기쁘면 happy, 슬프면 sad, 화가 나면 angry, 피곤하면 tired예요.", "배가 고프면 hungry, 졸리면 sleepy라고 해요. 기분이나 몸 상태를 나타내는 말이에요."], "example": "happy(기쁜), sad(슬픈), angry(화난), tired(피곤한)", "figure": "웃는 얼굴, 우는 얼굴, 화난 얼굴, 하품하는 얼굴 그림 아래 영어 낱말"}, {"heading": "I'm + 기분 으로 말해요", "paras": ["내 기분을 말할 때는 \"I'm happy.(나는 기뻐.)\"처럼 I'm 뒤에 기분을 나타내는 말을 붙여요. I'm은 I am을 줄인 말이에요.", "기분을 더 크게 말하고 싶으면 very를 넣어요. \"I'm very happy.(나는 정말 기뻐.)\""], "example": "I'm sad. / I'm very hungry.", "figure": "아이가 'I'm happy!'라고 말풍선을 띄우는 그림"}, {"heading": "친구의 기분 묻기", "paras": ["친구의 기분이 궁금하면 \"Are you happy?(너 기분 좋아?)\"라고 물을 수 있어요.", "맞으면 \"Yes, I am.\", 아니면 \"No, I'm not.\"이라고 대답해요. 슬퍼 보이는 친구에게는 \"What's wrong?(무슨 일 있어?)\"이라고 물어봐 줘요."], "example": "Are you tired? - Yes, I am. / No, I'm not.", "figure": "축 처진 친구에게 다가가 말을 거는 아이"}], "keywords": [{"word": "happy", "meaning": "기쁜, 행복한"}, {"word": "sad", "meaning": "슬픈"}, {"word": "angry", "meaning": "화난"}, {"word": "tired", "meaning": "피곤한"}, {"word": "hungry", "meaning": "배고픈"}], "expressions": [{"en": "I'm happy.", "ko": "나는 기뻐."}, {"en": "I'm sad.", "ko": "나는 슬퍼."}, {"en": "I'm hungry.", "ko": "나는 배고파."}, {"en": "Are you tired?", "ko": "너 피곤하니?", "note": "친구의 기분이나 상태를 물을 때"}, {"en": "Yes, I am.", "ko": "응, 그래."}, {"en": "No, I'm not.", "ko": "아니, 그렇지 않아."}, {"en": "What's wrong?", "ko": "무슨 일 있어?", "note": "속상해 보이는 친구에게"}], "quiz": [{"q": "'나는 슬퍼.'를 영어로 하면?", "choices": ["I'm happy.", "I'm sad.", "I'm hungry.", "I'm angry."], "answer": 1, "explain": "sad는 '슬픈'이에요."}, {"q": "점심 먹기 전 배가 꼬르륵거릴 때 알맞은 말은?", "choices": ["I'm sleepy.", "I'm angry.", "I'm hungry.", "I'm happy."], "answer": 2, "explain": "배가 고플 때는 hungry를 써요."}, {"q": "\"Are you tired?\"에 '아니'라고 대답할 때 알맞은 말은?", "choices": ["No, I'm not.", "Yes, I am.", "No, you are.", "I'm tired."], "answer": 0, "explain": "아니라고 할 때는 No, I'm not.이라고 해요."}, {"q": "\"I'm very happy.\"의 뜻은?", "choices": ["나는 조금 슬퍼.", "나는 배고파.", "너는 기뻐.", "나는 정말 기뻐."], "answer": 3, "explain": "very는 '정말, 매우'라는 뜻이에요."}, {"q": "친구가 울고 있을 때 건넬 말로 알맞은 것은?", "choices": ["Nice to meet you.", "What's wrong?", "How much is it?", "It's sunny."], "answer": 1, "explain": "What's wrong?은 '무슨 일 있어?'라는 뜻이에요."}], "summary": ["기분을 나타내는 말에는 happy, sad, angry, tired, hungry 등이 있어요.", "내 기분은 I'm + 기분으로 말해요.", "친구에게는 Are you ~?로 묻고 Yes, I am. / No, I'm not.으로 대답해요."], "parent_tip": "부모님께: 아이들은 \"I happy.\"처럼 am을 빼먹는 실수를 자주 합니다. \"I'm은 꼭 붙어 다녀요\"라고 짚어 주세요. 하루를 마무리할 때 \"How do you feel today?\"라고 묻고 아이가 영어로 기분을 말하게 하면 감정 표현 연습에도 좋습니다."}$json$::jsonb,67) on conflict (slug) do nothing;
update public.topics set lesson_slug='e3-07' where band='3~4' and subject='영어' and name='감정 말하기';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e3-08','3~4','영어','좋아하는 것 말하기','내가 좋아하는 것을 영어로 말해 볼까?','assets/img/l_e3-08.jpg',$json${"intro": "좋아하는 과일, 좋아하는 운동, 좋아하는 동물이 있나요? 영어로 좋아하는 것을 말하고 친구에게도 물어봐요.", "sections": [{"heading": "I like ~ 로 좋아하는 것 말하기", "paras": ["좋아하는 것을 말할 때는 \"I like apples.(나는 사과를 좋아해.)\"처럼 I like 뒤에 좋아하는 것을 붙여요.", "과일이나 동물처럼 셀 수 있는 것은 보통 apples, dogs처럼 s를 붙여서 말해요."], "example": "I like bananas. / I like soccer.", "figure": "아이가 사과와 축구공을 안고 웃는 그림"}, {"heading": "싫어하는 것 말하기", "paras": ["좋아하지 않을 때는 \"I don't like carrots.(나는 당근을 좋아하지 않아.)\"라고 해요.", "don't는 do not을 줄인 말로 '~하지 않다'라는 뜻이에요."], "example": "I don't like snakes. (나는 뱀을 좋아하지 않아.)", "figure": "당근 앞에서 고개를 젓는 아이"}, {"heading": "친구에게 묻고 답하기", "paras": ["\"Do you like pizza?(너 피자 좋아해?)\"처럼 Do you like로 물어요.", "좋아하면 \"Yes, I do.\", 좋아하지 않으면 \"No, I don't.\"라고 대답해요. 무엇을 좋아하는지 물을 때는 \"What do you like?\"라고 해요."], "example": "Do you like cats? - Yes, I do. / No, I don't.", "figure": "두 친구가 피자를 사이에 두고 이야기하는 장면"}], "keywords": [{"word": "like", "meaning": "좋아하다"}, {"word": "don't", "meaning": "~하지 않다(do not의 줄임말)"}, {"word": "Do you ~?", "meaning": "너는 ~하니?하고 묻는 말"}, {"word": "favorite", "meaning": "가장 좋아하는"}], "expressions": [{"en": "I like apples.", "ko": "나는 사과를 좋아해."}, {"en": "I don't like carrots.", "ko": "나는 당근을 좋아하지 않아."}, {"en": "Do you like pizza?", "ko": "너 피자 좋아해?", "note": "친구에게 물을 때"}, {"en": "Yes, I do.", "ko": "응, 좋아해."}, {"en": "No, I don't.", "ko": "아니, 좋아하지 않아."}, {"en": "What do you like?", "ko": "너는 무엇을 좋아해?"}, {"en": "My favorite color is blue.", "ko": "내가 가장 좋아하는 색은 파란색이야."}], "quiz": [{"q": "'나는 고양이를 좋아해.'를 영어로 하면?", "choices": ["I like cats.", "I don't like cats.", "Do you like cats?", "I'm a cat."], "answer": 0, "explain": "좋아할 때는 I like ~.로 말해요."}, {"q": "\"Do you like soccer?\"에 '응'이라고 대답할 때는?", "choices": ["No, I don't.", "Yes, I am.", "Yes, I do.", "I like."], "answer": 2, "explain": "Do you ~?로 물으면 Yes, I do.로 대답해요."}, {"q": "\"I don't like milk.\"의 뜻은?", "choices": ["나는 우유를 좋아해.", "너는 우유를 좋아하니?", "우유가 몇 개야?", "나는 우유를 좋아하지 않아."], "answer": 3, "explain": "don't like는 '좋아하지 않다'예요."}, {"q": "친구가 무엇을 좋아하는지 물을 때 알맞은 말은?", "choices": ["What's your name?", "What do you like?", "How are you?", "What color is it?"], "answer": 1, "explain": "What do you like?는 '너는 무엇을 좋아해?'라는 뜻이에요."}, {"q": "\"My favorite fruit is grapes.\"에서 favorite의 뜻은?", "choices": ["가장 좋아하는", "싫어하는", "맛있는", "작은"], "answer": 0, "explain": "favorite은 '가장 좋아하는'이라는 뜻이에요."}], "summary": ["좋아하는 것은 I like ~., 싫어하는 것은 I don't like ~.로 말해요.", "친구에게는 Do you like ~?로 물어요.", "대답은 Yes, I do. 또는 No, I don't.로 해요."], "parent_tip": "부모님께: \"Do you like ~?\"에 \"Yes, I am.\"이라고 잘못 대답하는 경우가 많습니다. Are you로 물으면 am, Do you로 물으면 do로 대답한다고 묶어서 알려 주세요. 식사 시간에 반찬을 가리키며 \"Do you like it?\"이라고 물어보면 자연스럽게 연습할 수 있습니다."}$json$::jsonb,68) on conflict (slug) do nothing;
update public.topics set lesson_slug='e3-08' where band='3~4' and subject='영어' and name='좋아하는 것 말하기';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e5-01','5~6','영어','길 묻고 안내하기','길을 잃었을 때 영어로 길을 물어볼까?','assets/img/l_e5-01.jpg',$json${"intro": "외국인 관광객이 \"Where is the bank?\"라고 묻는다면 어떻게 알려 줄까요? 길을 묻고 안내하는 표현을 배워 봐요.", "sections": [{"heading": "장소 묻기", "paras": ["가고 싶은 곳이 어디인지 물을 때는 \"Where is the library?(도서관이 어디에 있나요?)\"처럼 Where is 뒤에 장소를 붙여요.", "처음 보는 사람에게 물을 때는 \"Excuse me.(실례합니다.)\"로 먼저 말을 거는 것이 예의예요."], "example": "Excuse me. Where is the post office?", "figure": "길에서 지도를 들고 지나가는 사람에게 묻는 여행자"}, {"heading": "방향 알려 주기", "paras": ["\"Go straight.(곧장 가세요.)\", \"Turn left.(왼쪽으로 도세요.)\", \"Turn right.(오른쪽으로 도세요.)\"로 방향을 알려 줘요.", "몇 블록을 가야 하는지 말할 때는 \"Go straight two blocks.(두 블록 곧장 가세요.)\"처럼 말해요."], "example": "Go straight one block and turn right.", "figure": "갈림길에 직진, 좌회전, 우회전 화살표가 그려진 지도"}, {"heading": "위치 설명하기", "paras": ["건물의 위치를 말할 때는 next to(~ 옆에), across from(~ 건너편에), between A and B(A와 B 사이에)를 써요.", "\"It's next to the bank.(그것은 은행 옆에 있어요.)\"처럼 It's 뒤에 붙여 말해요. \"It's on your left.(왼쪽에 있어요.)\"라고 할 수도 있어요."], "example": "It's between the school and the park.", "figure": "학교와 공원 사이에 있는 도서관, 은행 옆의 우체국이 표시된 마을 지도"}], "keywords": [{"word": "Where", "meaning": "어디"}, {"word": "straight", "meaning": "곧장, 똑바로"}, {"word": "turn left / right", "meaning": "왼쪽 / 오른쪽으로 돌다"}, {"word": "next to", "meaning": "~ 옆에"}, {"word": "across from", "meaning": "~ 건너편에"}, {"word": "between", "meaning": "~ 사이에"}], "expressions": [{"en": "Excuse me. Where is the library?", "ko": "실례합니다. 도서관이 어디에 있나요?", "note": "길을 물을 때"}, {"en": "Go straight.", "ko": "곧장 가세요."}, {"en": "Turn left.", "ko": "왼쪽으로 도세요."}, {"en": "Turn right.", "ko": "오른쪽으로 도세요."}, {"en": "It's next to the bank.", "ko": "은행 옆에 있어요."}, {"en": "It's across from the park.", "ko": "공원 건너편에 있어요."}, {"en": "It's on your left.", "ko": "왼쪽에 있어요."}, {"en": "Thank you for your help.", "ko": "도와줘서 고마워요."}], "quiz": [{"q": "길을 물어볼 때 먼저 하는 말로 알맞은 것은?", "choices": ["Excuse me.", "Goodbye.", "You're welcome.", "Here you are."], "answer": 0, "explain": "모르는 사람에게 말을 걸 때는 Excuse me.라고 해요."}, {"q": "\"Turn right.\"의 뜻은?", "choices": ["왼쪽으로 도세요.", "오른쪽으로 도세요.", "곧장 가세요.", "멈추세요."], "answer": 1, "explain": "right는 오른쪽, left는 왼쪽이에요."}, {"q": "빵집이 은행과 서점 사이에 있어요. 알맞은 말은?", "choices": ["It's next to the bank.", "It's across from the bookstore.", "It's between the bank and the bookstore.", "It's on the bank."], "answer": 2, "explain": "A와 B 사이는 between A and B예요."}, {"q": "\"Where is the hospital?\"에 대한 대답으로 알맞은 것은?", "choices": ["It's sunny.", "I'm fine.", "It's 500 won.", "Go straight one block."], "answer": 3, "explain": "장소를 물었으니 가는 방법을 알려 줘야 해요."}, {"q": "\"across from\"의 뜻은?", "choices": ["~ 건너편에", "~ 옆에", "~ 안에", "~ 위에"], "answer": 0, "explain": "across from은 길 건너 마주 보는 곳, '~ 건너편에'예요."}], "summary": ["장소는 Excuse me. Where is ~?로 물어요.", "방향은 Go straight. / Turn left. / Turn right.로 알려 줘요.", "위치는 next to, across from, between으로 설명해요."], "parent_tip": "부모님께: 아이들은 left와 right를 자주 헷갈립니다. 왼손으로 L 모양을 만들어 보는 방법을 알려 주세요. 동네 지도를 펴 놓고 \"Where is the bakery?\"라고 물으며 아이가 영어로 길 안내를 해 보게 하면 좋습니다."}$json$::jsonb,161) on conflict (slug) do nothing;
update public.topics set lesson_slug='e5-01' where band='5~6' and subject='영어' and name='길 묻고 안내하기';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e5-02','5~6','영어','하루 일과와 시각','몇 시에 일어나? 하루 일과를 영어로 말해 볼까?','assets/img/l_e5-02.jpg',$json${"intro": "아침에 일어나서 학교에 가고, 저녁에 잠자리에 들기까지 하루가 바쁘죠? 시각과 함께 하루 일과를 영어로 말해 봐요.", "sections": [{"heading": "시각 묻고 답하기", "paras": ["지금 몇 시인지 물을 때는 \"What time is it?(몇 시야?)\"이라고 해요.", "대답은 \"It's seven.(7시야.)\"처럼 It's 뒤에 시각을 말해요. 7시 30분은 \"It's seven thirty.\"처럼 시와 분을 차례로 읽어요."], "example": "What time is it? - It's eight thirty. (8시 30분이야.)", "figure": "8시 30분을 가리키는 벽시계 그림"}, {"heading": "하루 일과를 나타내는 말", "paras": ["get up(일어나다), eat breakfast(아침을 먹다), go to school(학교에 가다), do my homework(숙제를 하다), go to bed(잠자리에 들다) 같은 말이 있어요.", "이런 말을 순서대로 이어 말하면 나의 하루를 소개할 수 있어요."], "example": "get up → eat breakfast → go to school → do my homework → go to bed", "figure": "아침부터 밤까지 일과를 시계와 함께 보여 주는 만화 칸 그림"}, {"heading": "몇 시에 하는지 말하기", "paras": ["\"I get up at 7.(나는 7시에 일어나.)\"처럼 시각 앞에는 at을 붙여요.", "친구에게 물을 때는 \"What time do you get up?(너는 몇 시에 일어나?)\"이라고 해요. at은 '~시에'라는 뜻이에요."], "example": "What time do you go to bed? - I go to bed at 10.", "figure": "잠옷을 입고 10시를 가리키는 시계 옆에 선 아이"}], "keywords": [{"word": "What time", "meaning": "몇 시"}, {"word": "at", "meaning": "(시각 앞에서) ~시에"}, {"word": "get up", "meaning": "일어나다"}, {"word": "go to bed", "meaning": "잠자리에 들다"}, {"word": "thirty", "meaning": "30, 시각에서는 30분"}], "expressions": [{"en": "What time is it?", "ko": "몇 시야?", "note": "지금 시각을 물을 때"}, {"en": "It's seven thirty.", "ko": "7시 30분이야."}, {"en": "What time do you get up?", "ko": "너는 몇 시에 일어나?", "note": "일과를 물을 때"}, {"en": "I get up at 7.", "ko": "나는 7시에 일어나."}, {"en": "I go to school at 8:30.", "ko": "나는 8시 30분에 학교에 가."}, {"en": "I go to bed at 10.", "ko": "나는 10시에 잠자리에 들어."}, {"en": "It's time for lunch.", "ko": "점심 먹을 시간이야."}], "quiz": [{"q": "지금 시각을 물을 때 알맞은 말은?", "choices": ["How old are you?", "What time is it?", "What day is it?", "How are you?"], "answer": 1, "explain": "What time is it?은 '몇 시야?'라는 뜻이에요."}, {"q": "시계가 9시 30분을 가리켜요. 알맞은 말은?", "choices": ["It's nine thirty.", "It's three nine.", "It's nine thirteen.", "It's thirty nine."], "answer": 0, "explain": "시를 먼저, 분을 나중에 읽어요. 9시 30분은 nine thirty예요."}, {"q": "'나는 7시에 일어나.'를 바르게 쓴 것은?", "choices": ["I go to bed at 7.", "I get up in 7.", "I get up at 7.", "I eat breakfast at 7."], "answer": 2, "explain": "일어나다는 get up, 시각 앞에는 at을 써요."}, {"q": "\"What time do you go to bed?\"에 알맞은 대답은?", "choices": ["It's sunny.", "I'm tired.", "I like bed.", "I go to bed at 9:30."], "answer": 3, "explain": "몇 시에 자는지 물었으니 시각을 넣어 대답해요."}, {"q": "\"It's time for lunch.\"의 뜻은?", "choices": ["점심 먹을 시간이야.", "점심을 먹었어.", "점심이 맛있어.", "점심은 몇 시야?"], "answer": 0, "explain": "It's time for ~.는 '~할 시간이야'라는 뜻이에요."}], "summary": ["시각은 What time is it?으로 묻고 It's ~.로 대답해요.", "몇 시에 무엇을 하는지는 I get up at 7.처럼 at을 써서 말해요.", "친구의 일과는 What time do you ~?로 물어요."], "parent_tip": "부모님께: 아이들은 thirteen(13)과 thirty(30)를 헷갈려 시각을 잘못 듣는 경우가 많습니다. 아날로그 시계를 보며 \"What time is it?\"이라고 자주 물어 주세요. 아이의 실제 하루 일과표를 영어로 만들어 냉장고에 붙여 두는 것도 좋은 방법입니다."}$json$::jsonb,162) on conflict (slug) do nothing;
update public.topics set lesson_slug='e5-02' where band='5~6' and subject='영어' and name='하루 일과와 시각';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e5-03','5~6','영어','문장 만들기','영어 문장은 어떤 순서로 만들까?','assets/img/l_e5-03.jpg',$json${"intro": "우리말은 \"나는 사과를 먹어\"라고 하지만 영어는 \"I eat an apple\"이라고 해요. 순서가 다르죠? 영어 문장을 만드는 규칙을 알아봐요.", "sections": [{"heading": "영어 문장의 기본 순서", "paras": ["영어 문장은 보통 '누가(주어) + 한다(동사) + 무엇을' 순서로 만들어요.", "우리말은 '무엇을'이 동사 앞에 오지만, 영어는 동사가 먼저 와요. I(나는) + eat(먹는다) + an apple(사과를)이에요."], "example": "I + play + soccer. (나는 축구를 한다.)", "figure": "'누가 → 한다 → 무엇을' 블록 세 개가 기차처럼 이어진 그림"}, {"heading": "문장을 쓰는 규칙", "paras": ["문장의 첫 글자는 대문자로 쓰고, 문장이 끝나면 마침표(.)를 찍어요.", "'나'를 뜻하는 I는 문장 어디에 있어도 항상 대문자로 써요. 낱말과 낱말 사이는 한 칸 띄어 써요."], "example": "my dog is cute → My dog is cute.", "figure": "틀린 문장에 빨간 펜으로 대문자와 마침표를 고친 공책"}, {"heading": "be동사로 상태 말하기", "paras": ["'~이다, ~하다'처럼 상태를 말할 때는 am, is, are를 써요. I와는 am, he·she·it와는 is, you·we·they와는 are가 짝이에요.", "\"She is tall.(그녀는 키가 커.)\", \"We are friends.(우리는 친구야.)\"처럼 써요."], "example": "I am happy. / He is my brother. / They are students.", "figure": "I-am, he/she/it-is, you/we/they-are 짝꿍 카드 그림"}, {"heading": "묻는 문장과 부정하는 문장", "paras": ["묻는 문장은 끝에 물음표(?)를 붙여요. \"Are you hungry?\"처럼 be동사를 앞으로 보내거나, \"Do you like music?\"처럼 Do를 앞에 붙여요.", "'~하지 않다'는 not을 넣어요. \"I am not sad.\", \"I don't play the piano.\"처럼 써요."], "example": "You are tall. → Are you tall? / I like milk. → I don't like milk.", "figure": "물음표와 마침표가 문장 끝에서 손을 흔드는 그림"}], "keywords": [{"word": "주어", "meaning": "문장에서 '누가'에 해당하는 말. 예: I, She"}, {"word": "동사", "meaning": "문장에서 '한다'에 해당하는 말. 예: eat, play"}, {"word": "am / is / are", "meaning": "'~이다, ~하다'를 나타내는 말(be동사)"}, {"word": "마침표", "meaning": "문장 끝에 찍는 점(.)"}, {"word": "물음표", "meaning": "묻는 문장 끝에 붙이는 표시(?)"}], "expressions": [{"en": "I play soccer.", "ko": "나는 축구를 해.", "note": "누가 + 한다 + 무엇을"}, {"en": "She is tall.", "ko": "그녀는 키가 커."}, {"en": "We are friends.", "ko": "우리는 친구야."}, {"en": "Are you hungry?", "ko": "너 배고프니?", "note": "be동사를 앞으로 보내 묻기"}, {"en": "Do you like music?", "ko": "너는 음악을 좋아하니?", "note": "Do를 앞에 붙여 묻기"}, {"en": "I don't play the piano.", "ko": "나는 피아노를 치지 않아."}], "quiz": [{"q": "'나는 사과를 먹는다.'를 바른 순서로 쓴 것은?", "choices": ["I an apple eat.", "I eat an apple.", "Eat I an apple.", "An apple I eat."], "answer": 1, "explain": "영어는 누가(I) + 한다(eat) + 무엇을(an apple) 순서예요."}, {"q": "빈칸에 알맞은 말은? They ___ students.", "choices": ["am", "is", "be", "are"], "answer": 3, "explain": "they와 짝이 되는 be동사는 are예요."}, {"q": "바르게 쓴 문장은?", "choices": ["my sister is kind.", "My sister is kind", "My sister is kind.", "my Sister is kind."], "answer": 2, "explain": "첫 글자는 대문자, 끝에는 마침표를 찍어요."}, {"q": "\"He is happy.\"를 묻는 문장으로 바꾸면?", "choices": ["Is he happy?", "He is happy?", "Does he happy?", "Happy is he?"], "answer": 0, "explain": "be동사 is를 맨 앞으로 보내고 물음표를 붙여요."}, {"q": "'나는 우유를 좋아하지 않아.'를 영어로 하면?", "choices": ["I not like milk.", "I don't like milk.", "I am not like milk.", "Don't I like milk."], "answer": 1, "explain": "일반 동사(like) 앞에는 don't를 넣어 부정해요."}], "summary": ["영어 문장은 '누가 + 한다 + 무엇을' 순서로 만들어요.", "첫 글자는 대문자, 끝에는 마침표나 물음표를 붙이고, I는 항상 대문자예요.", "I-am, he/she/it-is, you/we/they-are로 짝을 맞추고, 부정은 not을 넣어요."], "parent_tip": "부모님께: 아이들은 우리말 순서대로 \"I apple eat\"처럼 쓰는 실수를 자주 합니다. 낱말 카드를 섞어 주고 바른 순서로 늘어놓는 놀이를 해 보세요. \"I am not\"과 \"I don't\"를 섞어 쓰는 경우도 많으니 be동사 문장과 일반 동사 문장을 구분해 짚어 주시면 좋습니다."}$json$::jsonb,163) on conflict (slug) do nothing;
update public.topics set lesson_slug='e5-03' where band='5~6' and subject='영어' and name='문장 만들기';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e5-04','5~6','영어','해야 할 일 말하기','해야 할 일과 하면 안 되는 일을 영어로 말해 볼까?','assets/img/l_e5-04.jpg',$json${"intro": "도서관에서는 조용히 해야 하고, 수영장에서는 뛰면 안 되죠? 지켜야 할 일과 해야 할 일을 영어로 말해 봐요.", "sections": [{"heading": "해야 할 일 말하기: should", "paras": ["'~해야 해'라고 말할 때는 should를 써요. \"You should wash your hands.(너는 손을 씻어야 해.)\"", "should 뒤에는 동사의 원래 모양을 그대로 써요. \"I should do my homework.(나는 숙제를 해야 해.)\""], "example": "You should wear a helmet. (헬멧을 써야 해.)", "figure": "자전거를 타기 전 헬멧을 쓰는 아이"}, {"heading": "하면 안 되는 일 말하기", "paras": ["'~하면 안 돼'라고 할 때는 should not을 줄인 shouldn't를 써요. \"You shouldn't run here.(여기서 뛰면 안 돼.)\"", "짧게 규칙을 말할 때는 \"Don't run.(뛰지 마.)\"처럼 Don't를 문장 맨 앞에 붙이기도 해요. \"Be quiet.(조용히 해.)\"처럼 동사로 바로 시작하는 문장도 있어요."], "example": "Don't run in the hallway. / Be quiet in the library.", "figure": "도서관 안내판에 'Be quiet', 수영장 안내판에 'Don't run'이 적힌 그림"}, {"heading": "무엇을 해야 하는지 묻기", "paras": ["\"What should I do?(나는 무엇을 해야 해?)\"라고 물어볼 수 있어요.", "감기에 걸린 친구에게는 \"You should get some rest.(좀 쉬어야 해.)\", \"You should see a doctor.(병원에 가 봐야 해.)\"처럼 조언해 줄 수 있어요."], "example": "I have a cold. - You should get some rest.", "figure": "이불을 덮고 누운 아이에게 친구가 조언하는 장면"}], "keywords": [{"word": "should", "meaning": "~해야 한다"}, {"word": "shouldn't", "meaning": "~하면 안 된다(should not의 줄임말)"}, {"word": "Don't ~", "meaning": "~하지 마"}, {"word": "rule", "meaning": "규칙"}, {"word": "quiet", "meaning": "조용한"}], "expressions": [{"en": "You should wash your hands.", "ko": "너는 손을 씻어야 해."}, {"en": "I should do my homework.", "ko": "나는 숙제를 해야 해."}, {"en": "You shouldn't run here.", "ko": "여기서 뛰면 안 돼."}, {"en": "Don't run.", "ko": "뛰지 마.", "note": "짧게 규칙을 말할 때"}, {"en": "Be quiet, please.", "ko": "조용히 해 주세요.", "note": "도서관 같은 곳에서"}, {"en": "What should I do?", "ko": "나는 무엇을 해야 해?"}, {"en": "You should see a doctor.", "ko": "병원에 가 봐야 해.", "note": "아픈 친구에게 조언할 때"}], "quiz": [{"q": "'너는 손을 씻어야 해.'를 영어로 하면?", "choices": ["You should wash your hands.", "You shouldn't wash your hands.", "Don't wash your hands.", "Should you wash your hands?"], "answer": 0, "explain": "'~해야 해'는 should를 써요."}, {"q": "도서관에서 지켜야 할 말로 알맞은 것은?", "choices": ["Run fast.", "Be quiet.", "Let's sing loudly.", "Eat pizza here."], "answer": 1, "explain": "도서관에서는 조용히(Be quiet) 해야 해요."}, {"q": "\"You shouldn't swim here.\"의 뜻은?", "choices": ["여기서 수영해야 해.", "여기서 수영하고 싶어.", "여기서 수영하면 안 돼.", "여기서 수영할 수 있어."], "answer": 2, "explain": "shouldn't는 '~하면 안 된다'는 뜻이에요."}, {"q": "빈칸에 알맞은 말은? You should ___ a helmet.", "choices": ["wearing", "wears", "to wear", "wear"], "answer": 3, "explain": "should 뒤에는 동사의 원래 모양(wear)을 써요."}, {"q": "\"I have a headache.(머리가 아파.)\"에 알맞은 조언은?", "choices": ["You should get some rest.", "You should run fast.", "Don't see a doctor.", "You should eat more candy."], "answer": 0, "explain": "아플 때는 쉬어야 한다고 조언하는 것이 알맞아요."}], "summary": ["해야 할 일은 should, 하면 안 되는 일은 shouldn't로 말해요.", "should 뒤에는 동사의 원래 모양을 써요.", "짧은 규칙은 Don't ~. 또는 Be quiet.처럼 동사로 시작해서 말해요."], "parent_tip": "부모님께: 아이들은 \"You should washes\"나 \"should to wash\"처럼 should 뒤에 동사를 바꿔 쓰는 실수를 자주 합니다. 집안 규칙을 영어로 함께 정해 보는 활동(예: You should brush your teeth.)을 해 보세요. 아이가 부모님께 조언하는 역할도 맡게 하면 더 재미있게 연습합니다."}$json$::jsonb,164) on conflict (slug) do nothing;
update public.topics set lesson_slug='e5-04' where band='5~6' and subject='영어' and name='해야 할 일 말하기';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e5-05','5~6','영어','지난 일 말하기','어제 한 일을 영어로 말해 볼까?','assets/img/l_e5-05.jpg',$json${"intro": "주말에 무엇을 했는지 친구에게 이야기하고 싶을 때가 있죠? 이미 지나간 일은 영어로 조금 다르게 말해요.", "sections": [{"heading": "지난 일은 동사 모양이 바뀌어요", "paras": ["어제나 지난주처럼 이미 지나간 일을 말할 때는 동사의 모양을 바꿔요. 이것을 과거형이라고 해요.", "대부분은 동사 뒤에 -ed를 붙여요. play → played, watch → watched, visit → visited처럼요."], "example": "I played soccer yesterday. (나는 어제 축구를 했어.)", "figure": "달력에서 어제 날짜에 축구공 스티커가 붙어 있는 그림"}, {"heading": "모양이 특별하게 바뀌는 동사", "paras": ["어떤 동사는 -ed를 붙이지 않고 모양이 완전히 바뀌어요. go → went, eat → ate, see → saw, have → had, make → made예요.", "이런 동사는 자주 쓰니까 짝을 지어 외워 두면 좋아요."], "example": "I went to the beach. I ate ice cream.", "figure": "go-went, eat-ate, see-saw 짝꿍 카드 그림"}, {"heading": "지난 일 묻고 답하기", "paras": ["\"What did you do yesterday?(너는 어제 무엇을 했니?)\"라고 물어요. did는 지난 일을 물을 때 쓰는 말이에요.", "대답은 과거형을 써서 \"I visited my grandma.(할머니 댁에 갔어.)\"처럼 해요. 때를 나타내는 말 yesterday(어제), last weekend(지난 주말)를 함께 쓰면 좋아요."], "example": "What did you do last weekend? - I went camping.", "figure": "텐트 앞에서 캠핑하는 가족 그림"}], "keywords": [{"word": "과거형", "meaning": "이미 지나간 일을 나타내는 동사 모양"}, {"word": "-ed", "meaning": "과거형을 만들 때 동사 뒤에 붙이는 말"}, {"word": "yesterday", "meaning": "어제"}, {"word": "last weekend", "meaning": "지난 주말"}, {"word": "did", "meaning": "지난 일을 물을 때 쓰는 말"}], "expressions": [{"en": "What did you do yesterday?", "ko": "너는 어제 무엇을 했니?", "note": "지난 일을 물을 때"}, {"en": "I played soccer.", "ko": "나는 축구를 했어."}, {"en": "I watched a movie.", "ko": "나는 영화를 봤어."}, {"en": "I went to the beach.", "ko": "나는 바닷가에 갔어."}, {"en": "I visited my grandma.", "ko": "나는 할머니 댁에 갔어."}, {"en": "I ate pizza.", "ko": "나는 피자를 먹었어."}, {"en": "It was fun!", "ko": "재미있었어!", "note": "지난 일에 대한 느낌을 말할 때"}], "quiz": [{"q": "play의 과거형은?", "choices": ["playing", "played", "plays", "plaied"], "answer": 1, "explain": "play 뒤에 -ed를 붙여 played가 돼요."}, {"q": "go의 과거형은?", "choices": ["goed", "gone", "went", "going"], "answer": 2, "explain": "go는 모양이 완전히 바뀌어 went가 돼요."}, {"q": "\"What did you do yesterday?\"에 알맞은 대답은?", "choices": ["I went to the zoo.", "I go to the zoo.", "I'm going to the zoo.", "It's sunny."], "answer": 0, "explain": "어제 한 일을 물었으니 과거형 went를 써서 대답해요."}, {"q": "\"I ate ice cream.\"의 뜻은?", "choices": ["나는 아이스크림을 먹을 거야.", "나는 아이스크림을 좋아해.", "나는 아이스크림을 먹고 있어.", "나는 아이스크림을 먹었어."], "answer": 3, "explain": "ate는 eat(먹다)의 과거형이에요."}, {"q": "빈칸에 알맞은 말은? I ___ a movie last weekend.", "choices": ["watch", "watched", "watches", "watching"], "answer": 1, "explain": "last weekend(지난 주말)는 지난 일이니 과거형 watched를 써요."}], "summary": ["지나간 일은 동사의 과거형으로 말해요. 대부분 -ed를 붙여요.", "go-went, eat-ate, see-saw처럼 모양이 바뀌는 동사도 있어요.", "지난 일은 What did you do ~?로 묻고 과거형으로 대답해요."], "parent_tip": "부모님께: 아이들은 \"goed\", \"eated\"처럼 모든 동사에 -ed를 붙이는 실수를 자주 합니다. 이는 규칙을 잘 이해했다는 신호이기도 하니 칭찬해 주시고, 특별한 동사만 따로 짝지어 알려 주세요. 저녁 식사 때 \"What did you do today?\"라고 물어 하루를 영어 한두 문장으로 말해 보게 하면 좋습니다."}$json$::jsonb,165) on conflict (slug) do nothing;
update public.topics set lesson_slug='e5-05' where band='5~6' and subject='영어' and name='지난 일 말하기';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e5-06','5~6','영어','장래 희망 말하기','나는 커서 무엇이 되고 싶을까?','assets/img/l_e5-06.jpg',$json${"intro": "의사, 요리사, 과학자… 여러분은 커서 무엇이 되고 싶나요? 장래 희망과 그 이유를 영어로 말해 봐요.", "sections": [{"heading": "직업을 나타내는 말", "paras": ["doctor(의사), teacher(선생님), cook(요리사), scientist(과학자), singer(가수), police officer(경찰관), pilot(조종사) 같은 말이 있어요.", "직업 이름 앞에는 보통 a를 붙여 a doctor, a teacher처럼 말해요. artist(화가)나 engineer(기술자)처럼 모음 소리로 시작하면 an을 붙여요."], "example": "a doctor, a cook, an artist, an engineer", "figure": "여러 직업 옷을 입은 아이들이 줄지어 선 그림"}, {"heading": "무엇이 되고 싶은지 말하기", "paras": ["\"I want to be a cook.(나는 요리사가 되고 싶어.)\"처럼 I want to be 뒤에 직업을 붙여요.", "친구에게 물을 때는 \"What do you want to be?(너는 무엇이 되고 싶니?)\"라고 해요."], "example": "What do you want to be? - I want to be a scientist.", "figure": "실험복을 입고 플라스크를 든 아이"}, {"heading": "이유 말하기", "paras": ["이유를 물을 때는 \"Why?(왜?)\"라고 하고, 대답은 because(왜냐하면)를 써요.", "\"I want to be a vet because I like animals.(나는 동물을 좋아해서 수의사가 되고 싶어.)\"처럼 말해요. 잘하는 것을 말할 때는 \"I'm good at drawing.(나는 그림을 잘 그려.)\"이라고 할 수 있어요."], "example": "Why? - Because I like cooking.", "figure": "강아지를 안고 있는 수의사 옷차림의 아이"}], "keywords": [{"word": "future", "meaning": "미래"}, {"word": "want to be", "meaning": "~이 되고 싶다"}, {"word": "because", "meaning": "왜냐하면, ~해서"}, {"word": "be good at", "meaning": "~을 잘하다"}, {"word": "job", "meaning": "직업"}], "expressions": [{"en": "What do you want to be?", "ko": "너는 무엇이 되고 싶니?", "note": "장래 희망을 물을 때"}, {"en": "I want to be a doctor.", "ko": "나는 의사가 되고 싶어."}, {"en": "I want to be an artist.", "ko": "나는 화가가 되고 싶어."}, {"en": "Why?", "ko": "왜?"}, {"en": "Because I like animals.", "ko": "왜냐하면 나는 동물을 좋아하거든.", "note": "이유를 말할 때"}, {"en": "I'm good at drawing.", "ko": "나는 그림을 잘 그려."}, {"en": "That's a great dream!", "ko": "멋진 꿈이야!", "note": "친구의 꿈을 응원할 때"}], "quiz": [{"q": "장래 희망을 물을 때 알맞은 말은?", "choices": ["What do you want to be?", "What did you do?", "What time is it?", "What color is it?"], "answer": 0, "explain": "want to be는 '~이 되고 싶다'예요."}, {"q": "'나는 요리사가 되고 싶어.'를 영어로 하면?", "choices": ["I like a cook.", "I am cook.", "I want to be a cook.", "I want to a cook."], "answer": 2, "explain": "I want to be + a + 직업으로 말해요."}, {"q": "빈칸에 알맞은 말은? I want to be ___ artist.", "choices": ["a", "an", "in", "on"], "answer": 1, "explain": "artist는 모음 소리로 시작하니 an을 써요."}, {"q": "이유를 말할 때 쓰는 말은?", "choices": ["but", "and", "or", "because"], "answer": 3, "explain": "because는 '왜냐하면'이라는 뜻이에요."}, {"q": "\"I'm good at singing.\"과 가장 어울리는 장래 희망은?", "choices": ["a singer", "a pilot", "a doctor", "a police officer"], "answer": 0, "explain": "노래를 잘하니 가수(singer)가 잘 어울려요."}], "summary": ["장래 희망은 What do you want to be?로 묻고 I want to be a ~.로 대답해요.", "직업 앞에는 a를, 모음 소리로 시작하면 an을 붙여요.", "이유는 because를 써서 말하고, 잘하는 것은 I'm good at ~.으로 말해요."], "parent_tip": "부모님께: 아이들은 \"I want to be doctor\"처럼 a를 빠뜨리는 경우가 많으니 직업 앞의 a/an을 짚어 주세요. 꿈을 영어로 말한 뒤 \"Why?\"라고 이유를 물어봐 주시면 because 문장을 만드는 연습이 되고, 아이가 자신의 관심사를 돌아보는 계기도 됩니다."}$json$::jsonb,166) on conflict (slug) do nothing;
update public.topics set lesson_slug='e5-06' where band='5~6' and subject='영어' and name='장래 희망 말하기';
insert into public.lessons (slug,band,subject,topic,title,hero_image,content,sort_order) values ('e5-07','5~6','영어','계획 말하기','이번 방학에 무엇을 할 거야? 계획을 영어로 말해 볼까?','assets/img/l_e5-07.jpg',$json${"intro": "곧 다가올 방학이나 주말에 하고 싶은 일이 있나요? 앞으로 할 일을 영어로 말하는 방법을 배워 봐요.", "sections": [{"heading": "앞으로 할 일: be going to", "paras": ["앞으로 할 계획을 말할 때는 \"I'm going to visit my uncle.(나는 삼촌 댁에 갈 거야.)\"처럼 be going to를 써요.", "be going to 뒤에는 동사의 원래 모양을 써요. I와는 am, he·she와는 is, you·we·they와는 are를 짝지어요."], "example": "I'm going to swim. / She is going to read books.", "figure": "수영복과 튜브를 챙기며 방학 계획을 세우는 아이"}, {"heading": "때를 나타내는 말", "paras": ["앞으로의 때를 말할 때는 tomorrow(내일), this weekend(이번 주말), next week(다음 주), this summer(이번 여름) 같은 말을 함께 써요.", "\"I'm going to go camping this weekend.(이번 주말에 캠핑을 갈 거야.)\"처럼 문장 끝에 붙이면 돼요."], "example": "this weekend, next week, tomorrow", "figure": "달력에 이번 주말, 다음 주가 색칠된 그림"}, {"heading": "계획 묻고 답하기", "paras": ["\"What are you going to do this weekend?(이번 주말에 무엇을 할 거니?)\"라고 물어요.", "\"Are you going to ~?\"로 물으면 \"Yes, I am.\" 또는 \"No, I'm not.\"으로 대답해요. 함께하자고 할 때는 \"Let's go together!(같이 가자!)\"라고 해요."], "example": "Are you going to play baseball? - Yes, I am.", "figure": "두 친구가 달력을 보며 주말 계획을 이야기하는 장면"}], "keywords": [{"word": "plan", "meaning": "계획"}, {"word": "be going to", "meaning": "~할 것이다, ~할 예정이다"}, {"word": "tomorrow", "meaning": "내일"}, {"word": "this weekend", "meaning": "이번 주말"}, {"word": "next week", "meaning": "다음 주"}], "expressions": [{"en": "What are you going to do this weekend?", "ko": "이번 주말에 무엇을 할 거니?", "note": "계획을 물을 때"}, {"en": "I'm going to visit my uncle.", "ko": "나는 삼촌 댁에 갈 거야."}, {"en": "I'm going to go camping.", "ko": "나는 캠핑을 갈 거야."}, {"en": "Are you going to swim?", "ko": "너 수영할 거니?"}, {"en": "Yes, I am.", "ko": "응, 그럴 거야."}, {"en": "No, I'm not.", "ko": "아니, 안 할 거야."}, {"en": "Let's go together!", "ko": "같이 가자!", "note": "함께하자고 할 때"}, {"en": "Have a nice weekend!", "ko": "주말 잘 보내!", "note": "헤어질 때"}], "quiz": [{"q": "앞으로의 계획을 물을 때 알맞은 말은?", "choices": ["What did you do?", "What are you going to do?", "What do you like?", "What time is it?"], "answer": 1, "explain": "be going to는 앞으로 할 일을 나타내요."}, {"q": "'나는 내일 책을 읽을 거야.'를 영어로 하면?", "choices": ["I read books yesterday.", "I'm reading books.", "I'm going to read books tomorrow.", "I read books tomorrow yesterday."], "answer": 2, "explain": "앞으로 할 일은 I'm going to + 동사 원래 모양으로 말해요."}, {"q": "빈칸에 알맞은 말은? She ___ going to visit Jeju.", "choices": ["is", "am", "are", "do"], "answer": 0, "explain": "she와 짝이 되는 be동사는 is예요."}, {"q": "\"Are you going to play soccer?\"에 '아니'라고 대답할 때는?", "choices": ["No, I don't.", "Yes, I am.", "No, you aren't.", "No, I'm not."], "answer": 3, "explain": "Are you ~?로 물었으니 No, I'm not.으로 대답해요."}, {"q": "미래의 때를 나타내는 말이 아닌 것은?", "choices": ["yesterday", "tomorrow", "next week", "this weekend"], "answer": 0, "explain": "yesterday(어제)는 지나간 때예요."}], "summary": ["앞으로의 계획은 be going to + 동사 원래 모양으로 말해요.", "tomorrow, this weekend, next week 같은 때를 나타내는 말을 함께 써요.", "What are you going to do?로 묻고, Are you going to ~?에는 Yes, I am./No, I'm not.으로 대답해요."], "parent_tip": "부모님께: 아이들은 지난 일(yesterday)과 앞으로의 일(tomorrow)에 쓰는 동사 모양을 섞어 쓰기 쉽습니다. 금요일 저녁에 \"What are you going to do this weekend?\"라고 묻고, 월요일에는 \"What did you do last weekend?\"라고 물어 과거와 미래를 비교해 보게 해 주세요."}$json$::jsonb,167) on conflict (slug) do nothing;
update public.topics set lesson_slug='e5-07' where band='5~6' and subject='영어' and name='계획 말하기';
